  'Free' => 'مجاني',
  '\\nFor professionals who want the complete, clean experience.\\n' => 'للمحترفين الذين يريدون تجربة كاملة ونظيفة.',
  '\\nEverything in Free Plus\\n' => 'كل شيء في Free Plus',
