  '\\npremium experience\\n' => 'تجربة متميزة',
  '\\nMost Popular\\n' => 'الأكثر شهرة',
  '\\nYou can change this at any time from the panel settings menu. No data is lost when you upgrade.\\n' => 'يمكنك تغيير ذلك في أي وقت من قائمة إعدادات اللوحة. لا يتم فقدان أية بيانات عند الترقية.',
  '\\nMaybe later\\n' => 'ربما لاحقاً',
  '\\nBuild professional WordPress forms in minutes. Choose how you\\\'d like to get started.\\n' => 'قم بإنشاء نماذج WordPress احترافية في دقائق. اختر الطريقة التي تريدها للبدء.',
  '[[\'Switch to Free Plus?\\n' => 'هل تريد التبديل إلى Free Plus؟',
  '\\nYour Pro activation code will be removed from this site. Pro add-ons will be unavailable until you upgrade again. Your forms, entries and settings will not be deleted.\\n' => 'ستتم إزالة رمز التفعيل الاحترافي الخاص بك من هذا الموقع. لن تكون الوظائف الإضافية الاحترافية متاحة حتى تقوم بالترقية مرة أخرى. لن يتم حذف النماذج والإدخالات والإعدادات الخاصة بك.',
  '\\nSwitch to Free?\\n' => 'هل تريد التبديل إلى الإصدار المجاني؟',
  '\\nAdvanced features and advanced fields used in your forms will be disabled. Your forms, entries and settings will not be deleted, and will be available again if you upgrade.\\n' => 'سيتم تعطيل الميزات المتقدمة والحقول المتقدمة المستخدمة في النماذج الخاصة بك. لن يتم حذف النماذج والإدخالات والإعدادات الخاصة بك، وستكون متاحة مرة أخرى إذا قمت بالترقية.',
  '\\nYour Pro activation code will be removed from this site. Advanced features, Pro fields and add-ons will be unavailable until you upgrade again. Your forms, entries and settings will not be deleted.\\n' => 'ستتم إزالة رمز التفعيل الاحترافي الخاص بك من هذا الموقع. لن تكون الميزات المتقدمة والحقول الاحترافية والوظائف الإضافية متاحة حتى تقوم بالترقية مرة أخرى. لن يتم حذف النماذج والإدخالات والإعدادات الخاصة بك.',
  '\\nKeepPro\\n' => 'KeepPro',
  '[[\'Keep Free Plus\\n' => 'احتفظ بميزة إضافية مجانية',
  '\\nSwitch to Free Plus\', \'en\']]' => 'التبديل إلى الإصدار المجاني الإضافي',
  '\\nSwitch to Free\\n' => 'التبديل إلى مجاني',
  '\\nPlan change\\n' => 'تغيير الخطة',
  '\\nYour data stays untouched; only access to the features is limited.\\n' => 'تبقى بياناتك دون تغيير؛ الوصول إلى الميزات فقط محدود.',
  '[[\'An error occurred. Please try again.\\n' => 'حدث خطأ. الرجاء المحاولة مرة أخرى.',
