  '\\nPlan selected\\n' => 'تم تحديد الخطة',
  '\\nSet up form notifications\\n' => 'إعداد إعلامات النموذج',
  '\\nCheck whether your server can send emails, so you know you will receive form notifications.\\n' => 'تحقق مما إذا كان بإمكان الخادم الخاص بك إرسال رسائل بريد إلكتروني، حتى تعرف أنك ستتلقى إشعارات النماذج.',
  '\\nForm notification email\\n' => 'البريد الإلكتروني لإشعار النموذج',
  '\\nThis is saved in General Settings and can be changed later.\\n' => 'يتم حفظ هذا في "الإعدادات العامة" ويمكن تغييره لاحقًا.',
  '\\nYour default settings\\n' => 'إعداداتك الافتراضية',
