  '\\nSave and test email delivery", \'en\']]' => 'حفظ واختبار تسليم البريد الإلكتروني"، \'ar\']]',
  '[[\'Checking email delivery...\\n' => 'جارٍ التحقق من تسليم البريد الإلكتروني...',
  '\\nA test email was sent. Waiting for delivery confirmation...\\n' => 'تم إرسال بريد إلكتروني تجريبي. في انتظار تأكيد التسليم...',
  '\\nEmail delivery is ready. Form notifications can be sent.\\n' => 'تسليم البريد الإلكتروني جاهز. يمكن إرسال إعلامات النموذج.',
  '\\nYour test email was sent, but delivery is not confirmed yet. Check the inbox or spam folder for the address below; you can finish setup and try again later from General Settings.\\n' => 'تم إرسال بريدك الإلكتروني التجريبي، ولكن لم يتم تأكيد التسليم بعد. تحقق من البريد الوارد أو مجلد البريد العشوائي بحثًا عن العنوان أدناه؛ يمكنك إنهاء الإعداد والمحاولة مرة أخرى لاحقاً من "الإعدادات العامة".',
  '[[\'We could not verify delivery. Your email address was saved; please check your mail configuration in General Settings.\\n' => 'لم نتمكن من التحقق من التسليم. تم حفظ عنوان بريدك الإلكتروني؛ الرجاء التحقق من تكوين البريد الخاص بك في "الإعدادات العامة".',
  '\\nYour test email was delivered, but its deliverability score is only%1$sout of 100 (below%2$s). The emails your forms send will most likely be filtered as spam. Set up SMTP and run the check again.\\n' => 'تم تسليم البريد الإلكتروني الاختباري الخاص بك، ولكن درجة التسليم الخاصة به هي%1$sفقط من 100 (أقل من%2$s). من المرجح أن تتم تصفية رسائل البريد الإلكتروني التي ترسلها النماذج الخاصة بك كرسائل غير مرغوب فيها. قم بإعداد SMTP ثم قم بتشغيل التحقق مرة أخرى.',
  '\\nFinish setup\\n' => 'إنهاء الإعداد',
