  '\\nForm does not exist !!\', \'en\']]' => 'النموذج غير موجود !!',
  '\\nYour security session has expired or is invalid. Please refresh the page. E403\\n' => 'لقد انتهت صلاحية جلسة الأمان الخاصة بك أو أنها غير صالحة. يرجى تحديث الصفحة. E403',
  '\\nYour security session has expired or is invalid. Please refresh the page. E400\\n' => 'لقد انتهت صلاحية جلسة الأمان الخاصة بك أو أنها غير صالحة. يرجى تحديث الصفحة. E400',
  '\\nThis is a private form. Please log in to access it.\\n' => 'هذا نموذج خاص. الرجاء تسجيل الدخول للوصول إليه.',
  '\\nPlease check the site key and secret key on Flux Forms panel > Settings > Google Keys to resolve the error.\', \'en\']]' => 'الرجاء التحقق من مفتاح الموقع والمفتاح السري في لوحة Flux Forms > الإعدادات > مفاتيح Google لحل الخطأ.',
  '\\nThere seems to be a problem with the Captcha. Please try again.\\n' => 'يبدو أن هناك مشكلة في اختبار Captcha. الرجاء المحاولة مرة أخرى.',
  '\\nYour account has been successfully created! You will receive an email containing your information\\n' => 'تم إنشاء حسابك بنجاح! ستتلقى بريدًا إلكترونيًا يحتوي على معلوماتك',
  '\\nThis username or password combination is incorrect.\\n' => 'تركيبة اسم المستخدم وكلمة المرور هذه غير صحيحة.',
  '\\nIf your email is valid, a new password will send to your email.\\n' => 'إذا كان بريدك الإلكتروني صالحًا، فسيتم إرسال كلمة مرور جديدة إلى بريدك الإلكتروني.',
  '\\nThe survey has been successfully completed.\\n' => 'تم إكمال الاستطلاع بنجاح.',
  '\\nSurvey Results Display\\n' => 'عرض نتائج الاستطلاع',
  '\\nDo not show results\\n' => 'عدم إظهار النتائج',
  '\\nShow results with bar chart\\n' => 'إظهار النتائج باستخدام المخطط الشريطي',
  '\\nShow results with pie chart\\n' => 'إظهار النتائج باستخدام مخطط دائري',
  '\\nAfter submission, visitors can see aggregate survey results\\n' => 'بعد الإرسال، يمكن للزائرين رؤية نتائج الاستطلاع المجمعة',
  '\\nShow this field in public survey results\\n' => 'إظهار هذا الحقل في نتائج الاستطلاع العام',
  '\\nSurvey Results\\n' => 'نتائج الاستطلاع',
  '\\nWe are sorry, but there seems to be a security error (405) with your request.\\n' => 'عذرًا، ولكن يبدو أن هناك خطأ أمني (405) في طلبك.',
  '\\nError, Setting not Found\\n' => 'خطأ، لم يتم العثور على الإعداد',
  '\\nSorry, there seems to be an error. Please verify that you are human and try again.\\n' => 'عذراً، يبدو أن هناك خطأ ما. الرجاء التحقق من أنك إنسان والمحاولة مرة أخرى.',
  '\\nPlease enter valid values\\n' => 'الرجاء إدخال قيم صالحة',
  '\\nInvalid Confirmation Code.\\n' => 'رمز التأكيد غير صالح.',
  '\\nThere seems to be an error with the file permissions.\\n' => 'يبدو أن هناك خطأ في أذونات الملف.',
  '\\nOops! Something went wrong. Please try refreshing the page and try again.\\n' => 'عفوا! حدث خطأ ما. الرجاء محاولة تحديث الصفحة والمحاولة مرة أخرى.',
  '[[\'HTML tags are not allowed.\\n' => 'علامات HTML غير مسموح بها.',
  '\\nYour message has been sent.\\n' => 'تم إرسال رسالتك.',
  '\\nWe have received your message.\\n' => 'لقد تلقينا رسالتك.',
  '\\nThe form has been submitted successfully\\n' => 'تم إرسال النموذج بنجاح',
  '\\nYour registration is successful.\\n' => 'تم التسجيل بنجاح.',
  'Welcome' => 'مرحبًا',
  '\\nYou have successfully subscribed. Thank you!\\n' => 'لقد قمت بالاشتراك بنجاح. شكرا لك!',
  '\\nThank You for taking the time to complete this survey.\\n' => 'شكرًا لك على الوقت الذي أمضيته في إكمال هذا الاستطلاع.',
  '\\nPlease go to Panel > Settings > Email Settings, click "Check Email Server", then click "Save".\\n' => 'يُرجى الانتقال إلى اللوحة > الإعدادات > إعدادات البريد الإلكتروني، ثم النقر فوق "التحقق من خادم البريد الإلكتروني"، ثم النقر فوق "حفظ".',
  '\\nUh oh, looks like there is a problem with the form. Please make sure all of the input is correct.\\n' => 'آه، يبدو أن هناك مشكلة في النموذج. الرجاء التأكد من صحة كافة الإدخالات.',
  '\\nThe form was not created\\n' => 'لم يتم إنشاء النموذج',
  '\\nScripts tags are not allowed.\\n' => 'علامات البرامج النصية غير مسموح بها.',
  '\\nBootstrap Template\\n' => 'قالب التمهيد',
  '\\nWarning: If your theme uses Bootstrap, make sure the option below is enabled.\\n' => 'تحذير: إذا كان القالب الخاص بك يستخدم Bootstrap، فتأكد من تمكين الخيار أدناه.',
  '\\nMy theme is based on Bootstrap\\n' => 'يعتمد موضوعي على Bootstrap',
  '\\nUh oh, it looks like there is a problem with your request. Please review everything and try again.\\n' => ' اه، يبدو أن هناك مشكلة في طلبك. الرجاء مراجعة كل شيء والمحاولة مرة أخرى.',
  'updated' => 'محدث',
  '\\nPlease type in your message\', \'en\']]' => 'الرجاء كتابة رسالتك',
  '\\nThe files have been deleted.\\n' => 'تم حذف الملفات.',
  '\\nThe activation code you entered is incorrect. Please double-check and try again.\\n' => 'رمز التفعيل الذي أدخلته غير صحيح. الرجاء التحقق مرة أخرى والمحاولة مرة أخرى.',
  '\\nWe are sorry, but the message was not sent due to a settings error. Please contact the admin for assistance.\\n' => 'عذرًا، لم يتم إرسال الرسالة بسبب خطأ في الإعدادات. الرجاء الاتصال بالمسؤول للحصول على المساعدة.',
  '\\nOR\\n' => 'أو',
  '\\nEmail Template\\n' => 'قالب البريد الإلكتروني',
  '\\nreset\\n' => 'reset',
  '\\nNot Found\\n' => 'لم يتم العثور',
  '\\nEditor\\n' => 'محرر',
  '\\nPlease add the shortcode_message shortcode to the email template.\\n' => 'الرجاء إضافة الرمز القصير Shortcode_message إلى قالب البريد الإلكتروني.',
  '\\nYour Email Template cannot exceed 10,000 characters.\\n' => 'لا يمكن أن يتجاوز قالب البريد الإلكتروني الخاص بك 10000 حرف.',
  '\\nPlease use HTML tags to create your email template.\\n' => 'الرجاء استخدام علامات HTML لإنشاء قالب البريد الإلكتروني الخاص بك.',
  '\\nAdd this shortcode inside a tag to display the title of the email.\\n' => 'أضف هذا الرمز القصير داخل علامة لعرض عنوان البريد الإلكتروني.',
  '\\nAdd this shortcode inside an HTML tag to display the message content of an email.\\n' => 'أضف هذا الرمز القصير داخل علامة HTML لعرض محتوى رسالة البريد الإلكتروني.',
  '\\nTo display the website name, add this shortcode inside an HTML tag.\\n' => 'لعرض اسم موقع الويب، قم بإضافة هذا الرمز القصير داخل علامة HTML.',
  '\\nAdd this shortcode within an HTML tag to display the Website URL.\\n' => 'أضف هذا الرمز القصير ضمن علامة HTML لعرض عنوان URL لموقع الويب.',
  '\\nYou can display the Admin Email address of your WordPress site by adding this shortcode within an HTML tag.\\n' => 'يمكنك عرض عنوان البريد الإلكتروني للمسؤول لموقع WordPress الخاص بك عن طريق إضافة هذا الرمز القصير ضمن علامة HTML.',
  'Templates' => 'قوالب',
  '\\nMax selection\\n' => 'الحد الأقصى للاختيار',
  '\\nMin selection\\n' => 'الحد الأدنى للاختيار',
  '\\nDo not show the background.\\n' => 'عدم إظهار الخلفية.',
