  '\\nError: No payment gateway has been added to the form.\\n' => 'خطأ: لم تتم إضافة بوابة دفع إلى النموذج.',
  '\\nYour cart is currently empty. Please add items to continue.\\n' => 'عربة التسوق الخاصة بك فارغة حاليا. الرجاء إضافة عناصر للمتابعة.',
