  '\\nPublic Key\', \'en\']]' => 'المفتاح العام',
  'Price' => 'السعر',
  'title' => 'عنوان',
  'Medium' => 'متوسط',
  '\\nXSmall\\n' => 'صغير جدًا',
  '\\nXXSmall\\n' => 'صغير جدًا',
  '\\nCreate a payment form to collect online payments.\\n' => 'قم بإنشاء نموذج دفع لجمع الدفعات عبر الإنترنت.',
  '\\nSubmit\\n' => 'إرسال',
  '\\nPurchase Order\\n' => 'أمر الشراء',
  '\\nIt is not possible to include reCAPTCHA on payment forms.\\n' => 'لا يمكن تضمين reCAPTCHA في نماذج الدفع.',
  '\\nThis site can send emails\\n' => 'يمكن لهذا الموقع إرسال رسائل بريد إلكتروني',
  '\\nWeekly email health and form activity report\\n' => 'تقرير أسبوعي عن سلامة البريد الإلكتروني ونشاط النموذج',
  '\\nAdds your form activity totals – forms, views and submissions – to the weekly email your site sends the main administrator. These totals are read on your own site and are never sent to WhiteStudio.\\n' => 'يضيف إجمالي نشاط النموذج - النماذج وطرق العرض والإرسالات - إلى البريد الإلكتروني الأسبوعي الذي يرسله موقعك إلى المسؤول الرئيسي. تتم قراءة هذه الإجماليات على موقعك الخاص ولا يتم إرسالها مطلقًا إلى WhiteStudio.',
  'Last check: %s' => 'الفحص الأخير: %s',
  '\\nNo automated email check has run yet.\\n' => 'لم يتم تشغيل أي فحص تلقائي للبريد الإلكتروني حتى الآن.',
  '\\nCollect email delivery statistics\\n' => 'تجميع إحصائيات تسليم البريد الإلكتروني',
  '\\nCounts how many emails were sent or failed, shows them in the dashboard widget, and adds the email delivery status section to the weekly email. Once a week your site runs a delivery test and reports the result. Only Pro users can turn this off.\\n' => 'يحسب عدد رسائل البريد الإلكتروني التي تم إرسالها أو الفاشلة، ويعرضها في أداة لوحة المعلومات، ويضيف قسم حالة تسليم البريد الإلكتروني إلى البريد الإلكتروني الأسبوعي. يجري موقعك اختبار التسليم مرة واحدة في الأسبوع ويبلغ عن النتيجة. يمكن لمستخدمي Pro فقط إيقاف تشغيل هذا.',
  'Actions' => 'الإجراءات',
  '\\nInterval\\n' => 'الفاصل الزمني',
  '[[\'Next Billing Date\\n' => 'تاريخ الفاتورة التالي',
  'Daily' => 'يوميا',
  'Monthly' => 'شهريا',
  'Weekly' => 'أسبوعيا',
  '\\nYearly\\n' => 'سنوياً',
  '\\nHow to activate the Pro version of Flux Forms\\n' => 'كيفية تنشيط الإصدار الاحترافي من Flux Forms',
  '\\nUploaded File\\n' => 'الملف الذي تم تحميله',
  '\\nYour internet connection has been lost, but do not worry, we have saved the information you entered on this form. Once you are reconnected to the internet, you can easily send your information by clicking the submit button.\\n' => 'لقد انقطع اتصالك بالإنترنت، لكن لا تقلق، فقد قمنا بحفظ المعلومات التي أدخلتها في هذا النموذج. بمجرد إعادة اتصالك بالإنترنت، يمكنك إرسال معلوماتك بسهولة عن طريق النقر فوق الزر "إرسال".',
  '\\nPlease ensure that you have a stable internet connection and try again.\\n' => 'يُرجى التأكد من توفر اتصال ثابت بالإنترنت والمحاولة مرة أخرى.',
  '\\nThere was a problem uploading the file and the form was not submitted. Please check that your internet connection is stable and try again.\\n' => 'حدثت مشكلة أثناء تحميل الملف ولم يتم إرسال النموذج. الرجاء التأكد من أن اتصالك بالإنترنت مستقر ثم حاول مرة أخرى.',
  'Options' => 'خيارات',
  '\\nYou are experiencing issues with jQuery. Please contact the administrator for assistance. (Error code: JQ-500)\\n' => 'أنت تواجه مشكلات مع jQuery. الرجاء الاتصال بالمسؤول للحصول على المساعدة. (رمز الخطأ: JQ-500)',
  '\\nYour session has expired. Please refresh the page and try again.\\n' => 'لقد انتهت صلاحية جلسة العمل الخاصة بك. الرجاء تحديث الصفحة والمحاولة مرة أخرى.',
  '\\nBasic\\n' => 'أساسي',
  'Blank' => 'فارغ',
  '\\nSign-In|Up\\n' => 'تسجيل الدخول|التسجيل',
  '\\nAdvance\\n' => 'تقدم',
  'All' => 'الكل',
  '\\nThank you Page\\n' => 'صفحة شكرا',
  '\\nRedirect page\\n' => 'إعادة توجيه الصفحة',
  '\\nPlease wait, you will be redirected shortly.\\n' => 'الرجاء الانتظار، سيتم إعادة توجيهك قريباً.',
  '\\nPersia payment\\n' => 'الدفع في بلاد فارس',
  '[[\'Unlock Pro Features Today\\n' => 'افتح الميزات الاحترافية اليوم',
  '\\nUpgrade to Pro for just%1$s%2$s%3$s/year and get access to powerful features, including advanced form fields, payment integrations, conditional logic, multi-step forms, file uploads, Security & Spam Protection, and priority support.%4$sView Pro Features%5$s\\n' => 'قم بالترقية إلى Pro مقابل%1$s%2$s%3$s/سنة فقط واحصل على إمكانية الوصول إلى الميزات القوية، بما في ذلك حقول النماذج المتقدمة وعمليات تكامل الدفع والمنطق الشرطي والنماذج متعددة الخطوات وتحميل الملفات والأمان والحماية من البريد العشوائي والدعم ذي الأولوية. ميزات عرض %4$sPro%5$s',
  '\\nAdd-on\\n' => 'إضافة',
  '\\nAdd-ons\\n' => 'الإضافات',
  '[[\'Stripe Payment Add-on\\n' => 'وظيفة إضافية للدفع الشريطي',
  '\\nThe Stripe add-on for Flux Forms enables you to integrate your WordPress site with Stripe for payment processing, donations, and online orders.\\n' => 'تمكنك الوظيفة الإضافية Stripe لـ Flux Forms من دمج موقع WordPress الخاص بك مع Stripe لمعالجة الدفع والتبرعات والطلبات عبر الإنترنت.',
  '[[\'Offline Forms Add-on\\n' => 'الوظيفة الإضافية للنماذج دون اتصال',
  '\\nThe Offline Forms add-on for Flux Forms allows users to save their progress when filling out forms in offline situations.\\n' => 'تسمح الوظيفة الإضافية "النماذج دون اتصال" لـ Flux Forms للمستخدمين بحفظ تقدمهم عند ملء النماذج في المواقف دون اتصال.',
  'Install' => 'تثبيت',
  '[["Please update Flux Forms before trying again.\\n' => 'الرجاء تحديث Flux Forms قبل المحاولة مرة أخرى.',
  '\\nActivation of offline form mode.\\n' => 'تنشيط وضع النموذج دون اتصال.',
  '\\nBefore activating this option, install\\n' => 'قبل تنشيط هذا الخيار، قم بتثبيت',
  '\\nTo create a payment form to collect online payments, you must first install a payment add-on such as the Stripe Add-on.\\n' => 'لإنشاء نموذج دفع لجمع الدفعات عبر الإنترنت، يجب عليك أولاً تثبيت وظيفة إضافية للدفع مثل الوظيفة الإضافية Stripe.',
  '\\nAll formats\\n' => 'كافة التنسيقات',
  '\\nEFB SMS Add-on\\n' => 'وظيفة EFB الإضافية للرسائل النصية القصيرة',
  '\\nEnable SMS functionality in your forms with the EFB SMS add-on, allowing you to validate mobile numbers and send confirmation codes via SMS, as well as receive notifications through SMS service.\\n' => 'قم بتمكين وظيفة الرسائل القصيرة SMS في النماذج الخاصة بك باستخدام الوظيفة الإضافية لـ EFB SMS، مما يسمح لك بالتحقق من صحة أرقام الهاتف المحمول وإرسال رموز التأكيد عبر الرسائل القصيرة، بالإضافة إلى تلقي الإشعارات من خلال خدمة الرسائل القصيرة.',
  '\\nAdvanced confirmation code Add-on\\n' => 'الوظيفة الإضافية لرمز التأكيد المتقدم',
  '\\nSend a confirmation code via email or SMS to users and/or admins, allowing them to quickly access new responses.\\n' => 'أرسل رمز التأكيد عبر البريد الإلكتروني أو الرسائل النصية القصيرة إلى المستخدمين و/أو المسؤولين، مما يسمح لهم بالوصول بسرعة إلى الردود الجديدة.',
  '\\nBox Checklist\\n' => 'قائمة اختيار المربع',
  '\\nRadio Checklist\\n' => 'قائمة اختيار الراديو',
  'Qty' => 'الكمية',
  '\\nThis is a warning for WPBakery users. For more information, please click here.\\n' => 'هذا تحذير لمستخدمي WPBakery. لمزيد من المعلومات، الرجاء النقر هنا.',
  '\\nAre you sure you want to close replies to this message?\\n' => 'هل تريد بالتأكيد إغلاق الردود على هذه الرسالة؟',
  '\\nAre you sure you want to open the responses to this message?\\n' => 'هل أنت متأكد أنك تريد فتح الردود على هذه الرسالة؟',
  '\\nThe response has been closed by Admin.\\n' => 'تم إغلاق الاستجابة من قبل المسؤول.',
  '\\nThe response has been opened by Admin.\\n' => 'تم فتح الرد بواسطة المسؤول.',
  'Open' => 'مفتوح',
  '\\n$NN/year\\n' => '$NN/السنة',
  '\\ncolumns\\n' => 'أعمدة',
  '\\ncolumn\\n' => 'عمود',
  '\\nI would like to localize Flux Forms.\\n' => 'أرغب في ترجمة Flux Forms.',
  '\\nMax length\\n' => 'أقصى طول',
  '\\nMin length\\n' => 'الطول الأدنى',
  '\\nThe maximum number of characters allowed in the input element is 524288\\n' => 'الحد الأقصى لعدد الأحرف المسموح به في عنصر الإدخال هو 524288',
  '\\nPlease enter a value that is at least NN characters long.\\n' => 'الرجاء إدخال قيمة لا يقل طولها عن أحرف NN.',
  '\\nPlease enter a number that is greater than or equal to NN.\\n' => 'الرجاء إدخال رقم أكبر من أو يساوي NN.',
  '\\nPlease Enter a maximum of NN Characters For this field\\n' => 'الرجاء إدخال الحد الأقصى لعدد أحرف NN لهذا الحقل',
