  '\\nHijri Date\\n' => 'التاريخ الهجري',
  '\\nInstall the add-on\\n' => 'قم بتثبيت الوظيفة الإضافية',
  '\\nPlease go to the Add-ons Page of Flux Forms plugin and install the Jalili date addons\\n' => 'الرجاء الانتقال إلى صفحة الوظائف الإضافية للمكون الإضافي Flux Forms وتثبيت إضافات تاريخ Jalili',
  '\\nPlease go to the Add-ons Page of Flux Forms plugin and install the Hijri date addons\\n' => 'الرجاء الانتقال إلى صفحة الإضافات الخاصة بالمكون الإضافي Flux Forms وتثبيت الإضافات الخاصة بالتاريخ الهجري',
  'warning' => 'تحذير',
  '\\ndate & time\\n' => 'التاريخ والوقت',
  '\\nEnable file upload in the response box\\n' => 'تمكين تحميل الملف في مربع الاستجابة',
  '\\nEnable Google reCAPTCHA in the response box\\n' => 'قم بتمكين Google reCAPTCHA في مربع الاستجابة',
  '\\nEnable download button in the response box\\n' => 'تمكين زر التنزيل في مربع الاستجابة',
  '\\nDisplay the IP addresses of users in the response box.\\n' => 'عرض عناوين IP الخاصة بالمستخدمين في مربع الاستجابة.',
  '\\nPersia Payment Add-on\\n' => 'الوظيفة الإضافية للدفع في بلاد فارس',
  '\\nThe Persia payment add-on for Flux Forms enables you to connect your website with Persia payment to process payments, donations, and online orders.\\n' => 'تمكنك الوظيفة الإضافية للدفع في بلاد فارس لـ Flux Forms من ربط موقع الويب الخاص بك مع خدمة الدفع في بلاد فارس لمعالجة الدفعات والتبرعات والطلبات عبر الإنترنت.',
  '\\nJalali Date Add-on\\n' => 'إضافة تاريخ جلالي',
  '\\nThe Jalali Date add-on allows you to add a Jalali date field to your forms and create any type of form that includes this Shamsi date field.\\n' => 'تسمح لك الوظيفة الإضافية لتاريخ جلالي بإضافة حقل تاريخ جلالي إلى النماذج الخاصة بك وإنشاء أي نوع من النماذج يتضمن حقل تاريخ شمسي هذا.',
  '\\nHijri Date Add-on\\n' => 'إضافة التاريخ الهجري',
  '\\nThe Hijri Date add-on allows you to add a Hijri date field to your forms and create any type of form that includes this field.\\n' => 'تسمح لك الوظيفة الإضافية للتاريخ الهجري بإضافة حقل التاريخ الهجري إلى النماذج الخاصة بك وإنشاء أي نوع من النماذج يتضمن هذا الحقل.',
  '\\nSMS service Add-on\\n' => 'الوظيفة الإضافية لخدمة الرسائل القصيرة',
  '\\nThe SMS service add-on enables you to receive notification SMS messages when you or your customers receive new messages or responses.\\n' => 'تمكنك الوظيفة الإضافية لخدمة SMS من تلقي إشعارات عبر رسائل SMS عندما تتلقى أنت أو عملاؤك رسائل أو استجابات جديدة.',
  '\\nPlease install either the Hijri or Jalali date add-on. You cannot install both add-ons simultaneously.\\n' => 'يرجى تثبيت إضافة التاريخ الهجري أو الجلالي. لا يمكنك تثبيت كلتا الوظيفتين الإضافيتين في وقت واحد.',
  '\\nResponse box\\n' => 'مربع الاستجابة',
  '\\nRegions Drop-Down\\n' => 'القائمة المنسدلة للمناطق',
  '\\nYou are seeing this message because your required add-ons are being installed. Please wait a few minutes and then visit this page again. If it has been more than five minutes and nothing has happened, please contact the support team of Flux Forms at Whitestudio.team.\\n' => 'تظهر لك هذه الرسالة لأنه يتم الآن تثبيت الوظائف الإضافية المطلوبة. يرجى الانتظار بضع دقائق ثم قم بزيارة هذه الصفحة مرة أخرى. إذا مر أكثر من خمس دقائق ولم يحدث شيء، فيرجى الاتصال بفريق دعم Flux Forms على Whitestudio.team.',
  '\\nThe cell phone number is incorrect\\n' => 'رقم الهاتف الخليوي غير صحيح',
  '\\nInvalid country code\\n' => 'رمز البلد غير صالح',
  '\\nThe cell phone number is too short\\n' => 'رقم الهاتف الخلوي قصير جدًا',
  '\\nThe cell phone number is too long\\n' => 'رقم الهاتف الخلوي طويل جدًا',
  '\\nPlease select the number of countries to display within an acceptable range.\\n' => 'الرجاء تحديد عدد البلدان التي سيتم عرضها ضمن نطاق مقبول.',
  '\\nDisabled Field\\n' => 'حقل معطل',
  '\\nHidden Field\\n' => 'حقل مخفي',
  '[[\'Select a country to display a list of states/provinces.\\n' => 'حدد بلدًا لعرض قائمة الولايات/المقاطعات.',
  '\\nSelect a state/province to display a list of cities.\\n' => 'حدد ولاية/مقاطعة لعرض قائمة المدن.',
  '\\nSMS Service Add-on\\n' => 'الوظيفة الإضافية لخدمة الرسائل القصيرة',
  '[["This field is currently unavailable. Please contact the site administrator.\\n' => 'هذا الحقل غير متوفر حاليًا. الرجاء الاتصال بمسؤول الموقع.',
  '\\nWould you like to customize the form using the colors of the active template?\\n' => 'هل ترغب في تخصيص النموذج باستخدام ألوان القالب النشط؟',
  '\\nFlux Forms has utilized the colors of the active template. Please choose a color for each option below to customize the form you are creating based on the colors of your template. By selecting a color for each option below, the color of all form fields associated with that feature will change accordingly.\', \'en\']]' => 'لقد استخدمت Flux Forms ألوان القالب النشط. يرجى اختيار لون لكل خيار أدناه لتخصيص النموذج الذي تقوم بإنشائه بناءً على ألوان القالب الخاص بك. من خلال تحديد لون لكل خيار أدناه، سيتم تغيير لون جميع حقول النموذج المرتبطة بهذه الميزة وفقًا لذلك.',
  '\\nButtons text colors\\n' => 'ألوان نص الأزرار',
