  '\\nThe ID value must be unique, as it is already being used in this field. Please try a new, unique value.\\n' => 'يجب أن تكون قيمة المعرف فريدة، حيث إنها مستخدمة بالفعل في هذا الحقل. الرجاء تجربة قيمة جديدة وفريدة.',
