  '\\nTo use this option, please install the NN add-ons from the Flux Forms plugin\\\'s add-ons page.\\n' => 'لاستخدام هذا الخيار، الرجاء تثبيت وظائف NN الإضافية من صفحة الوظائف الإضافية الخاصة ببرنامج Flux Forms.',
  '\\nSMS Notifications\\n' => 'إشعارات الرسائل القصيرة',
