  '[[\'All SMS notifications sent by Flux Forms will be delivered to the numbers entered here.\\n' => 'سيتم تسليم جميع إشعارات الرسائل القصيرة المرسلة بواسطة Flux Forms إلى الأرقام المدخلة هنا.',
  '\\nChoose Email notification content\\n' => 'اختر محتوى إشعار البريد الإلكتروني',
  '\\nSend email with confirmation code and link\\n' => 'أرسل بريدًا إلكترونيًا يتضمن رمز التأكيد والرابط',
  '\\nSend email with submitted form content and link\', \'en\']]' => 'أرسل بريدًا إلكترونيًا يتضمن محتوى النموذج المقدم ورابطًا',
