  '\\nYou are offline. Please reconnect and upload the recording again.\\n' => 'أنت غير متصل. الرجاء إعادة الاتصال وتحميل التسجيل مرة أخرى.',
  '\\nUploading is not available right now. Please try again.\\n' => 'التحميل غير متاح الآن. الرجاء المحاولة مرة أخرى.',
  '\\nNo recording is ready to upload.\\n' => 'لا يوجد تسجيل جاهز للتحميل.',
  '\\nThe recording is larger than the allowed file size.\\n' => 'التسجيل أكبر من حجم الملف المسموح به.',
  '\\nThis recording format is not allowed.\\n' => 'تنسيق التسجيل هذا غير مسموح به.',
  '\\nThe recording is longer than the allowed duration.\\n' => 'التسجيل أطول من المدة المسموح بها.',
  '\\nRecording Quality\\n' => 'جودة التسجيل',
  '\\nMax Duration (seconds)\\n' => 'المدة القصوى (بالثواني)',
  'Low' => 'منخفض',
