  '\\n720p (HD)\\n' => '720p (عالية الدقة)',
  '\\n1080p (Full HD)\\n' => '1080p (الدقة العالية الكاملة)',
  '\\nPermission to access your microphone/camera/screen was denied.\\n' => 'تم رفض إذن الوصول إلى الميكروفون/الكاميرا/الشاشة.',
  '\\nYour browser does not support this recording feature.\\n' => 'المستعرض الذي تستخدمه لا يدعم ميزة التسجيل هذه.',
  '\\nMaximum recording duration reached.\\n' => 'تم الوصول إلى الحد الأقصى لمدة التسجيل.',
  '\\nMade by Flux Forms\\n' => 'تم إنشاؤه بواسطة Flux Forms',
  '\\nTap to start recording\\n' => 'انقر لبدء التسجيل',
  '\\nDownload recording\\n' => 'تنزيل التسجيل',
  '\\nRecording requires a secure (HTTPS) connection. Please ask the site administrator to enable HTTPS on this host.\\n' => 'يتطلب التسجيل اتصالاً آمنًا (HTTPS). الرجاء مطالبة مسؤول الموقع بتمكين HTTPS على هذا المضيف.',
  '\\nScreen recording is not supported on this device or browser (most mobile browsers do not allow it). Please open the form in a desktop browser such as Chrome, Edge or Firefox.\\n' => 'تسجيل الشاشة غير مدعوم على هذا الجهاز أو المتصفح (معظم متصفحات الجوال لا تسمح بذلك). الرجاء فتح النموذج في متصفح سطح المكتب مثل Chrome أو Edge أو Firefox.',
  '\\nCountdown before recording\\n' => 'العد التنازلي قبل التسجيل',
  '\\nDefault camera (mobile)\\n' => 'الكاميرا الافتراضية (الجوال)',
  '\\nFront (selfie)\\n' => 'الأمامية (صورة شخصية)',
  '\\nBack (environment)\\n' => 'الرجوع (البيئة)',
