  '\\nShow watermark on the preview\\n' => 'إظهار العلامة المائية في المعاينة',
  '\\nLet the user download a copy of the recording\\n' => 'السماح للمستخدم بتنزيل نسخة من التسجيل',
  '\\nYour hosting accepts uploads up to%sMB.\\n' => 'تقبل استضافتك عمليات تحميل تصل إلى%sميغابايت.',
  '\\nThis is larger than the hosting upload limit (%sMB); uploads will fail.\\n' => 'هذا أكبر من حد تحميل الاستضافة (%sMB)؛ ستفشل عمليات التحميل.',
  '\\nCities Drop-Down\\n' => 'القائمة المنسدلة للمدن',
