  '\\nNo data available for this period\\n' => 'لا توجد بيانات متاحة لهذه الفترة',
  '\\nThe entered data does not match the form type. If you are an admin, please review the form type.\', \'en\']]' => 'البيانات المدخلة غير متطابقة مع نوع النموذج. إذا كنت مسؤولاً، يرجى مراجعة نوع النموذج.',
  '\\nError: Please ensure there is only one form per page.\\n' => 'خطأ: الرجاء التأكد من وجود نموذج واحد فقط في كل صفحة.',
  '\\nYour activation code has been verified. Enjoy all Pro features of Flux Forms.", \'en\']]' => 'تم التحقق من رمز التفعيل الخاص بك. استمتع بجميع الميزات الاحترافية لـ Flux Forms.',
  '\\nThe confirmation code for this message is%s. By clicking the button below, you will be able to track messages and view received responses. If needed, you can also send a new reply.\\n' => 'رمز التأكيد لهذه الرسالة هو%s. بالنقر على الزر أدناه، ستتمكن من تتبع الرسائل وعرض الردود المستلمة. إذا لزم الأمر، يمكنك أيضًا إرسال رد جديد.',
  '\\nTo explore the full functionality and settings of Flux Forms, including email configurations, form creation options, and other features, simply delve into our%1$sdocumentation%2$s.\\n' => 'لاستكشاف الوظائف والإعدادات الكاملة لـ Flux Forms، بما في ذلك تكوينات البريد الإلكتروني وخيارات إنشاء النماذج والميزات الأخرى، ما عليك سوى التعمق في وثائق%1$sالخاصة بنا%2$s.',
  '\\nResponses & Confirmation\\n' => 'الردود والتأكيد',
  '\\nTest emails may land in your spam folder. If emails are not delivered, this is usually related to your hosting or email server configuration.server settings%1$sLearn how to fix email delivery issues%2$sor%3$scontact Flux Forms support%4$s.\\n' => 'قد تصل رسائل البريد الإلكتروني الاختبارية إلى مجلد الرسائل غير المرغوب فيها. إذا لم يتم تسليم رسائل البريد الإلكتروني، فهذا عادةً ما يرتبط بتكوين خادم الاستضافة أو البريد الإلكتروني. إعدادات الخادم%1$sتعرف على كيفية إصلاح مشكلات تسليم البريد الإلكتروني%2$sأو%3$sاتصل بدعم Flux Forms%4$s.',
  '\\nFrom Address\\n' => 'من العنوان',
  '\\nMake sure this email address matches the one configured in your SMTP settings to prevent email delivery issues.\\n' => 'تأكد من تطابق عنوان البريد الإلكتروني هذا مع العنوان الذي تم تكوينه في إعدادات SMTP لديك لمنع حدوث مشكلات في تسليم البريد الإلكتروني.',
  '\\nTo preview the form, you need to save the built form and try again.\\n' => 'لمعاينة النموذج، تحتاج إلى حفظ النموذج الذي تم إنشاؤه والمحاولة مرة أخرى.',
  '\\nNo selected rows found.\\n' => 'لم يتم العثور على صفوف محددة.',
  '\\nMark as Read\\n' => 'وضع علامة "مقروءة"',
  '\\nRequire admin login to view responses\\n' => 'يتطلب تسجيل دخول المسؤول لعرض الاستجابات',
  '\\nDevelopment Mode (Sandbox)\\n' => 'وضع التطوير (وضع الحماية)',
  '\\nWhen enabled, uses sandbox/demo servers for PayPal and other services. Disable for production.\\n' => 'عند التمكين، يتم استخدام خوادم وضع الحماية/التجريبية لـ PayPal والخدمات الأخرى. تعطيل للإنتاج.',
  '\\nAfter changing the Development Mode (Sandbox) option, save the settings, then deactivate and reactivate Flux Forms plugin from the Plugins page for the changes to take effect.\\n' => 'بعد تغيير خيار وضع التطوير (Sandbox)، احفظ الإعدادات، ثم قم بإلغاء تنشيط المكون الإضافي Flux Forms وإعادة تنشيطه من صفحة المكونات الإضافية حتى تدخل التغييرات حيز التنفيذ.',
  '\\nI have read and agree to%1$sthe terms and conditions%2$s\\n' => 'لقد قرأت ووافقت على شروط وأحكام%1$s%2$s',
  '\\nTerms\\n' => 'الشروط',
  '\\nPreview in new tab\\n' => 'معاينة في علامة تبويب جديدة',
  '\\nMaximum date\\n' => 'الحد الأقصى للتاريخ',
  '\\nMinimum date\\n' => 'الحد الأدنى للتاريخ',
  '\\nValid formats:%s\\n' => 'التنسيقات الصالحة: %s',
  '\\nZoom\\n' => 'تكبير',
  '\\nThe map library (OpenStreetMap and Leaflet) loads only on pages that contain a location picker field.\\n' => 'يتم تحميل مكتبة الخرائط (OpenStreetMap وLeaflet) فقط على الصفحات التي تحتوي على حقل منتقي الموقع.',
  '\\nEnable Location Picker in Flux Forms\\n' => 'تمكين منتقي الموقع في Flux Forms',
  '\\nFlux Forms cannot display the form because jQuery is not properly loaded. This issue might be due to incorrect jQuery invocation by another plugin or the current website theme.\\n' => 'لا يمكن لـ Flux Forms عرض النموذج لأنه لم يتم تحميل jQuery بشكل صحيح. قد تكون هذه المشكلة بسبب استدعاء jQuery غير صحيح بواسطة مكون إضافي آخر أو سمة موقع الويب الحالية.',
  '\\nTelegram Notification Add-on\\n' => 'الوظيفة الإضافية لإشعارات Telegram',
  '\\nThe Telegram notification add-on lets you get notifications on your Telegram app whenever you receive new messages or responses\\n' => 'تتيح لك الوظيفة الإضافية لإشعارات Telegram الحصول على إشعارات على تطبيق Telegram الخاص بك عندما تتلقى رسائل أو ردودًا جديدة',
  '\\nEnter a location name\\n' => 'أدخل اسم الموقع',
  '\\nThe%1$spages are currently unavailable. It looks like another plugin is causing a conflict with%1$s. To fix this issue,%2$scontact%1$ssupport%3$sfor assistance or try disabling your plugins one at a time to identify the one causing the conflict.\\n' => 'صفحات%1$sغير متاحة حاليًا. يبدو أن مكونًا إضافيًا آخر يتسبب في حدوث تعارض مع%1$s. لإصلاح هذه المشكلة، اتصل بـ%2$sبدعم%1$sبـ%3$sللحصول على المساعدة أو حاول تعطيل المكونات الإضافية الخاصة بك واحدًا تلو الآخر لتحديد المكون الذي يسبب التعارض.',
  'Settings' => 'الإعدادات',
  '[[\'Send email with submitted form content only\\n' => 'إرسال بريد إلكتروني يتضمن محتوى النموذج المقدم فقط',
  '\\n%scopied!\\n' => ' تم نسخ%s!',
  '\\nThe website is not responding; please refresh and try again—saving or submitting is not available until it is restored.\\n' => 'موقع الويب لا يستجيب؛ يرجى التحديث والمحاولة مرة أخرى - لن يكون الحفظ أو الإرسال متاحًا إلا بعد استعادته.',
  '\\nYour session has expired or is no longer valid. Please refresh the page to continue.\\n' => 'لقد انتهت صلاحية جلسة العمل الخاصة بك أو لم تعد صالحة. الرجاء تحديث الصفحة للمتابعة.',
  '\\nYour account has been successfully activated. You can now log in and get started!\\n' => 'لقد تم تفعيل حسابك بنجاح. يمكنك الآن تسجيل الدخول والبدء!',
  '\\nYou\'re all done\\n' => 'لقد انتهيت من كل شيء',
  '\\nEnter your email to reset your password\\n' => 'أدخل بريدك الإلكتروني لإعادة تعيين كلمة المرور',
  '\\nIf your email is valid, a password reset link has been sent to your email address.\\n' => 'إذا كان بريدك الإلكتروني صالحاً، فقد تم إرسال رابط إعادة تعيين كلمة المرور إلى عنوان بريدك الإلكتروني.',
  '\\nEnable%s\\n' => 'تمكين%s',
  '\\nAuto-Populate\\n' => 'التعبئة التلقائية',
  '\\nAuto-populate from previously submitted forms\', \'en\']]' => 'ملء تلقائي من النماذج التي تم إرسالها مسبقًا',
  '\\nEnable Auto-Populate to automatically populate this field\\n' => 'قم بتمكين الملء التلقائي لملء هذا الحقل تلقائياً',
  '\\nAPI Auto-Populate Integration is Active\\n' => 'تكامل الملء التلقائي لواجهة برمجة التطبيقات (API) نشط',
  '\\nThis form uses External API Auto-Populate. To configure settings, go to\\n' => 'يستخدم هذا النموذج التعبئة التلقائية لواجهة برمجة التطبيقات الخارجية. لتكوين الإعدادات، انتقل إلى',
  '\\nAuto-Populate Integrations\\n' => 'تعبئة عمليات التكامل تلقائيًا',
  '\\nSelect Form\\n' => 'حدد النموذج',
  '\\nTarget Form\\n' => 'نموذج الهدف',
  '\\nSelect a Form\\n' => 'حدد نموذج',
  '\\nSelect the form that will receive data from the API\\n' => 'حدد النموذج الذي سيتلقى البيانات من واجهة برمجة التطبيقات',
  '\\nSearch Fields (Trigger Fields)\\n' => 'حقول البحث (حقول التشغيل)',
  '\\nPlease select a form first\\n' => 'الرجاء تحديد نموذج أولاً',
  '\\nTarget Fields (Fields to Fill)\\n' => 'الحقول المستهدفة (الحقول المراد ملؤها)',
  '\\nMap API response fields to form fields. The API data will automatically fill these fields.\\n' => 'قم بتعيين حقول استجابة API لحقول النموذج. ستقوم بيانات API بملء هذه الحقول تلقائياً.',
  '\\nNo fillable fields found in this form\\n' => 'لم يتم العثور على حقول قابلة للتعبئة في هذا النموذج',
  '[[\'field\', \'en\']]' . chr(0) . '[[\'fields\', \'en\']]' => 'الحقول' . chr(0) . 'الحقل' . chr(0) . 'الحقول' . chr(0) . 'الحقول' . chr(0) . 'الحقول' . chr(0) . 'الحقول',
  '\\nAPI Field Name\\n' => 'اسم حقل واجهة برمجة التطبيقات',
  '\\nForm Field\\n' => 'حقل النموذج',
  '\\nSelect Field\\n' => 'حدد الحقل',
  '\\nCache Settings\\n' => 'إعدادات ذاكرة التخزين المؤقت',
  '\\nCache API responses to improve performance\\n' => 'تخزين استجابات API لتحسين الأداء',
  '\\nExternal API Connections\\n' => 'اتصالات API الخارجية',
  '\\nAdd API Connection\\n' => 'إضافة اتصال API',
  '\\nUpload the%sfile\\n' => 'قم بتحميل ملف%s',
  'CSV' => 'CSV',
  '\\nDataset\\n' => 'مجموعة البيانات',
  '[[\'The%shas been successfully completed\\n' => 'تم إكمال%sبنجاح',
  'Rename' => 'إعادة تسمية',
  'Source' => 'المصدر',
  '\\n%snot found\\n' => ' لم يتم العثور على%s',
  '\\n%sLocation\\n' => ' موقع%s',
  '\\ninstallation\\n' => 'التثبيت',
  '\\nThe%shave been deleted.\\n' => 'تم حذف%s.',
  '\\nThe%sfield must be correctly filled out to proceed.\', \'en\']]' => 'يجب ملء الحقل%sبشكل صحيح للمتابعة.',
  '\\nSubmitted Form\\n' => 'النموذج المقدم',
  '\\nYou can\'t add reCAPTCHA to payment forms.\\n' => 'لا يمكنك إضافة reCAPTCHA إلى نماذج الدفع.',
  '\\nLearn more about%sor watch the video tutorial.\\n' => 'اعرف المزيد حول%sأو شاهد الفيديو التعليمي.',
  '\\nLearn more%s\\n' => 'معرفة المزيد عن%s',
  '\\nGoogle reCAPTCHA\\n' => 'Google reCAPTCHA',
  '\\nThe connection was interrupted, but don\\\'t worry—your edits are safely stored in your browser. Refresh the page to continue working.\\n' => 'لقد انقطع الاتصال، لكن لا تقلق، فقد تم تخزين تعديلاتك بأمان في متصفحك. قم بتحديث الصفحة لمتابعة العمل.',
  '[["There is an auto-saved version of the form available. Do you want to restore it?\\n' => 'توجد نسخة محفوظة تلقائيًا من النموذج متوفرة. هل تريد استعادتها؟',
  '\\nSMS notification could not be sent. Check if the SMS plugin is installed and configured properly.\\n' => 'تعذر إرسال إشعار SMS. تحقق من تثبيت المكون الإضافي لـ SMS وتكوينه بشكل صحيح.',
  '\\nYour request was completed successfully.%1$s%2$s\\n' => 'تم إكمال طلبك بنجاح.%1$s%2$s',
  '\\nPayPal\\n' => 'باي بال',
  '\\nTo use%1$sfeatures in your forms, you need to get your%2$skeys.\\n' => 'لاستخدام ميزات%1$sفي النماذج الخاصة بك، يجب الحصول على مفاتيح%2$sالخاصة بك.',
  '\\nGo to the add-ons page in the Flux Forms plugin, install the%sadd-on, and try again.\\n' => 'انتقل إلى صفحة الوظائف الإضافية في المكون الإضافي Flux Forms، ثم قم بتثبيت الوظيفة الإضافية%s، ثم حاول مرة أخرى.',
  '\\nTo create a payment form to collect online payments, install a payment add-on such as the%sAdd-on first.\\n' => 'لإنشاء نموذج دفع لجمع الدفعات عبر الإنترنت، قم بتثبيت وظيفة الدفع الإضافية مثل الوظيفة الإضافية%sأولاً.',
  'Activated' => 'تفعيلها',
  '\\nThank\\n' => 'شكرًا',
  '\\nThe%splugin may interfere with Flux Forms form functionality. If you encounter any issues with the forms, disable caching for the Flux Forms plugin in the%ssettings.\\n' => 'قد يتداخل المكون الإضافي%sمع وظيفة نموذج Flux Forms. إذا واجهت أي مشاكل مع النماذج، قم بتعطيل التخزين المؤقت للمكون الإضافي Flux Forms في إعدادات%s.',
  '\\nRemind me later\\n' => 'ذكّرني لاحقًا',
  '[["Got it, don\'t show it again\\n' => 'فهمت، لا تعرضه مرة أخرى',
  '\\nThe value of the%1$sfield does not match the pattern and must be at least%2$scharacters.\\n' => 'قيمة الحقل%1$sلا تتطابق مع النمط ويجب أن تتكون من أحرف%2$sعلى الأقل.',
  '\\nThe value of the%1$sfield does not match the pattern and must be at most%2$scharacters.\\n' => 'قيمة الحقل%1$sلا تتطابق مع النمط ويجب أن تتكون من أحرف%2$sعلى الأكثر.',
  '[[\'Please enter valid value for the%sfield.\\n' => 'الرجاء إدخال قيمة صالحة للحقل%s.',
  '\\n%slist\\n' => ' قائمة%s',
  '\\nThe uploaded file exceeds the allowable limit of%sMB.\\n' => 'الملف الذي تم تحميله يتجاوز الحد المسموح به وهو%sميغابايت.',
  '\\nThe uploaded file is below the required minimum size of%sMB.\\n' => 'الملف الذي تم تحميله أقل من الحد الأدنى المطلوب للحجم وهو%sميغابايت.',
  '\\nReview the entered values in the%stab. This message appeared because an error was detected.\\n' => 'راجع القيم المدخلة في علامة التبويب%s. ظهرت هذه الرسالة بسبب اكتشاف خطأ.',
  '\\nAre you sure you want to duplicate the "%s" ?\\n' => 'هل أنت متأكد أنك تريد تكرار "%s" ؟',
