  '\\nThe following security plugin may block form submissions with 403 errors. It may block the REST API, remove the X-WP-Nonce header, or apply firewall rules to form requests.\\n' => 'قد يقوم مكون الأمان الإضافي التالي بحظر عمليات إرسال النماذج التي تحتوي على أخطاء 403. قد يقوم بحظر REST API، أو إزالة رأس X-WP-Nonce، أو تطبيق قواعد جدار الحماية على طلبات النماذج.',
