  '\\nAuto-Populate Add-on\\n' => 'ملء الوظيفة الإضافية تلقائيًا',
  '\\nThe Auto-Populate add-on enables you to automatically populate form fields from datasets, previously submitted forms, or external APIs.\\n' => 'تمكّنك وظيفة الملء التلقائي الإضافية من تعبئة حقول النماذج تلقائيًا من مجموعات البيانات، أو النماذج التي تم إرسالها مسبقًا، أو واجهات برمجة التطبيقات الخارجية.',
  '\\nForm Security & Spam Protection\\n' => 'أمان النماذج والحماية من البريد العشوائي',
  '\\nBehavior-based anti-spam and API abuse protection with rate limits and a stop-loss for paid notifications such as SMS, Telegram, email and webhooks.\\n' => 'حماية من إساءة استخدام واجهة برمجة التطبيقات (API) ومكافحة البريد العشوائي المستندة إلى السلوك مع حدود للمعدلات وإيقاف الخسارة للإشعارات المدفوعة مثل الرسائل النصية القصيرة (SMS) وTelegram والبريد الإلكتروني وخطافات الويب.',
  '\\nGoogle Sheet Add-on\\n' => 'الوظيفة الإضافية لجداول بيانات Google',
  '\\nAutomatically send form submissions to your Google Sheets in real time. Connect a service account, map fields to columns, and keep a live, styled spreadsheet of every response — no webhook or browser login required.\\n' => 'أرسل عمليات إرسال النماذج تلقائيًا إلى جداول بيانات Google في الوقت الفعلي. قم بتوصيل حساب خدمة، وقم بتعيين الحقول إلى الأعمدة، واحتفظ بجدول بيانات مباشر ومُصمم لكل استجابة - لا يلزم وجود خطاف ويب أو تسجيل دخول للمتصفح.',
  '\\nPlease fill in all required fields\\n' => 'الرجاء ملء كافة الحقول المطلوبة',
  '\\nEmail Server Status\\n' => 'حالة خادم البريد الإلكتروني',
  '\\nThe test email never arrived\\n' => 'لم يصل البريد الإلكتروني التجريبي مطلقًا',
  '\\nYour WordPress site cannot send emails reliably. This is a very common hosting issue — the default PHP mail function is often blocked or ends up in spam. Installing an SMTP plugin routes your emails through a verified mail service and fixes this in minutes.\\n' => 'لا يمكن لموقع WordPress الخاص بك إرسال رسائل البريد الإلكتروني بشكل موثوق. هذه مشكلة استضافة شائعة جدًا - غالبًا ما يتم حظر وظيفة بريد PHP الافتراضية أو ينتهي بها الأمر في البريد العشوائي. يؤدي تثبيت مكون SMTP الإضافي إلى توجيه رسائل البريد الإلكتروني الخاصة بك عبر خدمة بريد تم التحقق منها وإصلاح هذه المشكلة خلال دقائق.',
  '\\nWordPress sent the email - it just never arrived\\n' => 'أرسل WordPress البريد الإلكتروني - لكنه لم يصل مطلقًا',
  '\\nYour site handed the message to your mail server successfully, so WordPress and this plugin did their part. It was lost, delayed or rejected afterwards - most often the receiving mailbox filed it as spam, or your host never delivered it from the outbound queue. Sending through an SMTP service, with SPF and DKIM records for your domain, is what fixes this.\\n' => 'لقد قام موقعك بتسليم الرسالة إلى خادم البريد الخاص بك بنجاح، لذلك قام WordPress وهذا المكون الإضافي بدورهما. تم فقدها أو تأخيرها أو رفضها بعد ذلك - غالبًا ما يرسلها صندوق البريد المتلقي كرسالة غير مرغوب فيها، أو لم يسلمها مضيفك مطلقًا من قائمة انتظار البريد الصادر. إن الإرسال عبر خدمة SMTP، مع سجلات SPF وDKIM للمجال الخاص بك، هو ما يحل هذه المشكلة.',
  '\\nWordPress could not send the email\\n' => 'تعذر على WordPress إرسال البريد الإلكتروني',
  '\\nThe message never left your website: WordPress returned an error while sending it. Install and configure an SMTP plugin, or ask your host whether PHP mail is disabled.\\n' => 'لم تغادر الرسالة موقعك على الويب مطلقًا: عرض WordPress خطأً أثناء إرسالها. قم بتثبيت مكون SMTP الإضافي وتكوينه، أو اسأل مضيفك عما إذا كان بريد PHP معطلاً.',
  '\\nYour emails arrive, but will most likely land in spam\\n' => 'تصل رسائل البريد الإلكتروني الخاصة بك، ولكن من المرجح أن تصل إلى رسائل غير مرغوب فيها',
  '[[\'Delivery itself works - the test message reached us. What is missing is trust: sending through an SMTP service and adding SPF and DKIM records for your domain is what moves your emails from the spam folder to the inbox.\\n' => 'التسليم نفسه يعمل - وصلت رسالة الاختبار إلينا. ما ينقصنا هو الثقة: الإرسال عبر خدمة SMTP وإضافة سجلات SPF وDKIM للمجال الخاص بك هو ما ينقل رسائل البريد الإلكتروني الخاصة بك من مجلد البريد العشوائي إلى البريد الوارد.',
  '\\nThe test email was delivered with a deliverability score of%1$sout of 100. Under%2$s, most mailboxes file messages in the spam folder, so the people filling in your forms may never see them.\\n' => 'تم تسليم البريد الإلكتروني التجريبي بدرجة تسليم تبلغ%1$sمن أصل 100. ضمن%2$s، تقوم معظم صناديق البريد بحفظ الرسائل في مجلد البريد العشوائي، لذلك قد لا يتمكن الأشخاص الذين يملؤون النماذج الخاصة بك من رؤيتها أبدًا.',
  '\\nStep-by-step SMTP setup guide\\n' => 'دليل إعداد SMTP خطوة بخطوة',
  '\\nYour email server is working. A detailed HTML report has been sent to%s.\\n' => 'خادم البريد الإلكتروني الخاص بك يعمل. تم إرسال تقرير HTML مفصل إلى%s.',
  '\\nyour admin email address\\n' => 'عنوان البريد الإلكتروني للمشرف',
  '\\nSpam Score Report on the Way!\\n' => 'تقرير نتيجة البريد العشوائي في الطريق!',
  '\\nA complete email health report — including your spam score, deliverability details, and recommendations — will be sent to%swithin the next few minutes.\\n' => 'سيتم إرسال تقرير كامل عن سلامة البريد الإلكتروني - بما في ذلك نقاط البريد العشوائي وتفاصيل إمكانية التسليم والتوصيات - إلى%sخلال الدقائق القليلة القادمة.',
  '\\nEmail notifications may not be delivered\\n' => 'قد لا يتم تسليم إعلامات البريد الإلكتروني',
  '\\nThis form\'s email notification feature is enabled, but email delivery has not been verified and the latest spam score is%s/100. The form was saved, but admin notification emails may not reach you until SMTP/email delivery is fixed.\\n' => 'تم تمكين ميزة الإعلام عبر البريد الإلكتروني لهذا النموذج، ولكن لم يتم التحقق من تسليم البريد الإلكتروني وآخر نتيجة للبريد العشوائي هي%s/100. تم حفظ النموذج، ولكن قد لا تصلك رسائل البريد الإلكتروني الخاصة بإشعارات المشرف حتى يتم إصلاح تسليم SMTP/البريد الإلكتروني.',
  '\\nNotification emails are turned off\\n' => 'تم إيقاف رسائل الإعلام الإلكترونية',
  '\\nFlux Forms will not send any email — neither to you nor to the person who submits this form — until "This site can send emails" is enabled in Email Settings.\\n' => 'لن تقوم Flux Forms بإرسال أي بريد إلكتروني - لا إليك ولا إلى الشخص الذي يرسل هذا النموذج - حتى يتم تمكين "يمكن لهذا الموقع إرسال رسائل بريد إلكتروني" في إعدادات البريد الإلكتروني.',
  '[[\'Enable email sending\\n' => 'تمكين إرسال البريد الإلكتروني',
  '\\nClick "Check Email Server" to test delivery, turn this switch on, then press Save.\\n' => 'انقر فوق "التحقق من خادم البريد الإلكتروني" لاختبار التسليم، ثم قم بتشغيل هذا المفتاح، ثم اضغط "حفظ".',
  '\\nDelivery is taking longer than expected\', \'en\']]' => 'يستغرق التسليم وقتًا أطول من المتوقع',
  '\\nWordPress sent the test email, but our server has not received it yet. This may be a temporary delay. Check the diagnostics below to troubleshoot.\\n' => 'أرسل WordPress رسالة البريد الإلكتروني التجريبية، لكن خادمنا لم يستلمها بعد. قد يكون هذا تأخيرًا مؤقتًا. تحقق من التشخيص أدناه لاستكشاف الأخطاء وإصلاحها.',
  '\\nPrepare Test\\n' => 'تحضير الاختبار',
  '\\nConnecting to WhiteStudio to generate a unique test email address.\\n' => 'الاتصال بـ WhiteStudio لإنشاء عنوان بريد إلكتروني فريد للاختبار.',
  '\\nWordPress Sends the Email\\n' => 'يرسل WordPress البريد الإلكتروني',
  '\\nWordPress hands a real message to your mail server. A tick here means WordPress sent it, not yet that it arrived.\\n' => 'يسلم WordPress رسالة حقيقية إلى خادم البريد الخاص بك. علامة الاختيار هنا تعني أن WordPress قد أرسلها، ولم تصل بعد.',
  '\\nWaiting for Delivery\\n' => 'في انتظار التسليم',
  '\\nChecking whether the test email arrived at our server (usually takes a few seconds).\\n' => 'التحقق من وصول البريد الإلكتروني التجريبي إلى الخادم الخاص بنا (يستغرق عادةً بضع ثوانٍ).',
  '\\nQuick Result\\n' => 'نتيجة سريعة',
  '\\nShowing the first delivery result — you will see right away if email is working.\\n' => 'عرض نتيجة التسليم الأولى — ستعرف على الفور ما إذا كان البريد الإلكتروني يعمل أم لا.',
  '\\nFull Report\\n' => 'التقرير الكامل',
  '\\nA detailed HTML report with full diagnostics is being prepared and emailed to you.\\n' => 'جاري إعداد تقرير HTML مفصل يتضمن تشخيصات كاملة وإرساله إليك عبر البريد الإلكتروني.',
  'Running' => 'الجري',
  'Finished' => 'انتهى',
  '\\nNeeds attention\\n' => 'يحتاج إلى الاهتمام',
  '\\n%sof 5 steps done\\n' => ' تم تنفيذ%sمن 5 خطوات',
  '\\nStep%sof 5\\n' => 'الخطوة%sمن 5',
  '\\n/ 100\\n' => '/ 100',
  '\\nTest started\\n' => 'بدأ الاختبار',
  '[[\'A unique address is being generated for this test.\\n' => 'جاري الآن إنشاء عنوان فريد لهذا الاختبار.',
  '\\nWaiting for the email to arrive\\n' => 'في انتظار وصول البريد الإلكتروني',
  '\\nWe check our server every few seconds. Please keep this page open.\\n' => 'نحن نتحقق من الخادم الخاص بنا كل بضع ثوانٍ. الرجاء إبقاء هذه الصفحة مفتوحة.',
  '\\nYour email server is healthy\\n' => 'خادم البريد الإلكتروني الخاص بك سليم',
  '\\nThe test email arrived, and the subject and unique-code checks both passed.\\n' => 'وصلت رسالة البريد الإلكتروني الاختبارية، وتم اجتياز عملية التحقق من الموضوع والرمز الفريد.',
  '\\nDelivered, but likely to be filtered as spam\\n' => 'تم التسليم، ولكن من المحتمل أن تتم تصفيته كرسائل غير مرغوب فيها',
  '\\nDelivered, but deliverability is weak\\n' => 'تم التسليم، ولكن إمكانية التسليم ضعيفة',
  '\\nNo email arrived\\n' => 'لم يصل أي بريد إلكتروني',
  '\\nNothing was received during the test window, so your server most likely cannot send email.\\n' => 'لم يتم تلقي أي شيء أثناء نافذة الاختبار، لذلك على الأرجح لا يستطيع الخادم الخاص بك إرسال بريد إلكتروني.',
  '\\nThe test timed out\\n' => 'انتهت مهلة الاختبار',
  '\\nThe test reached its time limit. Your server may be slow, or may block outbound email.\\n' => 'وصل الاختبار إلى الحد الزمني المحدد له. قد يكون الخادم الخاص بك بطيئًا، أو قد يحظر البريد الإلكتروني الصادر.',
  '\\nThe test email could not be sent\\n' => 'تعذر إرسال البريد الإلكتروني التجريبي',
  '\\nWordPress returned an error while sending. See the message below.\\n' => 'أرجع WordPress خطأً أثناء الإرسال. راجع الرسالة أدناه.',
  '\\nThe connection was lost\', \'en\']]' => 'تم فقدان الاتصال',
  '\\nNo answer came back from the server. Refresh the page and try again.\\n' => 'لم يتم الحصول على أي إجابة من الخادم. قم بتحديث الصفحة وحاول مرة أخرى.',
  '\\nThis test needs a higher plan\\n' => 'يحتاج هذا الاختبار إلى خطة أعلى',
  '\\nUpgrade your plan to run the full delivery test.\\n' => 'قم بترقية خطتك لإجراء اختبار التسليم الكامل.',
  '\\nYour email server is working. A detailed HTML report has been sent to\\n' => 'خادم البريد الإلكتروني الخاص بك يعمل. تم إرسال تقرير HTML مفصل إلى',
  '\\nA complete email health report — including your spam score, deliverability details, and recommendations — will be sent within the next few minutes to\\n' => 'سيتم إرسال تقرير كامل عن سلامة البريد الإلكتروني - بما في ذلك نقاط الرسائل غير المرغوب فيها وتفاصيل إمكانية التسليم والتوصيات - خلال الدقائق القليلة القادمة إلى',
  '\\nUpgrade required\\n' => 'الترقية مطلوبة',
  '\\nAn auto-saved version exists\\n' => 'توجد نسخة محفوظة تلقائياً',
  '\\nRestore it\', \'en\']]' => 'استعادتها',
  '\\nStart fresh\\n' => 'ابدأ من جديد',
  '\\nLast saved\\n' => 'آخر حفظ',
  '\\nDelivery Details\\n' => 'تفاصيل التسليم',
  '\\nTest sent to\\n' => 'تم إرسال الاختبار إلى',
  '\\nEmail subject\\n' => 'موضوع البريد الإلكتروني',
  'Sender address' => 'عنوان المرسل',
  '\\nEmail received\\n' => 'تم استلام البريد الإلكتروني',
  '\\nSubject matched\\n' => 'الموضوع مطابق',
  '\\nUnique code verified\\n' => 'تم التحقق من الرمز الفريد',
  '\\nTime waited\\n' => 'الوقت المنتظر',
