  '\\nScore:%s\\n' => 'النتيجة: %s',
  '\\nUpgrade\\n' => 'ترقية',
  '\\nThe test timed out. Please try again — your server may be slow or blocking outgoing mail.\\n' => 'انتهت مهلة الاختبار. الرجاء المحاولة مرة أخرى — قد يكون الخادم الخاص بك بطيئًا أو يحظر البريد الصادر.',
  '\\nWaiting for the test email to arrive...\\n' => 'في انتظار وصول البريد الإلكتروني التجريبي...',
  '\\nEmail is on its way — still waiting for delivery confirmation.\\n' => 'البريد الإلكتروني في طريقه إليك — لا يزال في انتظار تأكيد التسليم.',
  '\\nNo email arrived during the test window.\\n' => 'لم يصل أي بريد إلكتروني أثناء نافذة الاختبار.',
  '\\nStill checking — please wait a moment...\\n' => 'لا يزال التحقق — الرجاء الانتظار قليلاً...',
