  '\\nSides/Appetizers\\n' => 'أطباق جانبية/مقبلات',
  'Average' => 'متوسط',
  '\\nAvg Length\\n' => 'متوسط الطول',
  '\\nOffline Forms\', \'en\']]' => 'نماذج غير متصلة بالإنترنت',
  '\\nPersia Payment\\n' => 'الدفع في بلاد فارس',
  '\\nPersian Date Picker\\n' => 'منتقي التاريخ الفارسي',
  '\\nArabic Date Picker\\n' => 'منتقي التاريخ باللغة العربية',
  '\\nGoogle Sheets\\n' => 'جداول بيانات Google',
  '\\nConditional Logic\\n' => 'المنطق الشرطي',
  '\\nYour subscription needs renewing before the missing add-ons can be restored.\\n' => 'يحتاج اشتراكك إلى التجديد قبل أن تتمكن من استعادة الوظائف الإضافية المفقودة.',
  '\\nThe missing add-on files could not be restored. Check the server connection and file permissions, then try again.\\n' => 'تعذرت استعادة ملفات الوظائف الإضافية المفقودة. تحقق من اتصال الخادم وأذونات الملفات، ثم حاول مرة أخرى.',
  '\\nYou do not have permission to do this.\\n' => 'ليس لديك الإذن للقيام بذلك.',
  '\\nAll required add-ons were restored.\\n' => 'تمت استعادة كافة الوظائف الإضافية المطلوبة.',
  '\\nFinish updating Flux Forms\\n' => 'الانتهاء من تحديث نماذج التمويه',
  '\\nSome add-on files are missing\\n' => 'بعض ملفات الوظائف الإضافية مفقودة',
  '\\nThe plugin was updated, so its add-ons must be reinstalled before this page can load. Click the button below to install them.\\n' => 'تم تحديث المكون الإضافي، لذا يجب إعادة تثبيت الوظائف الإضافية الخاصة به قبل أن تتمكن من تحميل هذه الصفحة. انقر فوق الزر أدناه لتثبيتها.',
  '\\nOne or more add-on files are missing. Click the button below to reinstall them.\\n' => 'هناك ملف واحد أو أكثر من الملفات الإضافية مفقود. انقر فوق الزر أدناه لإعادة تثبيتها.',
  '\\nAutomatic recovery was attempted but did not finish. Review the reason below, fix it if necessary, then try again.\\n' => 'جرت محاولة الاسترداد التلقائي ولكنها لم تنته. راجع السبب أدناه، وقم بإصلاحه إذا لزم الأمر، ثم حاول مرة أخرى.',
  '\\nRecover add-ons\\n' => 'استرداد الوظائف الإضافية',
  '\\nInstalling add-ons...\\n' => 'تثبيت الوظائف الإضافية...',
  '\\nInstallation complete.\\n' => 'اكتمل التثبيت.',
  '\\nClick to activate the add-ons.\\n' => 'انقر لتنشيط الوظائف الإضافية.',
  '[[\'Activate add-ons\\n' => 'تفعيل الوظائف الإضافية',
  '\\nInstallation failed. Please try again.\\n' => 'فشل التثبيت. الرجاء المحاولة مرة أخرى.',
  '\\nMissing add-ons:\', \'en\']]' => 'الوظائف الإضافية مفقودة:',
  '\\nWhy the recovery failed\\n' => 'لماذا فشلت عملية الاسترداد',
  '\\nPreparing your form\\n' => 'تحضير النموذج',
  '\\nAdd-ons restored successfully\\n' => 'تمت استعادة الوظائف الإضافية بنجاح',
  '\\nThe form is being prepared. This page will reload automatically.\\n' => 'جاري إعداد النموذج. سيتم إعادة تحميل هذه الصفحة تلقائياً.',
  '\\nThe page will reload automatically so the restored add-ons can be activated.\\n' => 'ستتم إعادة تحميل الصفحة تلقائياً حتى يمكن تنشيط الوظائف الإضافية المستعادة.',
  '\\nReload now\\n' => 'أعد التحميل الآن',
  '\\nThis form is temporarily unavailable.\\n' => 'هذا النموذج غير متوفر مؤقتاً.',
  '\\nWe could not restore a required form component automatically. Please try again shortly; the site administrator can view the exact recovery error in Flux Forms.\\n' => 'لم نتمكن من استعادة مكون النموذج المطلوب تلقائياً. يرجى المحاولة مرة أخرى قريبا؛ يمكن لمسؤول الموقع عرض خطأ الاسترداد الدقيق في Flux Forms.',
  '\\nThe add-on is already installed.\\n' => 'الوظيفة الإضافية مثبتة مسبقاً.',
  '\\nFile access status not checked yet. Please wait.\\n' => 'لم يتم التحقق من حالة الوصول إلى الملف بعد. الرجاء الانتظار.',
  '\\nError: server (%s) responded with an invalid request. responded code:%s\\n' => 'خطأ: استجاب الخادم (%s) بطلب غير صالح. رمز الاستجابة: %s',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to connect to the%sserver\\n' => 'لا يمكن تثبيت الوظائف الإضافية لـ Flux Forms لأن المكون الإضافي غير قادر على الاتصال بملقم%s',
  '\\nYour Easy Form Builder Pro subscription has expired, so the Pro add-ons could not be downloaded. The plugin keeps working without them. Renew your subscription to restore all Pro features:\\n' => 'لقد انتهت صلاحية اشتراكك في Easy Form Builder Pro، لذا تعذر تنزيل الوظائف الإضافية Pro. يستمر البرنامج المساعد في العمل بدونها. قم بتجديد اشتراكك لاستعادة كافة ميزات Pro:',
  '\\nThe version of the add-on is not compatible with the version of the Flux Forms plugin.\\n' => 'إصدار الوظيفة الإضافية غير متوافق مع إصدار البرنامج الإضافي Flux Forms.',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to download files\\n' => 'لا يمكن تثبيت الوظائف الإضافية لـ Flux Forms لأن المكون الإضافي غير قادر على تنزيل الملفات',
  '\\nCannot install add-ons because this server has disabled the PHP filesystem functions needed to prepare the download. Please ask your hosting provider to enable mkdir and rename, or configure the WordPress filesystem.\\n' => 'لا يمكن تثبيت الوظائف الإضافية لأن هذا الملقم قام بتعطيل وظائف نظام ملفات PHP اللازمة للتحضير للتنزيل. الرجاء مطالبة موفر الاستضافة بتمكين mkdir وإعادة تسمية نظام ملفات WordPress أو تكوينه.',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to move the downloaded file\\n' => 'لا يمكن تثبيت الوظائف الإضافية لـ Flux Forms لأن المكون الإضافي غير قادر على نقل الملف الذي تم تنزيله',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to unzip files\', \'en\']]' => 'لا يمكن تثبيت الوظائف الإضافية لـ Flux Forms لأن المكون الإضافي غير قادر على فك ضغط الملفات',
  '\\nTo fix this, sign in to your%s, download the Add-ons Handler plugin from the Downloads section, then install and activate it. After that, activate the add-ons you need from the Add-ons Handler plugin.\\n' => 'لإصلاح هذه المشكلة، قم بتسجيل الدخول إلى%s الخاص بك، وقم بتنزيل المكون الإضافي Add-ons Handler من قسم التنزيلات، ثم قم بتثبيته وتنشيطه. بعد ذلك، قم بتنشيط الوظائف الإضافية التي تحتاجها من المكون الإضافي Add-ons Handler.',
  '\\nWhiteStudio dashboard\\n' => 'لوحة تحكم WhiteStudio',
  '\\nThis bundled add-on is missing from the plugin files.\\n' => 'هذه الوظيفة الإضافية المجمعة مفقودة من ملفات البرنامج الإضافي.',
  '\\nThe add-on server returned an unexpected response.\\n' => 'أرجع خادم الوظيفة الإضافية استجابة غير متوقعة.',
  '\\nThe add-on could not be installed.\\n' => 'تعذر تثبيت الوظيفة الإضافية.',
  '\\nThe add-on server did not provide a download URL.\\n' => 'لم يوفر خادم الوظيفة الإضافية عنوان URL للتنزيل.',
  '\\nThe add-on download URL is not an approved Flux Forms source.\\n' => 'عنوان URL لتنزيل الوظيفة الإضافية ليس مصدرًا معتمدًا لـ Flux Forms.',
  '\\nYour server could not reach%1$s, so the add-on could not be downloaded. This is almost always a firewall on your hosting blocking the outgoing request, not a problem with your licence. To install add-ons without any download at all, sign in at%2$sand download the Flux Forms Add-ons Handler plugin, then install it like any other plugin. It contains every add-on your licence covers.\\n' => 'تعذر على الخادم الخاص بك الوصول إلى%1$s، لذا تعذر تنزيل الوظيفة الإضافية. يكون هذا دائمًا بمثابة جدار حماية على الاستضافة الخاصة بك يمنع الطلب الصادر، ولا يمثل مشكلة في الترخيص الخاص بك. لتثبيت الإضافات دون أي تنزيل على الإطلاق، قم بتسجيل الدخول على%2$sوقم بتنزيل المكون الإضافي Flux Forms Add-ons Handler، ثم قم بتثبيته مثل أي مكون إضافي آخر. فهو يحتوي على كل الوظائف الإضافية التي تغطي تراخيصك.',
  '\\nIf you would rather fix the connection, ask your hosting provider why outgoing requests from%sare being blocked.\\n' => 'إذا كنت تفضل إصلاح الاتصال، اسأل موفر الاستضافة عن سبب حظر الطلبات الصادرة من%s.',
  '\\nFlux Forms: add-on downloads are being blocked\\n' => 'نماذج التدفق: تم حظر تنزيلات الوظائف الإضافية',
  '\\nAdd-on affected:%s\\n' => 'الوظيفة الإضافية المتأثرة: %s',
  '\\nNo response was recorded for this add-on.\\n' => 'لم يتم تسجيل أي استجابة لهذه الوظيفة الإضافية.',
  '\\nWritable\\n' => 'قابل للكتابة',
  '\\nNot writable — the add-on folder cannot be created or extracted into.\\n' => 'غير قابل للكتابة — لا يمكن إنشاء مجلد الوظيفة الإضافية أو استخراجه إليه.',
  '\\nBlocked by WP_HTTP_BLOCK_EXTERNAL — outgoing requests are disabled on this site.\\n' => 'تم حظرها بواسطة WP_HTTP_BLOCK_EXTERNAL — تم تعطيل الطلبات الصادرة على هذا الموقع.',
  'Allowed' => 'مسموح',
  '\\nDISABLE_WP_CRON is on — background retries only run if a server cron task calls wp-cron.php.\\n' => 'DISABLE_WP_CRON قيد التشغيل - يتم تشغيل عمليات إعادة المحاولة في الخلفية فقط إذا كانت مهمة cron الخاصة بالخادم تستدعي wp-cron.php.',
  'Site' => 'الموقع',
  '\\nPage that needed it\\n' => 'الصفحة التي تحتاج إليها',
  '\\nPlugin version\\n' => 'إصدار البرنامج المساعد',
  'WordPress' => 'ووردبريس',
  '\\nAdd-on folder\\n' => 'مجلد الوظائف الإضافية',
  '\\nOutgoing requests\\n' => 'الطلبات الصادرة',
  '\\nWP-Cron\\n' => 'WP-Cron',
  '\\nAttempts made\\n' => 'تم إجراء المحاولات',
  '\\nFlux Forms could not reinstall its add-on files automatically. Forms that rely on those add-ons are showing a temporary message to visitors until this is resolved.\\n' => 'تعذر على Flux Forms إعادة تثبيت ملفات الوظائف الإضافية الخاصة به تلقائياً. تعرض النماذج التي تعتمد على تلك الوظائف الإضافية رسالة مؤقتة للزائرين حتى يتم حل هذه المشكلة.',
  '\\nWhat is missing\\n' => 'ما هو المفقود',
  '\\nDiagnostics\\n' => 'التشخيص',
  '\\nWhat to do next\\n' => 'ما يجب فعله بعد ذلك',
  '\\nOpen Flux Forms in your dashboard and use the Recover add-ons button.\\n' => 'افتح Flux Forms في لوحة المعلومات واستخدم زر "استرداد الوظائف الإضافية".',
  '\\nIf the add-on folder is not writable, ask your host to allow writing to the plugin folder.\\n' => 'إذا كان مجلد الوظيفة الإضافية غير قابل للكتابة، فاطلب من مضيفك السماح بالكتابة إلى مجلد الوظيفة الإضافية.',
  '\\nIf outgoing requests are blocked, ask your host to allow connections to the Flux Forms update server.\\n' => 'إذا تم حظر الطلبات الصادرة، فاطلب من مضيفك السماح بالاتصالات بملقم تحديث Flux Forms.',
  '\\nIf your Pro subscription has expired, renew it to restore the Pro add-ons.\\n' => 'إذا انتهت صلاحية اشتراكك في Pro، قم بتجديده لاستعادة الوظائف الإضافية لـ Pro.',
  '\\nWe have made some updates. Please wait a few minutes before trying again.\\n' => 'لقد أجرينا بعض التحديثات. الرجاء الانتظار بضع دقائق قبل المحاولة مرة أخرى.',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to connect to the whitestudio.team server\\n' => 'لا يمكن تثبيت الوظائف الإضافية لـ Flux Forms لأن المكون الإضافي غير قادر على الاتصال بخادم Whitestudio.team',
  '\\nOne of the free features\\n' => 'إحدى الميزات المجانية',
  '\\nImportant: Caching Plugin May Affect Flux Forms\\n' => 'هام: قد يؤثر البرنامج الإضافي للتخزين المؤقت على نماذج التمويه',
  '\\nThe following caching plugins are active on your site:\\n' => 'المكونات الإضافية التالية للتخزين المؤقت نشطة على موقعك:',
  '\\nPlugin Name\\n' => 'اسم البرنامج المساعد',
  '\\nSlug\\n' => 'سبيكة',
  '\\nPlease note that these plugins may affect the functionality of Flux Forms.\\n' => 'الرجاء ملاحظة أن هذه المكونات الإضافية قد تؤثر على وظيفة Flux Forms.',
  '\\nIf you experience any issues, please exclude the page where your form is published from caching or disable these plugins. For detailed guidance on how to set up this exclusion, please refer to the documentation of the respective caching plugin.\\n' => 'إذا واجهت أية مشكلات، فيرجى استبعاد الصفحة التي تم نشر النموذج الخاص بك فيها من التخزين المؤقت أو تعطيل هذه المكونات الإضافية. للحصول على إرشادات مفصلة حول كيفية إعداد هذا الاستثناء، يرجى الرجوع إلى وثائق البرنامج الإضافي للتخزين المؤقت المعني.',
  '\\nSent by\\n' => 'تم الإرسال بواسطة',
  '\\nAction needed: Flux Forms Pro is paused on%s\\n' => 'الإجراء المطلوب: تم إيقاف Flux Forms Pro مؤقتًا على%s',
  '\\nFlux Forms could not confirm your Pro licence for%1$sdays in a row, so the Pro features on%2$sare paused for now.\\n' => 'تعذر على Flux Forms تأكيد ترخيص Pro الخاص بك لمدة%1$sمن الأيام المتتالية، لذا تم إيقاف ميزات Pro في%2$sمؤقتًا في الوقت الحالي.',
  '\\nYour forms, entries and settings are untouched, every free feature keeps working, and your activation code is still stored — nothing was deleted.\\n' => 'لم يتم تغيير النماذج والإدخالات والإعدادات الخاصة بك، وستستمر كل الميزات المجانية في العمل، ولا يزال رمز التنشيط الخاص بك مخزّنًا - ولم يتم حذف أي شيء.',
  '\\nOpen%1$sYT Form → Settings%2$sand press%1$sSave%2$s. That checks the licence again straight away; if the connection is back, Pro switches on within a minute.\\n' => 'افتح نموذج%1$sYT → الإعدادات%2$sواضغط على%1$sحفظ%2$s. يقوم ذلك بالتحقق من الترخيص مرة أخرى على الفور؛ إذا عاد الاتصال، فسيتم تشغيل Pro خلال دقيقة.',
  '\\nStill paused? Ask your hosting provider to allow outgoing HTTPS connections to%s— a firewall, proxy or regional block is the usual cause — then repeat step 1.\\n' => 'هل ما زالت متوقفة مؤقتًا؟ اطلب من موفر الاستضافة السماح باتصالات HTTPS الصادرة بـ%s— جدار الحماية أو الوكيل أو الحظر الإقليمي هو السبب المعتاد — ثم كرر الخطوة 1.',
  '\\nIf your subscription has expired, or you moved this website to a new domain,%1$srenew or re-activate your licence%2$sand paste the new code into Settings.\', \'en\']]' => 'إذا انتهت صلاحية اشتراكك، أو قمت بنقل موقع الويب هذا إلى مجال جديد، %1$sقم بتجديد ترخيصك%2$sأو إعادة تنشيطه ولصق الرمز الجديد في الإعدادات.',
  'Reason' => 'السبب',
  '\\nFirst failed check\\n' => 'فشل الفحص الأول',
  '\\ngrace period\\n' => 'فترة السماح',
  '%s days' => '%s أيام',
  '\\nActivation code\\n' => 'رمز التفعيل',
  '\\nError code\\n' => 'رمز الخطأ',
  '\\nHow to bring Pro back\\n' => 'كيفية إعادة النسخة الاحترافية',
  '\\nCheck my licence now\\n' => 'التحقق من الترخيص الخاص بي الآن',
  '\\nStill stuck? Send the details above to%1$sour support team%2$sand we will take it from there.\\n' => 'هل ما زلت عالقًا؟ أرسل التفاصيل أعلاه إلى%1$sفريق الدعم لدينا%2$sوسنتولى الأمر من هناك.',
  '\\nThe licence server answered with an error and could not confirm your licence.\\n' => 'أجاب خادم الترخيص بخطأ ولم يتمكن من تأكيد الترخيص الخاص بك.',
  '\\nYour website could not reach the licence server — almost always a network, firewall or DNS restriction on the hosting side.\\n' => 'تعذر على موقع الويب الخاص بك الوصول إلى خادم الترخيص — غالبًا ما يكون هناك قيود على الشبكة أو جدار الحماية أو DNS من جانب الاستضافة.',
  '\\nThe licence server’s answer arrived damaged, usually because a security plugin, proxy or CDN changed it on the way.\\n' => 'وصلت إجابة خادم الترخيص تالفة، وذلك عادةً بسبب قيام مكون إضافي للأمان أو وكيل أو CDN بتغييرها في الطريق.',
  '\\nThe licence check could not be completed.\\n' => 'تعذر إكمال فحص الترخيص.',
  '[[\'Your activation code has expired!\\n' => 'لقد انتهت صلاحية رمز التفعيل الخاص بك!',
  '\\nYour Easy Form Builder Pro subscription has expired. To continue using the%sadd-on and all Pro features, please renew your subscription.\\n' => 'لقد انتهت صلاحية اشتراكك في Easy Form Builder Pro. لمواصلة استخدام الوظيفة الإضافية%sوجميع ميزات Pro، يرجى تجديد اشتراكك.',
  '\\nRenew Subscription\\n' => 'تجديد الاشتراك',
  '\\nPro Version Required\\n' => 'الإصدار الاحترافي مطلوب',
  '\\nThe%sadd-on is a Pro feature. Please upgrade to Flux Forms Pro to access this functionality.\\n' => 'الوظيفة الإضافية%sهي ميزة احترافية. الرجاء الترقية إلى Flux Forms Pro للوصول إلى هذه الوظيفة.',
  '\\nYour Easy Form Builder Pro subscription has expired. To continue enjoying all Pro features and keep your forms running,%1$sRenew your subscription now.%2$s\\n' => 'لقد انتهت صلاحية اشتراكك في Easy Form Builder Pro. لمواصلة الاستمتاع بجميع ميزات Pro والحفاظ على تشغيل النماذج الخاصة بك، %1$sقم بتجديد اشتراكك الآن.%2$s',
  '\\nThe payment could not be verified yet.\\n' => 'تعذر التحقق من الدفع بعد.',
  '\\nThis payment provider does not support refunds from the site.\\n' => 'لا يدعم موفر الدفع هذا عمليات استرداد الأموال من الموقع.',
  'Completed' => 'مكتمل',
  'Active' => 'نشط',
  '\\nTrial\\n' => 'محاكمة',
  'Pending' => 'في انتظار',
  'Processing' => 'المعالجة',
  '\\nCanceled\\n' => 'تم الإلغاء',
  '\\nAmount mismatch\\n' => 'المبلغ غير متطابق',
  'Past due' => 'فات موعد استحقاقها',
  '\\nUnpaid\\n' => 'غير مدفوعة',
  '\\nIncomplete\\n' => 'غير مكتمل',
  '\\nExpired\\n' => 'انتهت الصلاحية',
  'Refunded' => 'ردها',
  'Partly refunded' => 'تم ردها جزئيا',
  '\\nSorry, you are not allowed to access this page.\\n' => 'عذرًا، غير مسموح لك بالوصول إلى هذه الصفحة.',
  '\\nPayments taken through your forms, from every payment provider. API keys and the active provider are set on the plugin Settings page, Payment tab.\\n' => 'يتم سداد الدفعات من خلال النماذج الخاصة بك، من كل مزود خدمة دفع. يتم تعيين مفاتيح API والموفر النشط في صفحة إعدادات المكون الإضافي، علامة التبويب "الدفع".',
  'Settings saved.' => 'تم حفظ الإعدادات.',
  '\\nA Stripe webhook signing secret starts with "whsec_".\\n' => 'يبدأ سر توقيع خطاف الويب الشريطي بـ "whsec_".',
  '\\nProviders and webhooks\\n' => 'الموفرون وخطافات الويب',
  '\\nConfigured\\n' => 'تم تكوينه',
  '\\nNot configured\', \'en\']]' => 'لم يتم تكوينه',
