  '\\nApprove every payment\\n' => 'الموافقة على كل دفعة',
  '\\nDecline every payment\\n' => 'رفض كل دفعة',
  '\\nNo money is taken. Development only.\\n' => 'لم يتم أخذ أي أموال. التطوير فقط.',
  '\\nTEST MODE: no card is charged.\\n' => 'وضع الاختبار: لم يتم شحن البطاقة.',
  '\\nTest provider: the payment was declined.\\n' => 'موفر الاختبار: تم رفض الدفع.',
  '[[\'Publishable key\\n' => 'مفتاح قابل للنشر',
  'Secret key' => 'المفتاح السري',
  '\\nStripe is not configured on this site. Please contact the site administrator.\\n' => 'لم يتم تكوين الشريط على هذا الموقع. الرجاء الاتصال بمسؤول الموقع.',
  '\\nThe payment method of this form is not supported.\\n' => 'طريقة الدفع لهذا النموذج غير معتمدة.',
  '\\nThe payment could not be started. Please try again.\\n' => 'تعذر بدء الدفع. الرجاء المحاولة مرة أخرى.',
  '\\nOptional but recommended: in the Stripe Dashboard add a webhook endpoint with this URL and the events payment_intent.succeeded, payment_intent.payment_failed, payment_intent.canceled, charge.refunded, customer.subscription.updated and customer.subscription.deleted, then paste its signing secret below.\\n' => 'اختياري لكن موصى به: في لوحة معلومات Stripe، قم بإضافة نقطة نهاية خطاف الويب باستخدام URL هذا والأحداث Payment_intent.succeeded وPayment_intent.Payment_failed وPayment_intent.canceled وcharge.refunded وcustomer.subscription.updated وcustomer.subscription.deleted، ثم الصق سر التوقيع الخاص به أدناه.',
  '\\nWebhook signing secret\\n' => 'سر التوقيع على الويب',
  '\\nSaved - leave empty to keep it\\n' => 'تم الحفظ - اتركه فارغًا للاحتفاظ به',
  '\\nRemove the saved secret\\n' => 'قم بإزالة السر المحفوظ',
  '\\nInvalid or expired nonce\\n' => 'رقم غير صالح أو منتهية الصلاحية',
  '\\nNo payment provider is available on this site. Please contact the site administrator.\\n' => 'لا يتوفر أي مزود دفع على هذا الموقع. الرجاء الاتصال بمسؤول الموقع.',
  '\\nToo many payment attempts. Please wait a few minutes and try again.\\n' => 'محاولات الدفع كثيرة جدًا. الرجاء الانتظار بضع دقائق ثم حاول مرة أخرى.',
  '\\nInvalid payment data. Please refresh the page and try again.\\n' => 'بيانات الدفع غير صالحة. الرجاء تحديث الصفحة والمحاولة مرة أخرى.',
  '\\nThe payment provider is not configured on this site. Please contact the site administrator.\\n' => 'لم يتم تكوين موفر الدفع على هذا الموقع. الرجاء الاتصال بمسؤول الموقع.',
  '\\nNo payment amount detected. Please review your selected items and try again. If the problem persists, contact support.\\n' => 'لم يتم اكتشاف مبلغ الدفع. يرجى مراجعة العناصر المحددة والمحاولة مرة أخرى. إذا استمرت المشكلة، فاتصل بالدعم.',
  '\\nToo many requests. Please wait a moment and try again.\\n' => 'الطلبات كثيرة جدًا. الرجاء الانتظار قليلاً ثم حاول مرة أخرى.',
  '\\nPayment not found.\\n' => 'لم يتم العثور على الدفعة.',
  '\\nYour payment has not been confirmed yet. Please wait a moment and try again. If the problem persists, contact the site administrator.\\n' => 'لم يتم تأكيد دفعتك بعد. الرجاء الانتظار لحظة وحاول مرة أخرى. إذا استمرت المشكلة، اتصل بمسؤول الموقع.',
  '\\nOnline payment is not available at the moment. Please try again later or contact us.\\n' => 'الدفع عبر الإنترنت غير متاح في الوقت الحالي. يرجى المحاولة مرة أخرى لاحقاً أو الاتصال بنا.',
  '\\nActive payment provider\\n' => 'موفر الدفع النشط',
  '\\nPayment forms take card payments through this provider. Only installed providers are listed.\\n' => 'تستقبل نماذج الدفع دفعات البطاقة من خلال هذا الموفر. تم سرد الموفرين المثبتين فقط.',
  '\\nSaved — leave empty to keep\\n' => 'تم الحفظ — اتركه فارغًا للاحتفاظ به',
  '\\n%ssettings\\n' => ' إعدادات%s',
  '\\nFlux Forms replaces%s, which has been deactivated. Your forms, entries and settings stay in place. You can delete the old plugin.\\n' => 'تحل Flux Forms محل%s، الذي تم إلغاء تنشيطه. تظل النماذج والإدخالات والإعدادات الخاصة بك في مكانها. يمكنك حذف المكوّن الإضافي القديم.',
  '\\nUpdating amount...\\n' => 'جاري تحديث المبلغ...',
  '\\nThe amount could not be verified. Please check your selections and try again.\\n' => 'تعذر التحقق من المبلغ. الرجاء التحقق من اختياراتك والمحاولة مرة أخرى.',
  '\\nSubject made by Flux Forms (with the tracking code)\\n' => 'تم إنشاء الموضوع بواسطة Flux Forms (باستخدام رمز التتبع)',
