  'No checks are registered.' => 'لم يتم تسجيل أي شيكات.',
  'System check found %d problem(s) that can stop donations or automations.' => 'عثر فحص النظام على مشكلة (مشكلات)%d التي يمكنها إيقاف التبرعات أو عمليات التشغيل الآلي.',
  'Open system check' => 'فتح فحص النظام',
  'Hide until the next update' => 'إخفاء حتى التحديث القادم',
  'System: %d error(s)' => 'النظام: خطأ (أخطاء)%d',
  'This check could not run: %s' => 'تعذر تشغيل هذا الفحص: %s',
  'Scheduled tasks (cron)' => 'المهام المجدولة (كرون)',
  'Plugins' => 'الإضافات',
  'E-mail' => 'البريد الإلكتروني',
  'Security' => 'الأمن',
  '\\nPayment hand-off\\n' => 'تسليم الدفع',
  '\\nFlux Donate handles payments (providers, keys, webhooks): Donations › Payments.\\n' => 'يتعامل Flux Donate مع عمليات الدفع (المقدمون، المفاتيح، خطافات الويب): التبرعات › المدفوعات.',
  '[[\'Flux Donate is active but did not take over payments (filter flxb_own_payments is off?). Flux Forms uses its own Stripe settings.\\n' => 'Flux Donate نشط ولكنه لم يتولى الدفعات (تم إيقاف تشغيل عامل التصفية flxb_own_ Payments؟). يستخدم Flux Forms إعدادات Stripe الخاصة به.',
  '\\nFlux Donate is not active; Flux Forms takes payments itself with%s.\\n' => 'Flux Donate غير نشط؛ تتلقى Flux Forms الدفعات بنفسها باستخدام%s.',
  '[[\'Flux Donate is not active and the Stripe keys are missing:%dpayment form shows "Online payment is unavailable".\', \'en\']]' . chr(0) . '[[\'Flux Donate is not active and the Stripe keys are missing:%dpayment forms show "Online payment is unavailable".\', \'en\']]' => 'Flux Donate غير نشط والمفاتيح الشريطية مفقودة: تظهر نماذج الدفع %d"الدفع عبر الإنترنت غير متاح".' . chr(0) . 'Flux Donate غير نشط والمفاتيح الشريطية مفقودة: نموذج الدفع %dيعرض "الدفع عبر الإنترنت غير متاح".' . chr(0) . 'Flux Donate غير نشط والمفاتيح الشريطية مفقودة: تظهر نماذج الدفع %d"الدفع عبر الإنترنت غير متاح".' . chr(0) . 'Flux Donate غير نشط والمفاتيح الشريطية مفقودة: تظهر نماذج الدفع %d"الدفع عبر الإنترنت غير متاح".' . chr(0) . 'Flux Donate غير نشط والمفاتيح الشريطية مفقودة: تظهر نماذج الدفع %d"الدفع عبر الإنترنت غير متاح".' . chr(0) . 'Flux Donate غير نشط والمفاتيح الشريطية مفقودة: تظهر نماذج الدفع %d"الدفع عبر الإنترنت غير متاح".',
  '\\nFlux Donate is not active and no Stripe keys are set. No payment form exists, so nothing is affected.\\n' => 'Flux Donate غير نشط ولم يتم تعيين أي مفاتيح شريطية. لا يوجد نموذج دفع، لذلك لن يتأثر أي شيء.',
  '\\nPanel › Settings › Payment\\n' => 'اللوحة › الإعدادات › الدفع',
  '\\nNot active. Forms work; donations are not tracked and recurring iyzico payments are not available.\\n' => 'غير نشط. عمل النماذج؛ لا يتم تعقب التبرعات ولا تتوفر دفعات iyzico المتكررة.',
  '\\nFlux Certificates (automations)\\n' => 'شهادات التدفق (الأتمتة)',
  '\\nVersion%sis active; certificate automations can run.\\n' => 'الإصدار%sنشط؛ يمكن تشغيل عمليات أتمتة الشهادات.',
  '\\nVersion%1$sis active; certificate automations need%2$sor later.\\n' => 'الإصدار%1$sنشط؛ تحتاج عمليات أتمتة الشهادات إلى%2$sأو إصدار أحدث.',
  '[[\'Not active, but%dactive automation creates or sends certificates; it will fail.\', \'en\']]' . chr(0) . '[[\'Not active, but%dactive automations create or send certificates; they will fail.\', \'en\']]' => 'غير نشط، ولكن عمليات التشغيل التلقائي النشطة لـ%dتقوم بإنشاء الشهادات أو إرسالها؛ سوف يفشلون.' . chr(0) . 'غير نشط، ولكن التشغيل الآلي النشط لـ%dيقوم بإنشاء الشهادات أو إرسالها؛ سوف تفشل.' . chr(0) . 'غير نشط، ولكن عمليات التشغيل التلقائي النشطة لـ%dتقوم بإنشاء الشهادات أو إرسالها؛ سوف يفشلون.' . chr(0) . 'غير نشط، ولكن عمليات التشغيل التلقائي النشطة لـ%dتقوم بإنشاء الشهادات أو إرسالها؛ سوف يفشلون.' . chr(0) . 'غير نشط، ولكن عمليات التشغيل التلقائي النشطة لـ%dتقوم بإنشاء الشهادات أو إرسالها؛ سوف يفشلون.' . chr(0) . 'غير نشط، ولكن عمليات التشغيل التلقائي النشطة لـ%dتقوم بإنشاء الشهادات أو إرسالها؛ سوف يفشلون.',
