  '\\nAll sent messages are recorded in the Message History tab\\n' => 'يتم تسجيل كافة الرسائل المرسلة في علامة التبويب "محفوظات الرسائل"',
  '\\nSupported SMS Providers\\n' => 'موفري خدمة الرسائل القصيرة المعتمدين',
  '\\nForm Security & Spam Protection is disabled.\\n' => 'تم تعطيل أمان النماذج والحماية من البريد العشوائي.',
  '\\nThe security service is not available right now. Your form still works.\\n' => 'خدمة الأمان غير متوفرة الآن. النموذج الخاص بك لا يزال يعمل.',
  '\\nPlease refresh the form and try again.\\n' => 'الرجاء تحديث النموذج والمحاولة مرة أخرى.',
  '\\nToo many requests. Please try again shortly.\\n' => 'الطلبات كثيرة جدًا. الرجاء المحاولة مرة أخرى قريباً.',
  '[[\'Missing challenge.\\n' => 'التحدي مفقود.',
  '\\nExpired challenge.\\n' => 'انتهى التحدي.',
  '\\nChallenge already used.\\n' => 'تم استخدام التحدي بالفعل.',
