  '\\nThe Security & Spam Protection admin data could not be loaded. Another plugin may be blocking the script settings, or the page was cached. Reload the page; if it persists, disable admin script optimization for this page.\\n' => 'تعذر تحميل بيانات إدارة الأمان والحماية من البريد العشوائي. ربما يقوم مكون إضافي آخر بحظر إعدادات البرنامج النصي، أو قد تكون الصفحة مخزنة مؤقتًا. إعادة تحميل الصفحة؛ إذا استمرت المشكلة، قم بتعطيل تحسين البرنامج النصي للمسؤول لهذه الصفحة.',
  '\\nThe Security & Spam Protection panel failed to render. Reload the page or check the browser console.\\n' => 'فشل عرض لوحة الأمان والحماية من البريد العشوائي. أعد تحميل الصفحة أو تحقق من وحدة تحكم المتصفح.',
  '\\nProtection is paused: required PHP functions are disabled on this server:%s. Ask your host to remove them from the disable_functions line in php.ini. Your forms keep working without protection until then.\\n' => 'تم إيقاف الحماية مؤقتًا: تم تعطيل وظائف PHP المطلوبة على هذا الخادم: %s. اطلب من مضيفك إزالتها من سطر Disable_functions في php.ini. تستمر النماذج في العمل دون حماية حتى ذلك الحين.',
  '\\nProtection is paused: the add-on database tables could not be created. Check that the database user can CREATE tables, then reload this page.\\n' => 'تم إيقاف الحماية مؤقتاً: تعذر إنشاء جداول قاعدة البيانات الإضافية. تأكد من أن مستخدم قاعدة البيانات يمكنه إنشاء الجداول، ثم أعد تحميل هذه الصفحة.',
  '\\nProtection is paused: the WordPress REST API is not available on this site.\\n' => 'تم إيقاف الحماية مؤقتًا: واجهة برمجة تطبيقات WordPress REST غير متوفرة على هذا الموقع.',
  '\\nBehavior scoring\\n' => 'تسجيل السلوك',
