  '\\nForm global/min\\n' => 'نموذج عالمي/دقيقة',
  '[[\'Total submit pressure per form.\\n' => 'إجمالي ضغط الإرسال لكل نموذج.',
  '\\nTracking lookups per IP/min\\n' => 'تعقب عمليات البحث لكل IP/دقيقة',
  '\\nProtects confirmation-code lookup.\\n' => 'يحمي البحث عن رمز التأكيد.',
  '\\nResponses per IP/min\\n' => 'الإجابات لكل IP/الدقيقة',
  '\\nProtects public reply box.\\n' => 'يحمي مربع الرد العام.',
  '\\nReplies per tracking code/hour\\n' => 'الردود لكل رمز تتبع/ساعة',
  '\\nCaps replies to one tracked conversation (across IPs). 0 disables.\\n' => 'يقوم Caps بالرد على محادثة واحدة متعقبة (عبر عناوين IP). 0 معطل.',
  '\\nUploads per IP/min\\n' => 'التحميلات لكل IP/الدقيقة',
  '\\nProtects upload endpoint.\\n' => 'يحمي نقطة نهاية التحميل.',
  '\\nPayment starts per IP/min\\n' => 'يبدأ الدفع لكل IP/دقيقة',
  '\\nProtects payment REST routes.\\n' => 'يحمي مسارات الدفع REST.',
  '\\nFile upload budget\\n' => 'ميزانية تحميل الملف',
  '\\nFlux Forms already limits uploads on its own: each visitor may upload three files per file field on the form, and the response box allows three. Leave a box at 0 to keep that automatic behaviour, or enter a number to set it yourself.\\n' => 'تقيد Flux Forms عمليات التحميل من تلقاء نفسها: يمكن لكل زائر تحميل ثلاثة ملفات لكل حقل ملف في النموذج، ويسمح مربع الاستجابة بثلاثة. اترك المربع عند 0 للاحتفاظ بهذا السلوك التلقائي، أو أدخل رقمًا لتعيينه بنفسك.',
  '\\nUploads allowed per file field\\n' => 'التحميلات مسموحة لكل حقل ملف',
  '\\nDefault 3, so a two-field form allows six uploads. 0 keeps the default.\\n' => 'الافتراضي 3، لذا فإن النموذج المكون من حقلين يسمح بستة عمليات تحميل. 0 يحتفظ بالقيمة الافتراضية.',
  '\\nTotal uploads per visitor\\n' => 'إجمالي التحميلات لكل زائر',
  '\\nA fixed total that ignores how many fields the form has. 0 keeps the automatic per-field calculation.\\n' => 'إجمالي ثابت يتجاهل عدد الحقول التي يحتوي عليها النموذج. 0 يحتفظ بالحساب التلقائي لكل حقل.',
  '\\nBudget resets after (seconds)\\n' => 'يتم إعادة تعيين الميزانية بعد (ثواني)',
  '\\nDefault 3600 (one hour). 0 keeps the default.\\n' => 'الافتراضي 3600 (ساعة واحدة). 0 يحتفظ بالقيمة الافتراضية.',
  '\\nMaximum file size (MB)\\n' => 'الحد الأقصى لحجم الملف (ميجابايت)',
  '\\nA site-wide ceiling. It can only tighten a per-field limit, never widen it. 0 keeps the field setting.\\n' => 'سقف على مستوى الموقع. يمكنها فقط تشديد الحد لكل حقل، ولا توسعه أبدًا. 0 يحتفظ بإعدادات الحقل.',
  '\\nProtect response lookup\\n' => 'حماية البحث عن الاستجابة',
  '\\nRate-limit tracking-code searches by request count (no human-token check).\\n' => 'البحث عن كود التتبع بحدود المعدل حسب عدد الطلبات (بدون فحص الرمز المميز البشري).',
  '\\nManual access lists\\n' => 'قوائم الوصول اليدوي',
  '\\nOne entry per line: an exact IP or a wildcard prefix such as 203.0.113.* — allowlist bypasses all checks, blocklist blocks in every mode.\\n' => 'إدخال واحد في كل سطر: عنوان IP محدد أو بادئة بدل مثل 203.0.113.* — تتجاوز القائمة المسموح بها جميع عمليات التحقق، وتحظر قوائم الحظر في كل وضع.',
  '[[\'IP allowlist\\n' => 'القائمة المسموح بها لعنوان IP',
  '\\nTrusted IPs that skip the shield completely (your office, monitoring bots).\\n' => 'عناوين IP الموثوقة التي تتخطى الحماية تمامًا (مكتبك، برامج المراقبة).',
  '\\nIP blocklist\\n' => 'قائمة حظر IP',
  '\\nIPs that are always blocked on protected form routes.\\n' => 'عناوين IP المحظورة دائمًا على توجيهات النماذج المحمية.',
  '\\nMinimum paid notification score\\n' => 'الحد الأدنى لنتيجة الإشعارات المدفوعة',
  '\\nSuppress costly notifications below this score.\\n' => 'منع الإعلامات المكلفة التي تقل عن هذه النتيجة.',
  '[["SMS daily stop-loss\\n' => 'إيقاف الخسارة اليومي عبر الرسائل النصية القصيرة',
  '\\nGlobal SMS budget per day, across all recipients.\\n' => 'ميزانية الرسائل النصية القصيرة (SMS) العالمية يوميًا، عبر كافة المستلمين.',
  '\\nTelegram daily stop-loss\\n' => 'إيقاف الخسارة اليومي في تيليجرام',
  '\\nGlobal Telegram budget per day, across all recipients.\\n' => 'ميزانية Telegram العالمية يوميًا، عبر جميع المستلمين.',
  '\\nWebhook/Email daily stop-loss\\n' => 'الخطاف عبر الويب/البريد الإلكتروني لإيقاف الخسارة اليومي',
  '\\nGlobal webhook/email/sheet budget per day.\\n' => 'خطاف ويب عالمي/بريد إلكتروني/ميزانية ورقة يوميًا.',
  '\\nPer-recipient daily cap\\n' => 'الحد الأقصى اليومي لكل مستلم',
  '\\nMaximum notifications per single recipient per day (0 disables).\\n' => 'الحد الأقصى من الإشعارات لكل مستلم واحد في اليوم (0 تعطيل).',
  '\\nThese limits become active for paid services after the core integration filter is added.\\n' => 'تصبح هذه الحدود نشطة للخدمات المدفوعة بعد إضافة عامل تصفية التكامل الأساسي.',
  '\\nDecisions — last 24 hours\\n' => 'القرارات — آخر 24 ساعة',
  '\\nStacked per hour: allowed, blocked, quarantined and monitored requests.\\n' => 'مجمعة لكل ساعة: الطلبات المسموح بها، والمحظورة، والمعزولة، والمراقبة.',
  '\\nNo decisions recorded in the last 24 hours.\\n' => 'لم يتم تسجيل أي قرارات خلال 24 ساعة الماضية.',
  '\\nSecurity logs\\n' => 'سجلات الأمان',
  '\\nRecent decisions without storing raw IP addresses.\\n' => 'القرارات الأخيرة دون تخزين عناوين IP الأولية.',
  '\\nClear Human Shield logs?\\n' => 'هل تريد مسح سجلات Human Shield؟',
  '[[\'Logs cleared.\\n' => 'تم مسح السجلات.',
  'Recent activity' => 'النشاط الأخير',
  '\\nLatest security decisions.\\n' => 'أحدث قرارات الأمان.',
  '\\nNo logs yet.\\n' => 'لا توجد سجلات حتى الآن.',
  '\\nRoute\\n' => 'المسار',
  'Decision' => 'القرار',
  '[[\'Score\\n' => 'النتيجة',
  '\\nReasons\\n' => 'الأسباب',
