  '\\nPHP requirements are ready.\\n' => 'متطلبات PHP جاهزة.',
  '\\nSome required PHP functions are unavailable.", \'en\']]' => 'بعض وظائف PHP المطلوبة غير متوفرة.',
  '\\nREST API:\\n' => 'واجهة برمجة تطبيقات REST:',
  '\\navailable\\n' => 'متوفر',
