  '\\nTables:\\n' => 'الجداول:',
  '\\nready\\n' => 'جاهز',
  '\\nnot ready yet\\n' => 'ليست جاهزة بعد',
  '\\nRecommended only after you verify PHP functions and tables are ready.\\n' => 'يوصى به فقط بعد التحقق من أن وظائف وجداول PHP جاهزة.',
  '\\nTrust proxy IP headers\\n' => 'الوثوق برؤوس IP للوكيل',
  '\\nUse forwarding headers only when the immediate peer matches the trusted proxy list below.\\n' => 'استخدم إعادة توجيه الرؤوس فقط عندما يتطابق النظير المباشر مع قائمة الوكيل الموثوق به أدناه.',
  '\\nTrusted proxy IPs\\n' => 'عناوين IP الوكيلة الموثوقة',
  '\\nOne exact IP or wildcard prefix per line. Add only your load balancer/CDN egress addresses; keep this empty when the origin is directly reachable.\\n' => 'عنوان IP أو بادئة بدل واحدة محددة لكل سطر. أضف فقط موازن التحميل/عناوين خروج CDN الخاصة بك؛ أبقِ هذا فارغًا عندما يكون من الممكن الوصول إلى الأصل مباشرةً.',
  '\\nStore raw behavior metrics\\n' => 'تخزين مقاييس السلوك الأولية',
  '\\nKeep off for privacy unless debugging a rollout.\\n' => 'توقف عن العمل للحفاظ على الخصوصية ما لم يتم تصحيح أخطاء الطرح.',
  '\\nLog retention days\\n' => 'تسجيل أيام الاحتفاظ',
  '\\nHow long events should be retained.\\n' => 'مدة الاحتفاظ بالأحداث.',
  '\\nClient attestation timeout\\n' => 'انتهت مهلة تصديق العميل',
  '\\nMilliseconds before the browser falls back to the normal request.\\n' => 'ملي ثانية قبل عودة المستعرض إلى الطلب العادي.',
  '\\nIf a required PHP function is disabled, enable it in php.ini disable_functions or ask the host to allow it. Cache and security plugins must not cache or rewrite POST responses from /wp-json/EmsfbShield/v1/*.\\n' => 'إذا تم تعطيل إحدى وظائف PHP المطلوبة، قم بتمكينها في php.ini Disable_functions أو اطلب من المضيف السماح بذلك. يجب ألا تقوم ذاكرة التخزين المؤقت والمكونات الإضافية للأمان بالتخزين المؤقت أو إعادة كتابة استجابات POST من /wp-json/EmsfbShield/v1/*.',
  '\\nSecurity & Spam Protection tabs\\n' => 'علامات التبويب "الأمان والحماية من البريد العشوائي"',
  '\\nSecurity log export is unavailable because this server has disabled a required PHP function:%s. Ask your hosting provider to enable it.\\n' => 'تصدير سجل الأمان غير متاح لأن هذا الملقم قام بتعطيل وظيفة PHP مطلوبة: %s. اطلب من موفر الاستضافة تمكينه.',
  '\\nSecurity log export is unavailable because this server has disabled required PHP functions:%s. Ask your hosting provider to enable them.\\n' => 'تصدير سجل الأمان غير متاح لأن هذا الملقم قام بتعطيل وظائف PHP المطلوبة: %s. اطلب من موفر الاستضافة تمكينها.',
  '\\nAuto-Populate Dataset\\n' => 'ملء مجموعة البيانات تلقائيًا',
