  '\\nUpload Dataset\\n' => 'تحميل مجموعة البيانات',
  '\\nIn Form Builder, open Form Settings and enable "Auto-Populate". Choose your dataset, then map elements to dataset fields as search conditions.\', \'en\']]' => 'في "منشئ النماذج"، افتح "إعدادات النموذج" وقم بتمكين "الملء التلقائي". اختر مجموعة البيانات الخاصة بك، ثم قم بتعيين العناصر إلى حقول مجموعة البيانات كشروط بحث.',
  '\\nEnable Auto-Populate\\n' => 'تمكين الملء التلقائي',
  '[[\'For each target field, enable "Auto-Populate to automatically populate this field" and select the dataset column to auto-populate.\\n' => 'بالنسبة لكل حقل مستهدف، قم بتمكين "الملء التلقائي لملء هذا الحقل تلقائيًا" وحدد عمود مجموعة البيانات لملءه تلقائيًا.',
  '\\nMap Fields\\n' => 'حقول الخريطة',
  '\\nYou can edit dataset values inline by clicking on them.\\n' => 'يمكنك تحرير قيم مجموعة البيانات بشكل مضمّن عن طريق النقر عليها.',
  '\\nFollow these steps to set up auto-populate for your forms\\n' => 'اتبع هذه الخطوات لإعداد التعبئة التلقائية للنماذج الخاصة بك',
  '\\nQuick Start Guide\\n' => 'دليل البدء السريع',
  '\\nTips & Notes\\n' => 'نصائح وملاحظات',
  '\\nEditing Data\\n' => 'تحرير البيانات',
  '\\nSupported format: CSV with UTF-8 encoding.\\n' => 'التنسيق المعتمد: ملف CSV بتشفير UTF-8.',
  '\\nForm Builder Tips\\n' => 'نصائح منشئ النماذج',
  '[[\'Use conditions to filter dataset rows based on user input.\\n' => 'استخدم الشروط لتصفية صفوف مجموعة البيانات بناءً على إدخال المستخدم.',
  '\\nMultiple fields can auto-populate from the same dataset.\\n' => 'يمكن تعبئة الحقول المتعددة تلقائيًا من نفس مجموعة البيانات.',
  'Good to know' => 'من الجيد أن نعرف',
  '\\nChanges to the dataset take effect immediately for new form submissions.\\n' => 'تسري التغييرات على مجموعة البيانات فورًا لعمليات إرسال النماذج الجديدة.',
  '\\nConnect & Manage API Integrations\\n' => 'الاتصال وإدارة عمليات تكامل واجهة برمجة التطبيقات',
