  '\\nAdd Connection\\n' => 'إضافة اتصال',
  '\\nConfigure authentication (API Key, Bearer Token, or Basic Auth) if your API requires it.\\n' => 'قم بتكوين المصادقة (مفتاح API، أو Bearer Token، أو المصادقة الأساسية) إذا كانت API لديك تتطلب ذلك.',
  'Authentication' => 'المصادقة',
  '\\nSelect a form and map API response fields to your form fields for auto-populate.\\n' => 'حدد نموذجًا وقم بتعيين حقول استجابة واجهة برمجة التطبيقات (API) إلى حقول النموذج الخاص بك لملءها تلقائيًا.',
  '\\nUse the Test button to verify the API returns expected data, then save your connection.\\n' => 'استخدم الزر "اختبار" للتحقق من قيام API بإرجاع البيانات المتوقعة، ثم احفظ اتصالك.',
