  '\\nGoogle Sheet\\n' => 'جدول بيانات Google',
  '\\nSync Form Responses to Google Sheets\\n' => 'مزامنة استجابات النماذج مع جداول بيانات Google',
  '\\nAutomatically send form submissions to your Google Sheets. Connect one or more service accounts, link a sheet to each form, and let data flow in real time — no webhook or browser login required.\\n' => 'أرسل عمليات إرسال النماذج تلقائيًا إلى جداول بيانات Google. قم بتوصيل حساب خدمة واحد أو أكثر، وربط ورقة بكل نموذج، والسماح بتدفق البيانات في الوقت الحقيقي - لا يلزم وجود خطاف ويب أو تسجيل دخول للمتصفح.',
  'Connected' => 'متصل',
  '\\nNot Connected\\n' => 'غير متصل',
  '\\nAuto Sync\\n' => 'مزامنة تلقائية',
  '\\nAuto Header\\n' => 'رأس تلقائي',
  '\\nSync Logs\\n' => 'سجلات المزامنة',
  '\\nGoogle Sheet Settings\\n' => 'إعدادات ورقة Google',
  '\\nActive Bindings\\n' => 'الارتباطات النشطة',
  '[[\'Form\', \'en\']]' . chr(0) . '[[\'Forms\', \'en\']]' => 'النماذج' . chr(0) . 'نموذج' . chr(0) . 'النماذج' . chr(0) . 'النماذج' . chr(0) . 'النماذج' . chr(0) . 'النماذج',
  '[[\'%dservice account connected\', \'en\']]' . chr(0) . '[[\'%dservice accounts connected\', \'en\']]' => 'حسابات خدمة %dمتصلة' . chr(0) . 'تم توصيل حساب خدمة %d' . chr(0) . 'حسابات خدمة %dمتصلة' . chr(0) . 'حسابات خدمة %dمتصلة' . chr(0) . 'حسابات خدمة %dمتصلة' . chr(0) . 'حسابات خدمة %dمتصلة',
  '\\nNo service account connected yet\\n' => 'لم يتم توصيل أي حساب خدمة حتى الآن',
  '\\nForm Bindings\\n' => 'ارتباطات النموذج',
  '\\nHelp & Guide\\n' => 'تعليمات وتوجيهات',
  'Something went wrong.' => 'حدث خطأ ما.',
  '\\nSaved successfully.\\n' => 'تم الحفظ بنجاح.',
  'Remove' => 'إزالة',
  '\\nOpen in Google Sheets\\n' => 'فتح في جداول بيانات Google',
  '\\nService Accounts\\n' => 'حسابات الخدمة',
  '\\nConnect one or more Google service accounts — no browser login required\\n' => 'قم بتوصيل حساب واحد أو أكثر من حسابات خدمة Google — لا يلزم تسجيل الدخول إلى المتصفح',
  '\\nYour server is missing the PHP OpenSSL extension.\\n' => 'يفتقد الملقم الخاص بك ملحق PHP OpenSSL.',
  '\\nGoogle Sheet sync cannot work until it is enabled. Please ask your host to enable the%sPHP extension, then reload this page.\\n' => 'لا يمكن أن تعمل مزامنة جداول بيانات Google حتى يتم تمكينها. الرجاء مطالبة مضيفك بتمكين ملحق%sPHP، ثم إعادة تحميل هذه الصفحة.',
  'Not tested' => 'لم يتم اختباره',
  '\\nCopy this email\\n' => 'انسخ هذا البريد الإلكتروني',
  '\\nCopy email\\n' => 'نسخ البريد الإلكتروني',
  '\\nTo sync an<strong>existing</strong>sheet: open it in Google Sheets →<strong>Share</strong>→ paste the email above → set role to<strong>Editor</strong>. To create a<strong>new</strong>sheet, just use Form Bindings — no sharing needed.\\n' => 'لمزامنة ورقة<strong>موجودة في</strong>: افتحها في جداول بيانات Google ←<strong>شارك</strong>← الصق البريد الإلكتروني أعلاه ← اضبط الدور على<strong>Editor</strong>. لإنشاء ورقة<strong>جديدة</strong>، ما عليك سوى استخدام روابط النماذج — لا حاجة للمشاركة.',
  '\\nSet Default\\n' => 'تعيين كافتراضي',
  '\\nRetest\\n' => 'إعادة الاختبار',
  '\\nLet’s connect Google Sheets — about 3 minutes, one time\', \'en\']]' => 'دعونا نربط جداول بيانات Google — حوالي 3 دقائق، مرة واحدة',
  '\\nFollow the numbered steps on the right to download a free service account key from Google, then drop the file below. You only do this once. After that, creating a sheet for any form is a couple of clicks.\\n' => 'اتبع الخطوات المرقمة على اليمين لتنزيل مفتاح حساب خدمة مجاني من Google، ثم قم بإسقاط الملف أدناه. أنت تفعل هذا مرة واحدة فقط. بعد ذلك، يتم إنشاء ورقة لأي نموذج ببضع نقرات.',
  '\\nYour Google email\\n' => 'بريدك الإلكتروني على Google',
  '\\n(recommended)\\n' => '(مستحسن)',
  '\\nAny sheet the plugin<strong>creates</strong>is automatically shared to this address, so it appears in your own Google Drive under “Shared with me.” Without it, new sheets stay hidden inside the service account.\\n' => 'أي ورقة ينشئها المكون الإضافي<strong></strong>تتم مشاركتها تلقائيًا على هذا العنوان، لذلك تظهر في Google Drive الخاص بك ضمن "تمت مشاركتها معي". وبدون ذلك، تظل الأوراق الجديدة مخفية داخل حساب الخدمة.',
  '\\nEnable Google Sheet Integration\\n' => 'تمكين تكامل جداول بيانات Google',
  '\\nSync form submissions to your spreadsheets automatically\\n' => 'مزامنة عمليات إرسال النماذج إلى جداول البيانات تلقائيًا',
  '\\nDrag & drop service account JSON file(s) here\\n' => 'قم بسحب وإفلات ملف (ملفات) حساب الخدمة JSON هنا',
  '\\nor click to browse — you can add multiple service accounts at once\\n' => 'أو انقر للتصفح — يمكنك إضافة حسابات خدمة متعددة في وقت واحد',
  '\\nConnected service accounts\\n' => 'حسابات الخدمة المتصلة',
  '\\nOne-time setup (≈3 min)\\n' => 'الإعداد لمرة واحدة (≈3 دقائق)',
  '\\nGo to<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a>→ Project dropdown (top-left) → New Project → name it → Create\\n' => 'انتقل إلى<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a>→ القائمة المنسدلة للمشروع (أعلى اليسار) → مشروع جديد → قم بتسميته → إنشاء',
  '\\nAPIs & Services → Library → enable<strong>Google Sheets API</strong><em>and</em><strong>Google Drive API</strong>\\n' => 'واجهات برمجة التطبيقات والخدمات → المكتبة → تمكين<strong>Google Sheets API</strong><em>و</em><strong>Google Drive API</strong>',
  '\\nAPIs & Services → Credentials → Create Credentials → Service Account → name it → Done\\n' => 'واجهات برمجة التطبيقات والخدمات → بيانات الاعتماد → إنشاء بيانات الاعتماد → حساب الخدمة → قم بتسميته → تم',
  '\\nOpen the service account → Keys tab → Add Key → Create New Key → JSON (downloads automatically)\\n' => 'افتح حساب الخدمة ← علامة تبويب المفاتيح ← إضافة مفتاح ← إنشاء مفتاح جديد ← JSON (يتم التنزيل تلقائيًا)',
  '\\nDrag that downloaded file into the box on the left — it is tested automatically\\n' => 'اسحب الملف الذي تم تنزيله إلى المربع الموجود على اليسار — سيتم اختباره تلقائيًا',
  '\\nAdd<strong>Your Google email</strong>above so created sheets land in your Drive\\n' => 'أضف<strong>بريدك الإلكتروني في Google</strong>أعلاه بحيث تصل الأوراق التي تم إنشاؤها إلى Drive',
  '\\nPlease choose a valid .json key file.\\n' => 'الرجاء اختيار ملف مفتاح .json صالح.',
  '\\nCould not read file:%s\\n' => 'تعذرت قراءة الملف: %s',
  '\\nConnecting service account...\\n' => 'جارٍ توصيل حساب الخدمة...',
  '\\nService account added.\\n' => 'تمت إضافة حساب الخدمة.',
  '\\nSaved. New sheets created by the plugin will be shared to%sautomatically.\\n' => 'تم الحفظ. ستتم مشاركة الأوراق الجديدة التي أنشأها البرنامج الإضافي مع%sتلقائيًا.',
  '\\nEmail cleared. New sheets will stay inside the service account until you share them.\\n' => 'تم مسح البريد الإلكتروني. ستبقى الأوراق الجديدة داخل حساب الخدمة حتى تقوم بمشاركتها.',
  '\\nRemove this service account?\\n' => 'هل تريد إزالة حساب الخدمة هذا؟',
  '\\nConnect each form to a specific Google Sheet tab\\n' => 'قم بتوصيل كل نموذج بعلامة تبويب معينة في ورقة Google',
  '\\nConnect each form to a specific Google Sheet tab — step by step\\n' => 'قم بتوصيل كل نموذج بعلامة تبويب معينة في جدول بيانات Google - خطوة بخطوة',
  '\\nNo service account connected.\\n' => 'لا يوجد حساب خدمة متصل.',
  '\\nGo to the Connections tab and drop a service account JSON key first.\\n' => 'انتقل إلى علامة التبويب "الاتصالات" وقم بإسقاط مفتاح JSON لحساب الخدمة أولاً.',
  '\\nLast sync OK\\n' => 'موافقة آخر مزامنة',
  '\\nLast sync failed\\n' => 'فشلت آخر مزامنة',
  '\\nRemove sync? The sheet stays safe.\\n' => 'هل تريد إزالة المزامنة؟ تظل الورقة آمنة.',
  '\\nYes, remove\\n' => 'نعم، قم بالإزالة',
  '\\nRemove this sync (your Google Sheet is not deleted)\\n' => 'قم بإزالة هذه المزامنة (لم يتم حذف جدول بيانات Google الخاص بك)',
  '\\nExisting Bindings\\n' => 'الارتباطات الموجودة',
  '\\nDelete All\\n' => 'حذف الكل',
  '\\nNew Binding\\n' => 'ربط جديد',
  '\\nSpreadsheet ID\\n' => 'معرف جدول البيانات',
  '\\ntab\\n' => 'علامة التبويب',
  '\\nChoose Sheet\\n' => 'اختر ورقة',
  '\\nColumns & Fields\\n' => 'الأعمدة والحقول',
  '\\nStyle & Save\\n' => 'التصميم والحفظ',
  '\\nWhich form should send data to Google Sheets?\\n' => 'ما هو النموذج الذي يجب أن يرسل البيانات إلى جداول بيانات Google؟',
  '\\nPlease select a form first.\\n' => 'الرجاء تحديد نموذج أولاً.',
  '\\nService Account\\n' => 'حساب الخدمة',
  '\\nLoading your spreadsheets...\\n' => 'جارٍ تحميل جداول البيانات...',
  '\\nClick<strong>“Browse My Sheets”</strong>to list spreadsheets this service account can already access, or<strong>“Create New Sheet”</strong>to make a fresh one.\\n' => 'انقر فوق<strong>"استعراض أوراقي"</strong>لسرد جداول البيانات التي يمكن لحساب الخدمة هذا الوصول إليها بالفعل، أو<strong>"إنشاء ورقة جديدة"</strong>لإنشاء ورقة جديدة.',
  '\\n<strong>No spreadsheets are accessible to this service account yet.</strong>You have two options:\\n' => '<strong>لا يمكن الوصول إلى جداول البيانات لحساب الخدمة هذا حتى الآن.</strong>لديك خياران:',
  '\\n<strong>Easiest:</strong>click<em>“Create New Sheet”</em>above — it is made for you and shared to your email automatically.\\n' => '<strong>الأسهل:</strong>انقر فوق<em>"إنشاء ورقة جديدة"</em>أعلاه — فهي مصممة خصيصًا لك ويتم مشاركتها مع بريدك الإلكتروني تلقائيًا.',
  '\\n<strong>Use an existing sheet:</strong>open it in Google Sheets → Share → paste\\n' => '<strong>استخدم ورقة موجودة:</strong>افتحها في جداول بيانات Google → مشاركة → لصق',
  '\\n→ Editor, then click<em>Browse My Sheets</em>again.\\n' => '→ المحرر، ثم انقر فوق<em>"استعراض الأوراق الخاصة بي"</em>مرة أخرى.',
  '\\nthe service account email\\n' => 'البريد الإلكتروني لحساب الخدمة',
  '\\nCreate a new spreadsheet\\n' => 'إنشاء جدول بيانات جديد',
  '\\nNew spreadsheet title (e.g. Contact form responses)\\n' => 'عنوان جدول بيانات جديد (على سبيل المثال، ردود نماذج الاتصال)',
  '\\nYour Google email — the sheet is shared here so you can open it\\n' => 'بريدك الإلكتروني على Google — تتم مشاركة الورقة هنا حتى تتمكن من فتحها',
  '\\nPre-filled from your saved email.\\n' => 'تم ملؤها مسبقًا من بريدك الإلكتروني المحفوظ.',
  '\\nLeave empty only if you don’t need to open the sheet yourself.\\n' => 'اتركه فارغًا فقط إذا لم تكن بحاجة إلى فتح الورقة بنفسك.',
  '\\nCreate Sheet\\n' => 'إنشاء ورقة',
  '\\nCreating...\\n' => 'جارٍ الإنشاء...',
  '\\nCreating spreadsheet...\\n' => 'جاري إنشاء جدول بيانات...',
  '\\nSheet created and shared with your email. It’s selected below — click Next to finish.\\n' => 'تم إنشاء الورقة ومشاركتها مع بريدك الإلكتروني. تم تحديده أدناه — انقر فوق "التالي" للإنهاء.',
  '\\nSheet created. Tip: add “Your Google email” on the Connections tab so new sheets are shared to you automatically.\\n' => 'تم إنشاء الورقة. نصيحة: أضف "بريدك الإلكتروني على Google" في علامة التبويب "الاتصالات" حتى تتم مشاركة الأوراق الجديدة معك تلقائيًا.',
  '\\nOpen the new sheet\\n' => 'افتح الورقة الجديدة',
  '\\nSelected:\\n' => 'محدد:',
  '\\nLoading worksheet tabs...\\n' => 'جاري تحميل علامات تبويب أوراق العمل...',
  '\\nWorksheet Tab\\n' => 'علامة تبويب ورقة العمل',
  '\\nOr type a new tab name (created automatically)\\n' => 'أو اكتب اسم علامة تبويب جديدة (يتم إنشاؤها تلقائيًا)',
  '\\nBrowse My Sheets\\n' => 'تصفح أوراقي',
  '\\nCreate New Sheet\\n' => 'إنشاء ورقة جديدة',
  '\\nChoose or create a spreadsheet first\\n' => 'اختر جدول بيانات أو أنشئه أولاً',
  '\\nPlease select a service account.\\n' => 'الرجاء تحديد حساب خدمة.',
  '\\nPlease choose or create a spreadsheet first.\\n' => 'الرجاء اختيار أو إنشاء جدول بيانات أولاً.',
  '\\nEnable Sync for this Form\\n' => 'تمكين المزامنة لهذا النموذج',
  '\\nDisable to pause without deleting the binding\\n' => 'تعطيل الإيقاف المؤقت دون حذف الارتباط',
  '\\nReading this form’s fields...\\n' => 'قراءة حقول هذا النموذج...',
  '\\nWe couldn’t read this form’s fields automatically, so column mapping isn’t available. Don’t worry —<strong>every submitted field will still be synced automatically</strong>, each in its own column, in submission order. The header row is created and kept up to date for you.\\n' => 'لم نتمكن من قراءة حقول هذا النموذج تلقائيًا، لذا فإن تعيين الأعمدة غير متاح. لا تقلق —<strong>ستتم مزامنة كل حقل مُرسل تلقائيًا</strong>، كل في العمود الخاص به، بترتيب الإرسال. يتم إنشاء صف الرأس وتحديثه لك.',
  '\\nDrag rows (or use ▲▼) to set the<strong>column order</strong>. Rename any<strong>header</strong>. Turn a field off to skip its column. The letter (A, B, C...) shows where each field lands.\\n' => 'اسحب الصفوف (أو استخدم ▲▼) لتعيين ترتيب الأعمدة<strong></strong>. إعادة تسمية أي رأس<strong></strong>. قم بإيقاف تشغيل الحقل لتخطي العمود الخاص به. يُظهر الحرف (A، B، C...) مكان وصول كل حقل.',
  '\\nCol\\n' => 'العقيد',
  '\\nSpreadsheet header\\n' => 'رأس جدول البيانات',
  '\\nOrder / On\\n' => 'الطلب / تشغيل',
  '\\nRefresh fields from form\\n' => 'تحديث الحقول من النموذج',
  '\\nColumns & Field Mapping\\n' => 'تعيين الأعمدة والحقول',
  '\\nSubmitted time\\n' => 'وقت الإرسال',
  'built-in' => 'مدمج',
  '\\nSubmitted At\\n' => 'تم الإرسال في',
  '\\nColumn header\\n' => 'رأس العمود',
  'Drag to reorder' => 'اسحب لإعادة الترتيب',
  '\\nInclude this field\\n' => 'قم بتضمين هذا الحقل',
  '[[\'%dcolumn will be written to the sheet.\', \'en\']]' . chr(0) . '[[\'%dcolumns will be written to the sheet.\', \'en\']]' => 'ستتم كتابة أعمدة %dفي الورقة.' . chr(0) . 'ستتم كتابة عمود %dعلى الورقة.' . chr(0) . 'ستتم كتابة أعمدة %dفي الورقة.' . chr(0) . 'ستتم كتابة أعمدة %dفي الورقة.' . chr(0) . 'ستتم كتابة أعمدة %dفي الورقة.' . chr(0) . 'ستتم كتابة أعمدة %dفي الورقة.',
  '\\nSheet Style\\n' => 'نمط الورقة',
  '\\n(Google theme)\', \'en\']]' => '(موضوع Google)',
  '[[\'Pick a look for the sheet — colored header, frozen top row and alternating row colors (Google Sheets’ own styling). It’s applied automatically on the first sync, or apply it now.\\n' => 'اختر مظهرًا للورقة - الرأس الملون والصف العلوي المجمد وألوان الصفوف البديلة (التصميم الخاص بجداول بيانات Google)." يتم تطبيقه تلقائيًا عند المزامنة الأولى، أو قم بتطبيقه الآن.',
  '\\nApply style now\\n' => 'تطبيق النمط الآن',
  '\\nApplying...\\n' => 'جارٍ التقديم...',
  '\\nOptional — it also applies on the first submission.\\n' => 'اختياري — ينطبق أيضًا على الإرسال الأول.',
  '\\nSpreadsheet:\\n' => 'جدول البيانات:',
  '\\nTab:\\n' => 'علامة التبويب:',
  '\\nColumns:\\n' => 'الأعمدة:',
  '\\n%dmapped\\n' => ' تم تعيين%d',
  '\\nall submitted fields (auto)\\n' => 'كافة الحقول المرسلة (تلقائي)',
  '\\nStyle:\\n' => 'النمط:',
  '\\nAfter saving, submit the form once to create the header row and confirm the first sync.\\n' => 'بعد الحفظ، قم بإرسال النموذج مرة واحدة لإنشاء صف الرأس وتأكيد المزامنة الأولى.',
  '\\nSave Binding\\n' => 'حفظ الربط',
  '[[\'Please choose a spreadsheet first.\\n' => 'الرجاء اختيار جدول بيانات أولاً.',
  '\\nPick a style first — “None” leaves the sheet unstyled.\\n' => 'اختر نمطًا أولاً — يؤدي اختيار "بلا" إلى ترك الورقة بدون نمط.',
  '\\nStyle applied.\\n' => 'تم تطبيق النمط.',
  '\\nPlease select a form.\\n' => 'الرجاء تحديد نموذج.',
  '\\nPlease choose a spreadsheet.\\n' => 'الرجاء اختيار جدول بيانات.',
  '\\nBinding saved.\\n' => 'تم حفظ التضمين.',
  '\\nRemove this binding? Syncing stops for this form. Your Google Sheet and its data are not deleted.\\n' => 'هل تريد إزالة هذا الارتباط؟ تتوقف المزامنة لهذا النموذج. لن يتم حذف جدول بيانات Google الخاص بك وبياناته.',
  '\\nSync removed — your Google Sheet and its data are untouched.\\n' => 'تمت إزالة المزامنة - لم يتم تغيير جدول بيانات Google الخاص بك وبياناته.',
  '[[\'Remove ALL%dbinding? Syncing stops for every form. Your Google Sheets are not deleted.\', \'en\']]' . chr(0) . '[[\'Remove ALL%dbindings? Syncing stops for every form. Your Google Sheets are not deleted.\', \'en\']]' => 'إزالة جميع روابط%d؟ تتوقف المزامنة لكل نموذج. لم يتم حذف جداول بيانات Google الخاصة بك.' . chr(0) . 'إزالة جميع روابط%d؟ تتوقف المزامنة لكل نموذج. لم يتم حذف جداول بيانات Google الخاصة بك.' . chr(0) . 'إزالة جميع روابط%d؟ تتوقف المزامنة لكل نموذج. لم يتم حذف جداول بيانات Google الخاصة بك.' . chr(0) . 'إزالة جميع روابط%d؟ تتوقف المزامنة لكل نموذج. لم يتم حذف جداول بيانات Google الخاصة بك.' . chr(0) . 'إزالة جميع روابط%d؟ تتوقف المزامنة لكل نموذج. لم يتم حذف جداول بيانات Google الخاصة بك.' . chr(0) . 'إزالة جميع روابط%d؟ تتوقف المزامنة لكل نموذج. لم يتم حذف جداول بيانات Google الخاصة بك.',
  '\\nAll bindings removed. Your Google Sheets are untouched.\\n' => 'تمت إزالة كافة الارتباطات. لم يتم تغيير جداول بيانات Google الخاصة بك.',
  '\\nHelp & Setup Guide\\n' => 'دليل التعليمات والإعداد',
  '\\nEverything you need to connect forms to Google Sheets\\n' => 'كل ما تحتاجه لربط النماذج بجداول بيانات Google',
  '\\nStep-by-Step Setup\\n' => 'الإعداد خطوة بخطوة',
  '\\nCreate or Select a Project\\n' => 'إنشاء مشروع أو تحديده',
  '\\nOpen console.cloud.google.com and log in → click the Project dropdown (top-left) → New Project (or pick an existing one) → enter a name → Create\', \'en\']]' => 'افتح console.cloud.google.com وقم بتسجيل الدخول ← انقر على القائمة المنسدلة "المشروع" (أعلى اليسار) ← مشروع جديد (أو اختر مشروعًا موجودًا) ← أدخل اسمًا ← إنشاء',
  '\\nEnable both Google APIs\\n' => 'تمكين كلا واجهتي Google APIs',
  '\\nAPIs & Services → Library → enable<strong>Google Sheets API</strong>and<strong>Google Drive API</strong>(both are required — Drive lists and creates the files)\\n' => 'واجهات برمجة التطبيقات والخدمات → المكتبة → تمكين<strong>Google Sheets API</strong>و<strong>Google Drive API</strong>(كلاهما مطلوب — قوائم Drive وإنشاء الملفات)',
  '\\nCreate a Service Account\\n' => 'إنشاء حساب خدمة',
  '\\nAPIs & Services → Credentials → Create Credentials → Service Account → enter a name → Done\\n' => 'واجهات برمجة التطبيقات والخدمات → بيانات الاعتماد → إنشاء بيانات الاعتماد → حساب الخدمة → أدخل اسمًا → تم',
  '\\nCreate a JSON Key\\n' => 'إنشاء مفتاح JSON',
  '\\nOpen the service account → Keys tab → Add Key → Create New Key → choose JSON (file downloads automatically)\\n' => 'افتح حساب الخدمة ← علامة تبويب المفاتيح ← إضافة مفتاح ← إنشاء مفتاح جديد ← اختر JSON (يتم تنزيل الملف تلقائيًا)',
  '\\nDrop the Key File\\n' => 'أسقط ملف المفتاح',
  '\\nDrag the downloaded file into the Connections tab — it is verified automatically and you’ll see a green “Connected” badge\\n' => 'اسحب الملف الذي تم تنزيله إلى علامة التبويب "الاتصالات" — يتم التحقق منه تلقائيًا وستظهر لك شارة "متصل" باللون الأخضر',
  '\\nAdd Your Google Email\\n' => 'أضف بريدك الإلكتروني على Google',
  '\\nOn the Connections tab, fill in “Your Google email” and Save — sheets the plugin creates are then shared to you so they appear in your own Drive\\n' => 'في علامة التبويب "الاتصالات"، املأ "بريدك الإلكتروني في Google" ثم احفظ - تتم بعد ذلك مشاركة الأوراق التي ينشئها المكون الإضافي معك حتى تظهر في Drive الخاص بك',
  '\\nBind a Form (create a sheet)\\n' => 'ربط نموذج (إنشاء ورقة)',
  '\\nForm Bindings → pick a form →<strong>Create New Sheet</strong>→ Save. No manual sharing needed — this is the easiest path\\n' => 'ربط النماذج ← اختر نموذجًا ←<strong>إنشاء ورقة جديدة</strong>← حفظ. ليست هناك حاجة للمشاركة اليدوية — هذا هو المسار الأسهل',
  '\\n...or use an existing sheet\\n' => '...أو استخدم ورقة موجودة',
  '\\nPrefer your own sheet? Open it → Share → paste the service account email (copy button on its card) → Editor → then Browse My Sheets in the wizard", \'en\']]' => 'هل تفضل ورقتك الخاصة؟ افتحه ← مشاركة ← الصق البريد الإلكتروني لحساب الخدمة (زر النسخ على بطاقته) ← المحرر ← ثم تصفح أوراقي في المعالج"، \'en\']]',
  'FAQ' => 'الأسئلة الشائعة',
  '\\nI created a sheet — where did it go?\\n' => 'لقد قمت بإنشاء ورقة — أين ذهبت؟',
  '\\nService accounts create files in their own hidden Drive. Add “Your Google email” on the Connections tab and the plugin shares every new sheet to you automatically — it then appears under “Shared with me” in your Google Drive. Each sheet also has an “Open” link right in this dashboard.\\n' => 'تنشئ حسابات الخدمة ملفات في محرك الأقراص المخفي الخاص بها. أضف "بريدك الإلكتروني على Google" في علامة التبويب "الاتصالات" وسيشارك المكون الإضافي كل ورقة جديدة لك تلقائيًا - ثم تظهر ضمن "تمت مشاركتها معي" في Google Drive. تحتوي كل ورقة أيضًا على رابط "فتح" مباشرةً في لوحة المعلومات هذه.',
  '\\nWhy don’t I see my existing sheet in the picker?\\n' => 'لماذا لا أرى الورقة الموجودة في المنتقي؟',
  '\\nIt must be shared with the service account’s email first: open the sheet → Share → paste the email (use the copy button on the connection card) → set Editor → Share. Then click “Browse My Sheets” again.\\n' => 'يجب مشاركته مع البريد الإلكتروني لحساب الخدمة أولاً: افتح الورقة ← مشاركة ← الصق البريد الإلكتروني (استخدم زر النسخ الموجود على بطاقة الاتصال) ← ضبط المحرر ← مشاركة. ثم انقر فوق "استعراض الأوراق" مرة أخرى.',
  '\\nTest result: Google API is not enabled.\\n' => 'نتيجة الاختبار: لم يتم تمكين Google API.',
  '\\nOpen Google Cloud Console for the same project → APIs & Services → Library, and enable BOTH “Google Sheets API” and “Google Drive API”. Wait a minute, then retest.\\n' => 'افتح Google Cloud Console لنفس المشروع → واجهات برمجة التطبيقات والخدمات → المكتبة، وقم بتمكين كل من "Google Sheets API" و"Google Drive API". انتظر دقيقة، ثم أعد الاختبار.',
  '\\nTest result: Access/Permission denied\\n' => 'نتيجة الاختبار: تم رفض الوصول/الإذن',
  '\\nThe service account can authenticate but can’t reach that specific spreadsheet. Re-share the sheet with the service account email as Editor, or create a new sheet instead.\\n' => 'يمكن لحساب الخدمة المصادقة ولكن لا يمكنه الوصول إلى جدول البيانات المحدد هذا. أعد مشاركة الورقة مع البريد الإلكتروني لحساب الخدمة كمحرر، أو قم بإنشاء ورقة جديدة بدلاً من ذلك.',
  '\\nOpenSSL is required.\\n' => 'مطلوب OpenSSL.',
  '\\nThe server is missing the PHP OpenSSL extension used to sign the secure Google request. Ask your host to enable it — no plugin setting can replace it.\\n' => 'يفتقد الخادم ملحق PHP OpenSSL المستخدم لتوقيع طلب Google الآمن. اطلب من مضيفك تمكينه — لا يمكن لأي إعداد إضافي أن يحل محله.',
  '\\nCan I connect more than one service account?\\n' => 'هل يمكنني توصيل أكثر من حساب خدمة واحد؟',
  '\\nYes — drop as many JSON keys as you like in the Connections tab and pick which one each form binding should use.\\n' => 'نعم — قم بإسقاط أي عدد تريده من مفاتيح JSON في علامة التبويب "الاتصالات" واختر المفتاح الذي يجب أن يستخدمه كل ربط نموذج.',
  '[[\'Does the connection expire?\\n' => 'هل تنتهي صلاحية الاتصال؟',
  '\\nNo. The integration runs entirely on the server using your JSON key — there’s no browser session or login to expire.\\n' => 'لا. يتم تشغيل التكامل بالكامل على الخادم باستخدام مفتاح JSON الخاص بك - لا توجد جلسة متصفح أو تسجيل دخول لتنتهي صلاحيته.',
  '\\nCan I choose which field goes to which column?\\n' => 'هل يمكنني اختيار الحقل الذي سيتم الانتقال إليه في أي عمود؟',
  '\\nYes. In the binding wizard’s<strong>Columns & Fields</strong>step, drag rows (or use ▲▼) to set the order, rename each column header, and toggle any field off to skip it. The A/B/C badge shows exactly where each field lands.\\n' => 'نعم. في خطوة<strong>الأعمدة والحقول</strong>الخاصة بمعالج الربط، اسحب الصفوف (أو استخدم ▲▼) لتعيين الترتيب، وأعد تسمية رأس كل عمود، وقم بتبديل أي حقل لتخطيه. تُظهر شارة A/B/C مكان وصول كل حقل بالضبط.',
  '\\nCan I style the sheet automatically?\\n' => 'هل يمكنني تصميم الورقة تلقائياً؟',
  '\\nYes. The<strong>Style & Save</strong>step offers Google-Sheets themes (colored header, frozen top row, alternating row colors). Pick one and it’s applied on the first sync, or click “Apply style now”.\\n' => 'نعم. توفر خطوة<strong>Style & Save</strong>سمات جداول بيانات Google (الرأس الملون، والصف العلوي المجمد، وألوان الصفوف البديلة). اختر واحدًا وسيتم تطبيقه على المزامنة الأولى، أو انقر فوق "تطبيق النمط الآن".',
  '\\nWhat if my form fields change later?\\n' => 'ماذا لو تغيرت حقول النموذج الخاصة بي لاحقاً؟',
  '\\nNew fields are added automatically. In mapped mode, open the Columns step and click “Refresh fields from form” to pull them into the mapping; in “All Form Fields” mode they appear as new columns on the next submission.\\n' => 'تتم إضافة الحقول الجديدة تلقائياً. في الوضع المعين، افتح خطوة الأعمدة وانقر على "تحديث الحقول من النموذج" لسحبها إلى التعيين؛ في وضع "كافة حقول النموذج"، تظهر كأعمدة جديدة في الإرسال التالي.',
  '\\nWhat if the tab doesn’t exist yet?\\n' => 'ماذا لو لم تكن علامة التبويب موجودة بعد؟',
  '\\nIt is created automatically the first time a submission is synced.\\n' => 'يتم إنشاؤه تلقائيًا عند مزامنة الإرسال لأول مرة.',
  '\\nGoogle Sheet Sync Logs\\n' => 'سجلات مزامنة أوراق Google',
  '\\nLatest submissions sent to Google Sheets, success or failure\\n' => 'أحدث الإرسالات التي تم إرسالها إلى جداول بيانات Google، سواء كانت ناجحة أم فاشلة',
  '\\nLog cleared.\\n' => 'تم مسح السجل.',
  '\\nClear Log\\n' => 'مسح السجل',
  '\\nClear all logs?\\n' => 'هل تريد مسح كافة السجلات؟',
  '\\nNo sync activity yet.\\n' => 'لا يوجد أي نشاط مزامنة حتى الآن.',
  'Event' => 'حدث',
  '\\nSpreadsheet\\n' => 'جدول بيانات',
  'Detail' => 'التفاصيل',
  '\\nsynchronized\\n' => 'متزامن',
  '\\nNone (plain)\\n' => 'لا يوجد (عادي)',
  '\\nMinimal\\n' => 'الحد الأدنى',
  '\\nSlate\\n' => 'قائمة',
  '\\nSunset\\n' => 'غروب الشمس',
  '\\nGrape\\n' => 'العنب',
  '\\n%sis currently unavailable.\\n' => '%sغير متوفر حالياً.',
  '\\ndisabled in php.ini:%s\\n' => 'معطل في php.ini: %s',
  '\\nnot provided by PHP or its required extension:%s\\n' => 'غير متوفر بواسطة PHP أو ملحقها المطلوب: %s',
  '\\n%1$scannot run because required PHP functions are unavailable (%2$s). Ask your hosting provider to enable the required PHP extension or remove the listed functions from disabled_functions in php.ini.\\n' => ' لا يمكن تشغيل%1$sلأن وظائف PHP المطلوبة غير متوفرة (%2$s). اطلب من موفر الاستضافة تمكين ملحق PHP المطلوب أو إزالة الوظائف المدرجة من Disable_functions في php.ini.',
  'Panel' => 'لوحة',
  '\\nThis add-on is not included in Flux Forms.\\n' => 'لم يتم تضمين هذه الوظيفة الإضافية في Flux Forms.',
  '\\nError: server (%s) responded with an invalid request. responded code :%s\\n' => 'خطأ: استجاب الخادم (%s) بطلب غير صالح. رمز الرد : %s',
  '\\nYour Easy Form Builder Pro subscription has expired, so this add-on cannot be downloaded.\\n' => 'لقد انتهت صلاحية اشتراكك في Easy Form Builder Pro، لذا لا يمكن تنزيل هذه الوظيفة الإضافية.',
  '\\nSomething went wrong, please refresh the page.\\n' => 'حدث خطأ ما، يرجى تحديث الصفحة.',
  '\\nThe response attachment could not be verified. Please attach the file again.\\n' => 'تعذر التحقق من مرفق الاستجابة. الرجاء إرفاق الملف مرة أخرى.',
  '\\nYou do not have permission to update these settings.", \'en\']]' => 'ليس لديك الإذن بتحديث هذه الإعدادات.',
  '\\nPlease enter a valid admin email address.\\n' => 'الرجاء إدخال عنوان بريد إلكتروني صالح للمسؤول.',
  '\\nYou do not have permission to complete setup.\\n' => 'ليس لديك الإذن بإكمال الإعداد.',
  '\\nInvalid email address\\n' => 'عنوان البريد الإلكتروني غير صالح',
  'Please enter a valid email address.' => 'الرجاء إدخال عنوان بريد إلكتروني صالح.',
  '\\nInvalid sender email\\n' => 'البريد الإلكتروني للمرسل غير صالح',
  '\\nThe sender email address is not valid.\\n' => 'عنوان البريد الإلكتروني للمرسل غير صالح.',
  '\\nEmail tester service error\\n' => 'خطأ في خدمة اختبار البريد الإلكتروني',
  '\\nCould not start email test.\\n' => 'تعذر بدء اختبار البريد الإلكتروني.',
  '\\nInvalid service response\\n' => 'استجابة الخدمة غير صالحة',
  '\\nThe email tester service returned an invalid response.\\n' => 'أرجعت خدمة اختبار البريد الإلكتروني استجابة غير صالحة.',
  '\\nThe message never left your website: WordPress reported an error while trying to send it. This is the one case where the fix really is on the WordPress or hosting side - usually an SMTP plugin, or PHP mail disabled by the host.\\n' => 'لم تغادر الرسالة موقعك على الويب مطلقًا: أبلغ WordPress عن خطأ أثناء محاولة إرسالها. هذه هي الحالة الوحيدة التي يكون فيها الإصلاح على جانب WordPress أو الاستضافة - عادةً ما يكون مكون SMTP الإضافي أو بريد PHP معطلاً بواسطة المضيف.',
  '\\nWordPress could not send the test email. The message never left your website, so nothing was delivered.\\n' => 'تعذر على WordPress إرسال البريد الإلكتروني التجريبي. لم تغادر الرسالة موقعك على الويب مطلقًا، لذلك لم يتم تسليم أي شيء.',
  '[[\'Email test is waiting for delivery confirmation\\n' => 'اختبار البريد الإلكتروني في انتظار تأكيد التسليم',
  '\\nWordPress sent the test email. Flux Forms is waiting for the delivery result before marking email as ready.\\n' => 'أرسل WordPress رسالة البريد الإلكتروني التجريبية. ينتظر Flux Forms نتيجة التسليم قبل وضع علامة على البريد الإلكتروني كجاهز.',
  '\\nWordPress accepted and sent the test email. Waiting for it to arrive.\\n' => 'قبل WordPress وأرسل البريد الإلكتروني التجريبي. في انتظار وصوله.',
  '\\nThe email tester service returned an invalid JSON response.\\n' => 'أرجعت خدمة اختبار البريد الإلكتروني استجابة JSON غير صالحة.',
  '\\nThe email tester service could not start the test.\\n' => 'تعذر على خدمة اختبار البريد الإلكتروني بدء الاختبار.',
  '\\nInvalid test hash\\n' => 'تجزئة الاختبار غير صالحة',
  '\\nThe email test hash is not valid.\\n' => 'تجزئة اختبار البريد الإلكتروني غير صالحة.',
  '\\nYour site could not connect\\n' => 'تعذر على موقعك الاتصال',
  '[[\'No connection could be opened from your site to our mail testing service. This is usually outbound traffic blocked by your server or its network - some hosts block connections to other countries - rather than a problem with the service. Your hosting provider can confirm it.\\n' => 'لا يمكن فتح اتصال من موقعك بخدمة اختبار البريد لدينا. عادةً ما تكون هذه حركة مرور صادرة محظورة بواسطة خادمك أو شبكته - حيث يقوم بعض المضيفين بحظر الاتصالات إلى بلدان أخرى - وليست مشكلة في الخدمة. يمكن لموفر الاستضافة الخاص بك تأكيد ذلك.',
  '\\nService error\\n' => 'خطأ في الخدمة',
  '\\nThe email tester service could not return the result.\\n' => 'تعذر على خدمة اختبار البريد الإلكتروني إرجاع النتيجة.',
  '\\nThe message never left your website. WordPress reported an error while sending, so nothing could be delivered.\\n' => 'لم تغادر الرسالة موقعك على الويب مطلقًا. أبلغ WordPress عن خطأ أثناء الإرسال، لذلك لا يمكن تسليم أي شيء.',
  '\\nThe email was sent, but it never arrived\\n' => 'تم إرسال البريد الإلكتروني، لكنه لم يصل مطلقًا',
  '\\nWordPress sent the message successfully, so your site and this plugin did their part. It was lost, delayed or rejected after leaving WordPress - usually the receiving side treated it as spam, or your host never delivered it from the outbound queue.\\n' => 'أرسل WordPress الرسالة بنجاح، لذلك قام موقعك وهذا المكون الإضافي بدورهما. لقد تم فقدها أو تأخيرها أو رفضها بعد مغادرة WordPress - عادةً ما يعاملها الجانب المتلقي كرسالة غير مرغوب فيها، أو لم يسلمها مضيفك مطلقًا من قائمة انتظار البريد الصادر.',
  '\\nEmail test failed\', \'en\']]' => 'فشل اختبار البريد الإلكتروني',
  '\\nThe email server test could not verify email capability.\\n' => 'تعذر على اختبار خادم البريد الإلكتروني التحقق من إمكانية البريد الإلكتروني.',
  '\\nEmail capability verified\\n' => 'تم التحقق من إمكانية البريد الإلكتروني',
  '\\nServer confirmed ability to send emails.\\n' => 'أكد الخادم قدرته على إرسال رسائل البريد الإلكتروني.',
  '\\nYour emails are being delivered to spam\\n' => 'يتم تسليم رسائل البريد الإلكتروني الخاصة بك إلى البريد العشوائي',
  '\\nWordPress sent the test email, but delivery has not been confirmed yet.\\n' => 'أرسل WordPress رسالة البريد الإلكتروني التجريبية، ولكن لم يتم تأكيد التسليم بعد.',
  '\\nEmail delivery failed:%s\\n' => 'فشل تسليم البريد الإلكتروني: %s',
  '\\nNo file was received. Please choose a file and try again.\\n' => 'لم يتم استلام أي ملف. الرجاء اختيار ملف والمحاولة مرة أخرى.',
  '\\nThe file could not be read. Please try attaching it again.\\n' => 'تعذرت قراءة الملف. الرجاء محاولة إرفاقه مرة أخرى.',
  '\\nEnable the Email Notification Feature\\n' => 'تمكين ميزة الإعلام عبر البريد الإلكتروني',
  '\\nTo receive email notifications from your forms, verify your email server by following these steps:\\n' => 'لتلقي إعلامات البريد الإلكتروني من النماذج الخاصة بك، تحقق من خادم البريد الإلكتروني الخاص بك باتباع الخطوات التالية:',
  '\\nGo to the<a href="%s" style="font-weight:600;">Flux Forms Panel</a>\\n' => 'انتقل إلى لوحة نماذج التدفق<a href="%s" style="font-weight:600;"></a>',
  '\\nClick Settings from the top menu\\n' => 'انقر فوق "إعدادات" من القائمة العلوية',
  '\\nSelect the Email Settings tab\\n' => 'حدد علامة التبويب إعدادات البريد الإلكتروني',
  '\\nClick "Check Email Server" and wait for the test to finish\\n' => 'انقر فوق "التحقق من خادم البريد الإلكتروني" وانتظر حتى ينتهي الاختبار',
  '\\nIf the score is above 70 — enable the "This site can send emails" switch and save\\n' => 'إذا كانت النتيجة أعلى من 70 — قم بتمكين مفتاح التبديل "يمكن لهذا الموقع إرسال رسائل بريد إلكتروني" ثم احفظ',
  '\\nOtherwise, follow the instructions shown in the test results\\n' => 'وإلا، فاتبع الإرشادات الموضحة في نتائج الاختبار',
  '\\n%snotification\\n' => ' إشعار%s',
  '\\nDisabling this feature may affect the proper functionality of Flux Forms. If you plan to use the%sfeature, please ensure it is enabled.\\n' => 'قد يؤثر تعطيل هذه الميزة على الأداء الوظيفي المناسب لـ Flux Forms. إذا كنت تخطط لاستخدام ميزة%s، فيرجى التأكد من تمكينها.',
  '\\nEmail system is working properly.\\n' => 'نظام البريد الإلكتروني يعمل بشكل صحيح.',
  '\\nYour server is able to send emails using the default PHP mail system.\', \'en\']]' => 'خادمك قادر على إرسال رسائل البريد الإلكتروني باستخدام نظام بريد PHP الافتراضي.',
  '\\nEmail system is not available.\\n' => 'نظام البريد الإلكتروني غير متوفر.',
  '\\nThe PHP mail() function is missing. Your server cannot send emails.\\n' => 'وظيفة PHP mail() مفقودة. لا يمكن لخادمك إرسال رسائل البريد الإلكتروني.',
  '\\nEmail sending is blocked by server settings.\\n' => 'تم حظر إرسال البريد الإلكتروني بواسطة إعدادات الخادم.',
  '\\nThe mail() function is disabled in your server PHP configuration (php.ini).\\n' => 'وظيفة mail() معطلة في تكوين PHP للملقم الخاص بك (php.ini).',
  '\\nWordPress mail function not found.\\n' => 'لم يتم العثور على وظيفة بريد WordPress.',
  '\\nThe wp_mail() function is missing or not available. WordPress email features may be broken.\\n' => 'وظيفة wp_mail() مفقودة أو غير متوفرة. قد تكون ميزات البريد الإلكتروني في WordPress معطلة.',
  '\\nNo email handler configured.\\n' => 'لم يتم تكوين معالج البريد الإلكتروني.',
  '\\nYour server has no SMTP host or sendmail path set. Emails may not be delivered.\\n' => 'لا يحتوي الملقم لديك على مضيف SMTP أو مسار إرسال البريد. قد لا يتم تسليم رسائل البريد الإلكتروني.',
  '\\nTest email could not be sent.\\n' => 'تعذر إرسال البريد الإلكتروني التجريبي.',
  '\\nIt seems that your WordPress site could not send a test email. To manually test your email system, go to Flux Forms > Settings > Email Settings tab and click the "Check Email Server" button.\\n' => 'يبدو أن موقع WordPress الخاص بك لم يتمكن من إرسال بريد إلكتروني تجريبي. لاختبار نظام البريد الإلكتروني يدويًا، انتقل إلى Flux Forms > الإعدادات > علامة التبويب إعدادات البريد الإلكتروني وانقر فوق الزر "التحقق من خادم البريد الإلكتروني".',
  '\\nInvalid email address.\\n' => 'عنوان البريد الإلكتروني غير صالح.',
  '\\nPlease enter a valid admin email address before testing email delivery.\\n' => 'الرجاء إدخال عنوان بريد إلكتروني صالح للمسؤول قبل اختبار تسليم البريد الإلكتروني.',
  '\\nInvalid sender email.\\n' => 'البريد الإلكتروني للمرسل غير صالح.',
  '\\nThe sender email address is not valid. Please check your email settings.\\n' => 'عنوان البريد الإلكتروني للمرسل غير صالح. الرجاء التحقق من إعدادات البريد الإلكتروني الخاص بك.',
  '\\nEmail tester service error.\\n' => 'خطأ في خدمة اختبار البريد الإلكتروني.',
  '\\nFlux Forms could not start the email delivery test. Please try again later.\\n' => 'تعذر على Flux Forms بدء اختبار تسليم البريد الإلكتروني. الرجاء المحاولة مرة أخرى لاحقاً.',
  '\\nInvalid email tester response.\', \'en\']]' => 'استجابة اختبار البريد الإلكتروني غير صالحة.',
  '\\nInvalid email test.\\n' => 'اختبار البريد الإلكتروني غير صالح.',
  '\\nThe email test identifier is invalid. Please start a new test.\\n' => 'معرّف اختبار البريد الإلكتروني غير صالح. الرجاء بدء اختبار جديد.',
  '\\nEmail tester connection error.\\n' => 'خطأ في اتصال مختبر البريد الإلكتروني.',
  '\\nFlux Forms could not connect to the email tester service.\\n' => 'تعذر على Flux Forms الاتصال بخدمة اختبار البريد الإلكتروني.',
  '\\nEmail delivery test failed.\\n' => 'فشل اختبار تسليم البريد الإلكتروني.',
  '\\nYour emails are arriving in the spam folder.\\n' => 'تصل رسائل البريد الإلكتروني الخاصة بك إلى مجلد الرسائل غير المرغوب فيها.',
  '\\nThe test message was delivered, but its deliverability score is too low to rely on. Sending through SMTP and adding SPF and DKIM records for your domain is what fixes this.\\n' => 'تم تسليم رسالة الاختبار، ولكن درجة تسليمها منخفضة للغاية بحيث لا يمكن الاعتماد عليها. إن الإرسال عبر SMTP وإضافة سجلات SPF وDKIM للمجال الخاص بك هو ما يحل هذه المشكلة.',
  '\\nEmail delivery test is pending.\\n' => 'اختبار تسليم البريد الإلكتروني معلق.',
  '\\nEmail Issue\\n' => 'مشكلة في البريد الإلكتروني',
  '\\nFlux Forms Email Warning:\\n' => 'تحذير عبر البريد الإلكتروني لنماذج التدفق:',
  '\\nPlan data is missing.\\n' => 'بيانات الخطة مفقودة.',
  '\\nInvalid plan data format.\\n' => 'تنسيق بيانات الخطة غير صالح.',
  '\\nInvalid plan type.\\n' => 'نوع الخطة غير صالح.',
  '\\nPlease confirm this plan downgrade before continuing.\\n' => 'الرجاء تأكيد الرجوع إلى إصدار سابق من هذه الخطة قبل المتابعة.',
  '\\nFree plan activated - no additional features.\\n' => 'تم تفعيل الخطة المجانية - لا توجد ميزات إضافية.',
  '\\nFree Plus plan activated with enhanced features.\\n' => 'تم تفعيل خطة Plus المجانية مع ميزات محسنة.',
  '\\nPro plan activated with existing activation code.\\n' => 'تم تفعيل الخطة الاحترافية باستخدام رمز التنشيط الموجود.',
  '\\nRedirecting to Pro plan purchase page.\\n' => 'إعادة التوجيه إلى صفحة شراء الخطة الاحترافية.',
  '\\nPlan "%s" has been successfully processed.\\n' => 'تمت معالجة الخطة "%s" بنجاح.',
  '\\nAddon Installation Issue\\n' => 'مشكلة في تثبيت الملحق',
  '\\nTechnical Details\\n' => 'التفاصيل الفنية',
  '\\nChecked%s\\n' => 'تم تحديد%s',
  '\\nSystem Ready\\n' => 'النظام جاهز',
  '\\nChecking add-on installation capabilities...\', \'en\']]' => 'يتم التحقق من إمكانيات تثبيت الوظائف الإضافية...',
  '\\nThis check runs once after plugin activation. Please refresh the page in a few moments.\\n' => 'يتم تنفيذ هذا الفحص مرة واحدة بعد تنشيط المكون الإضافي. الرجاء تحديث الصفحة خلال لحظات قليلة.',
  '\\nSome add-ons need a PHP server change\\n' => 'تحتاج بعض الوظائف الإضافية إلى تغيير خادم PHP',
  '\\nFlux Forms has safely paused each affected active add-on, so the rest of the plugin can continue working.\\n' => 'لقد قام Flux Forms بإيقاف كل وظيفة إضافية نشطة متأثرة مؤقتًا بشكل آمن، بحيث يمكن لبقية المكون الإضافي مواصلة العمل.',
  '\\n(currently enabled and paused)\\n' => '(ممكّن ومتوقف مؤقتًا حاليًا)',
  '\\n(not enabled)\\n' => '(غير ممكّن)',
  '\\ndisabled in php.ini:\\n' => 'معطل في php.ini:',
  '[["not provided by PHP or its required extension:\\n' => 'غير متوفر بواسطة PHP أو ملحقها المطلوب:',
  '\\nThis usually means the needed PHP extension is not installed, or the function is listed in disable_functions in php.ini. Please ask your hosting provider to enable it, then refresh this page.\\n' => 'يعني هذا عادة أن ملحق PHP المطلوب غير مثبت، أو أن الوظيفة مدرجة في Disable_functions في php.ini. الرجاء مطالبة موفر الاستضافة بتمكينه، ثم قم بتحديث هذه الصفحة.',
  '\\nIf you are seeing this message, it is likely for one of these reasons: If you have a caching plugin installed, its settings may need to be reviewed.\\n' => 'إذا كنت ترى هذه الرسالة، فمن المحتمل أن يكون ذلك لأحد الأسباب التالية: إذا كان لديك مكون إضافي للتخزين المؤقت مثبتاً، فقد تحتاج إعداداته إلى المراجعة.',
  '\\nPlease also ensure that you have a stable internet connection and try again.\\n' => 'يُرجى أيضًا التأكد من توفر اتصال ثابت بالإنترنت والمحاولة مرة أخرى.',
  'File' => 'ملف',
  '\\nBuilt with%sYT Form%sby%sWordPress form plugin by whitestudio.team%s\\n' => 'تم إنشاؤه باستخدام نموذج%sYT%sبواسطة المكون الإضافي لنموذج WordPress%sبواسطة Whitestudio.team%s',
  '\\nFree WordPress form plugin\\n' => 'مكوّن إضافي مجاني لنماذج WordPress',
  '\\nPowered by%1$sYT Form%2$s.%3$sbest Form plugin for Wordpress%4$s.\\n' => 'مدعوم من%1$sYT Form%2$s.%3$sأفضل مكون إضافي للنموذج في Wordpress%4$s.',
  '\\nFlux Forms WordPress Plugin\\n' => 'مكوّن Flux Forms WordPress الإضافي',
  '\\nThis form requires a payment method. Please add one or change the form type.\\n' => 'يتطلب هذا النموذج طريقة دفع. الرجاء إضافة واحد أو تغيير نوع النموذج.',
  '\\nError Monitor\\n' => 'مراقبة الأخطاء',
  'Theme' => 'الموضوع',
  '\\nWordPress Core\\n' => 'ووردبريس الأساسية',
  'External' => 'خارجي',
  'Unknown' => 'غير معروف',
  'Notice' => 'إشعار',
  '\\nLine\\n' => 'الخط',
  '\\nNo errors detected\\n' => 'لم يتم اكتشاف أية أخطاء',
  '\\nThese errors may interfere with forms built using Flux Forms.\\n' => 'قد تتداخل هذه الأخطاء مع النماذج التي تم إنشاؤها باستخدام Flux Forms.',
  '\\nThis panel is only visible to site administrators.\\n' => 'هذه اللوحة مرئية فقط لمسؤولي الموقع.',
  '\\njQuery Dependency Issue\\n' => 'jمشكلة تبعية الاستعلام',
  '\\njQuery is not properly loaded or available. AJAX and interactive form features may not work correctly.\\n' => 'jلم يتم تحميل الاستعلام أو توفره بشكل صحيح. قد لا تعمل ميزات AJAX والنماذج التفاعلية بشكل صحيح.',
  '\\nWhiteStudio.team\\n' => 'WhiteStudio.team',
  '\\nEFB\\n' => 'EFB',
  '[[\'Flux Forms is a free and powerful WordPress form builder plugin for creating contact forms, payment forms, surveys, registration forms, multi-step forms, file upload forms, electronic signature forms, and audio, video, and screen recording forms, with conditional logic, email notifications, integrations, entry management, and advanced spam protection.\\n' => 'Flux Forms عبارة عن مكون إضافي مجاني وقوي لإنشاء نماذج WordPress لإنشاء نماذج الاتصال ونماذج الدفع والاستطلاعات ونماذج التسجيل والنماذج متعددة الخطوات ونماذج تحميل الملفات ونماذج التوقيع الإلكتروني ونماذج تسجيل الصوت والفيديو والشاشة، مع المنطق الشرطي وإشعارات البريد الإلكتروني وعمليات التكامل وإدارة الإدخال والحماية المتقدمة من البريد العشوائي.',
  '\\nWordPress Form Builder Plugin\\n' => 'المكوّن الإضافي لإنشاء النماذج في WordPress',
  '\\nWordPress 5.0 or later; PHP 7.0 or later\\n' => 'WordPress 5.0 أو الأحدث؛ PHP 7.0 أو الأحدث',
  '\\nFlux Forms Documentation\\n' => 'وثائق نماذج التدفق',
  '\\nDrag-and-Drop WordPress Form Builder\\n' => 'أداة إنشاء نماذج WordPress بالسحب والإفلات',
  '\\nUnlimited Forms and Form Entries\', \'en\']]' => 'نماذج وإدخالات نماذج غير محدودة',
  '\\nResponsive and RTL-Friendly Forms\\n' => 'نماذج سريعة الاستجابة وصديقة لـ RTL',
  '\\nContact and Inquiry Forms\\n' => 'نماذج الاتصال والاستفسار',
  '\\nSupport and Feedback Forms with Message Tracking\\n' => 'نماذج الدعم والتعليقات مع تعقب الرسائل',
  '\\nSurvey and Poll Forms with Visual Results\\n' => 'نماذج الاستطلاع والاستطلاع مع النتائج المرئية',
  '\\nStripe and PayPal Payment Forms\\n' => 'نماذج الدفع Stripe وPayPal',
  '\\nWordPress Login and Registration Forms\\n' => 'نماذج تسجيل الدخول والتسجيل في WordPress',
