  '\\nOrder Forms with Recurring and Subscription Billing\', \'en\']]' => 'نماذج الطلب مع الفواتير المتكررة والاشتراكات',
  '\\nDrag-and-Drop File Upload Fields\\n' => 'حقول تحميل الملفات بالسحب والإفلات',
  '\\nAudio, Video and Screen Recording Fields\\n' => 'حقول الصوت والفيديو وتسجيل الشاشة',
  '\\nElectronic Signature and Location Picker Fields\\n' => 'حقول التوقيع الإلكتروني ومنتقي الموقع',
