  '\\nConditional Email Notifications and Recipient Routing\\n' => 'إشعارات البريد الإلكتروني المشروطة وتوجيه المستلمين',
  '\\nEmail Delivery Status Checking\\n' => 'التحقق من حالة تسليم البريد الإلكتروني',
  '\\nEmail Error Logging\\n' => 'تسجيل أخطاء البريد الإلكتروني',
  '\\nEmail Deliverability Reports with Spam Score, SPF, DKIM and DMARC Checks\\n' => 'تقارير إمكانية تسليم البريد الإلكتروني مع نقاط البريد العشوائي ونظام التعرف على هوية المرسل (SPF) وDKIM وفحوصات DMARC',
  '\\nSMS and Telegram Submission Notifications\', \'en\']]' => 'إشعارات إرسال الرسائل النصية القصيرة والتلغرام',
  '\\nWordPress Form Entry and Message Management Dashboard\\n' => 'إدخال نموذج WordPress ولوحة معلومات إدارة الرسائل',
