  '\\nUnique Submission Confirmation and Tracking Codes\\n' => 'تأكيد الإرسال الفريد وأكواد التتبع',
  '\\nPDF Downloads and CSV Exports\\n' => 'تنزيلات PDF وتصدير ملفات CSV',
  '\\nSurvey and Poll Result Charts\\n' => 'مخططات نتائج الاستطلاع والاستطلاع',
  '\\nGoogle Sheets Form Submission Sync\\n' => 'مزامنة إرسال نموذج جداول بيانات Google',
  '\\nStripe and PayPal Payment Workflows\\n' => 'سير عمل الدفع عبر Stripe وPayPal',
  '\\nExternal API Auto-Populate and Autofill\\n' => 'التعبئة التلقائية والملء التلقائي لواجهة برمجة التطبيقات الخارجية',
  '\\nOffline Form Data Collection\\n' => 'تجميع بيانات النموذج غير المتصل',
  '\\nShield Security silentCAPTCHA Integration\\n' => 'Shield Security تكامل صامت مع CAPTCHA',
  '\\nGutenberg, Elementor, Divi and WPBakery Integration\\n' => 'تكامل Gutenberg وElementor وDivi وWPBakery',
  '\\nForm Submissions Stored in the WordPress Database\\n' => 'عمليات إرسال النماذج المخزنة في قاعدة بيانات WordPress',
  '\\nNo Third-Party Form Submission Servers Required\\n' => 'ليس هناك حاجة إلى خوادم إرسال نماذج تابعة لجهة خارجية',
  '\\nClient-Side and Server-Side Form Validation\\n' => 'التحقق من صحة النماذج من جانب العميل والملقم',
  '\\nGoogle reCAPTCHA v2 Spam Protection\', \'en\']]' => 'Google reCAPTCHA v2 للحماية من البريد العشوائي',
  '\\nCAPTCHA-Free Spam Protection with Honeypot and Signed Single-Use Tokens\\n' => 'الحماية من البريد العشوائي بدون اختبار CAPTCHA باستخدام Honeypot والرموز المميزة ذات الاستخدام الواحد',
  '\\nRate Limiting and Abuse Protection\\n' => 'تحديد المعدل والحماية من إساءة الاستخدام',
