  '\\nWPBakery form plugin\\n' => 'المكوّن الإضافي لنموذج WPBakery',
  '\\nSome plugin files are missing, so the plugin stopped loading to keep your site running. Please reinstall Flux Forms from the Plugins page — your forms, messages, and settings are kept.\\n' => 'بعض ملفات المكونات الإضافية مفقودة، لذا توقف تحميل المكونات الإضافية للحفاظ على تشغيل موقعك. الرجاء إعادة تثبيت Flux Forms من صفحة المكونات الإضافية - يتم الاحتفاظ بالنماذج والرسائل والإعدادات الخاصة بك.',
  '\\nMissing files:\\n' => 'الملفات المفقودة:',
  '\\nSelect a form to display from the dropdown below.\\n' => 'حدد نموذجاً لعرضه من القائمة المنسدلة أدناه.',
  '\\nSelected Form:\\n' => 'النموذج المحدد:',
  '\\nForm will be displayed here on the frontend.\\n' => 'سيتم عرض النموذج هنا على الواجهة الأمامية.',
  '\\nLoading forms...\\n' => 'جاري تحميل النماذج...',
  '[[\'📍 Confirmation Code Finder (Tracking Form)\\n' => '📍 الباحث عن رمز التأكيد (نموذج التتبع)',
  '\\nChoose a form to display. The tracking form allows users to find submissions by confirmation code.\\n' => 'اختر نموذجًا لعرضه. يسمح نموذج التتبع للمستخدمين بالعثور على الإرسالات بواسطة رمز التأكيد.',
  '\\nShow Form Title\\n' => 'إظهار عنوان النموذج',
  '\\nContainer\\n' => 'حاوية',
  'Border' => 'الحدود',
  '\\nBorder Radius\\n' => 'نصف القطر الحدودي',
  '\\nBox Shadow\\n' => 'ظل الصندوق',
  '\\nSelect a form from the widget settings panel.\\n' => 'حدد نموذجًا من لوحة إعدادات عنصر واجهة المستخدم.',
  '\\n👈 Use the sidebar to choose a form\', \'tr\']]' => '👈 استخدم الشريط الجانبي لاختيار النموذج\'، \'tr\']]',
  '\\nSelected Form ID:\\n' => 'معرّف النموذج المحدد:',
  '\\nThe form will appear here on the frontend.\\n' => 'سيظهر النموذج هنا على الواجهة الأمامية.',
  '\\nDisplay an Flux Forms form\\n' => 'عرض نموذج Flux Forms',
  '\\nDisplay the form name as a heading above the form.\\n' => 'عرض اسم النموذج كعنوان أعلى النموذج.',
  '\\nExtra Class Name\\n' => 'اسم الفئة الإضافية',
  '\\nAdd custom CSS classes for styling.\', \'en\']]' => 'أضف فئات CSS مخصصة للتصميم.',
  '\\nDesign\\n' => 'التصميم',
  '\\nCSS\\n' => 'CSS',
  '\\nSelect a form from the element settings.\\n' => 'حدد نموذجاً من إعدادات العنصر.',
  '\\n✏️ Click to edit and choose a form\\n' => '✏️ انقر لتعديل النموذج واختياره',
  '[[\'Add forms created with Flux Forms\\n' => 'إضافة نماذج تم إنشاؤها باستخدام Flux Forms',
  '\\nDisplay Flux Forms forms on your page\\n' => 'عرض نماذج Flux Forms على صفحتك',
  '\\nChoose the form you want to display\\n' => 'اختر النموذج الذي تريد عرضه',
  '\\nPlease select a form from element settings\\n' => 'الرجاء تحديد نموذج من إعدادات العناصر',
  '\\nForm:%s(ID:%s)\\n' => 'النموذج: %s(المعرف: %s)',
  '\\n📍 Confirmation Code Finder (Tracking)\', \'en\']]' => '📍 الباحث عن رمز التأكيد (التتبع)',
  '\\n🎨 Flux Forms\\n' => '🎨 نماذج التدفق',
  '\\nAdd Flux Forms forms to your page\\n' => 'أضف نماذج Flux Forms إلى صفحتك',
  '\\nSelect Form:\\n' => 'حدد النموذج:',
  '\\nCustom Title (optional):\', \'en\']]' => 'عنوان مخصص (اختياري):',
  '\\nShortcode:\\n' => 'الرمز القصير:',
  '\\nRun the email check\\n' => 'قم بتشغيل فحص البريد الإلكتروني',
  '\\nThe last delivery check scored%sout of 100. Your messages do leave the site, but most mailboxes will file them as spam, so the people filling in your forms will not see them. Sending through an SMTP service, and adding SPF and DKIM records for your domain, is what fixes this.\\n' => 'سجل فحص التسليم الأخير%sمن أصل 100. تغادر رسائلك الموقع، ولكن معظم صناديق البريد ستسجلها كرسائل غير مرغوب فيها، وبالتالي لن يراها الأشخاص الذين يملؤون النماذج الخاصة بك. إن الإرسال عبر خدمة SMTP وإضافة سجلات SPF وDKIM للمجال الخاص بك هو ما يحل هذه المشكلة.',
  '\\nThe last delivery check found that your messages do leave the site, but mailboxes file them as spam. Sending through an SMTP service, and adding SPF and DKIM records for your domain, is what fixes this.\\n' => 'أظهر فحص التسليم الأخير أن رسائلك تغادر الموقع، لكن صناديق البريد تسجلها كرسائل غير مرغوب فيها. إن الإرسال عبر خدمة SMTP وإضافة سجلات SPF وDKIM للمجال الخاص بك هو ما يحل هذه المشكلة.',
  '\\nYour form emails are going to the spam folder\\n' => 'ستنتقل رسائل البريد الإلكتروني النموذجية الخاصة بك إلى مجلد الرسائل غير المرغوب فيها',
  '[[\'Your form emails are sent, but they are not arriving\\n' => 'تم إرسال رسائل البريد الإلكتروني للنموذج الخاص بك، لكنها لا تصل',
  '\\nWordPress sent the last test message successfully, so your site and this plugin did their part - it was lost, delayed or rejected after leaving WordPress. Usually the receiving mailbox treated it as spam, or your host never delivered it from the outbound queue. Sending through an SMTP service, with SPF and DKIM records for your domain, is what fixes this.\\n' => 'أرسل WordPress آخر رسالة اختبارية بنجاح، لذلك قام موقعك وهذا المكون الإضافي بدورهما - فقد تم فقده أو تأخيره أو رفضه بعد مغادرة WordPress. عادةً ما يعاملها صندوق البريد المتلقي على أنها بريد عشوائي، أو أن المضيف الخاص بك لم يسلمها مطلقًا من قائمة انتظار البريد الصادر. إن الإرسال عبر خدمة SMTP، مع سجلات SPF وDKIM للمجال الخاص بك، هو ما يحل هذه المشكلة.',
  '\\nWordPress cannot send your form emails\\n' => 'لا يمكن لـ WordPress إرسال رسائل البريد الإلكتروني للنموذج الخاص بك',
  '\\nThe last check could not even hand a message to your mail server: WordPress reported an error while sending, so nothing left the site. An SMTP plugin, or asking your host whether PHP mail is disabled, is where to start.\\n' => 'لم يتمكن الفحص الأخير حتى من تسليم رسالة إلى خادم البريد الخاص بك: أبلغ WordPress عن خطأ أثناء الإرسال، لذلك لم يبق أي شيء في الموقع. من أين تبدأ، مكون SMTP الإضافي، أو سؤال مضيفك عما إذا كان بريد PHP معطلاً.',
  '\\nYour form emails are not being delivered\', \'en\']]' => 'لا يتم تسليم رسائل البريد الإلكتروني النموذجية الخاصة بك',
  '\\nThe last delivery check could not get a message through, so nothing your forms send is reaching anybody. A hosting server usually sends mail without a trusted signature; sending through an SMTP service is the standard fix.\\n' => 'تعذر على فحص التسليم الأخير استلام الرسالة، لذا لا يصل أي شيء ترسله النماذج إلى أي شخص. عادةً ما يرسل خادم الاستضافة البريد بدون توقيع موثوق به؛ الإرسال عبر خدمة SMTP هو الحل القياسي.',
  '\\nOnce Weekly (Flux Forms)\\n' => 'مرة واحدة أسبوعيًا (نماذج التدفق)',
  '\\nThe weekly email delivery test completed successfully.\\n' => 'تم إكمال اختبار تسليم البريد الإلكتروني الأسبوعي بنجاح.',
  '\\nThe weekly email delivery test found an email delivery problem.\\n' => 'لقد اكتشف اختبار تسليم البريد الإلكتروني الأسبوعي وجود مشكلة في تسليم البريد الإلكتروني.',
  '\\nThe main WordPress administrator email address is not valid.\\n' => 'عنوان البريد الإلكتروني الرئيسي لمسؤول WordPress غير صالح.',
  '\\nCould not start the email delivery test.\\n' => 'تعذر بدء اختبار تسليم البريد الإلكتروني.',
  '\\nWordPress sent the automated test email and is waiting for it to arrive.\\n' => 'أرسل WordPress رسالة بريد إلكتروني تجريبية تلقائية وهو في انتظار وصولها.',
  '\\nWordPress could not send the automated test email. The message never left this website.\\n' => 'تعذر على WordPress إرسال البريد الإلكتروني التجريبي الآلي. لم تغادر الرسالة موقع الويب هذا مطلقًا.',
  '\\nThe email delivery test timed out before confirmation was received.\\n' => 'انتهت مهلة اختبار تسليم البريد الإلكتروني قبل استلام التأكيد.',
  '\\nWeekly Flux Forms report for%s\\n' => 'تقرير Flux Forms الأسبوعي لـ%s',
  '\\nHere is your weekly snapshot for%s.\\n' => 'هذه هي اللقطة الأسبوعية لـ%s.',
  '[[\'Report generated%s\\n' => 'تم إنشاء التقرير%s',
  '\\nDetailed analysis\\n' => 'تحليل تفصيلي',
  'This week' => 'هذا الاسبوع',
  '\\nEmails failed\\n' => 'فشلت رسائل البريد الإلكتروني',
  '\\nYou can turn these reports off in Flux Forms settings.\\n' => 'يمكنك إيقاف تشغيل هذه التقارير في إعدادات Flux Forms.',
  '\\nThe test email was delivered, but its deliverability score is only%1$sout of 100 (below%2$s), so the emails your forms send are very likely to be rejected or filtered as spam.\\n' => 'تم تسليم البريد الإلكتروني التجريبي، ولكن درجة التسليم الخاصة به هي%1$sفقط من أصل 100 (أقل من%2$s)، لذلك من المحتمل جدًا أن يتم رفض رسائل البريد الإلكتروني التي ترسلها النماذج أو تصفيتها كرسائل غير مرغوب فيها.',
  '\\nRun the email check so you can be sure the messages your forms send are actually reaching people. The check sends a real message through the new WhiteStudio delivery service and reports back what arrived.\\n' => 'قم بتشغيل فحص البريد الإلكتروني حتى تتأكد من أن الرسائل التي ترسلها نماذجك تصل بالفعل إلى الأشخاص. يرسل الشيك رسالة حقيقية من خلال خدمة تسليم WhiteStudio الجديدة ويبلغ بما وصل.',
  '\\nRead the guide to sending email through SMTP\\n' => 'اقرأ دليل إرسال البريد الإلكتروني عبر SMTP',
  '\\nDelivery has not been scored yet\\n' => 'لم يتم تسجيل التسليم بعد',
  '\\nWordPress sent your email, but it never arrived\\n' => 'أرسل WordPress بريدك الإلكتروني، لكنه لم يصل مطلقًا',
  '\\nWordPress could not send your email\', \'en\']]' => 'تعذر على WordPress إرسال بريدك الإلكتروني',
  '\\nWe could not confirm your emails are being delivered\\n' => 'لم نتمكن من تأكيد تسليم رسائل البريد الإلكتروني الخاصة بك',
  '\\nout of 100\\n' => 'من 100',
  '\\nYour email delivery is healthy\\n' => 'تسليم بريدك الإلكتروني سليم',
  '\\nYour emails are likely going to spam\\n' => 'من المحتمل أن تصل رسائل البريد الإلكتروني الخاصة بك إلى رسائل غير مرغوب فيها',
  '\\nYour emails are not reaching anybody\\n' => 'رسائل البريد الإلكتروني الخاصة بك لا تصل إلى أي شخص',
  '\\ngrade%s\\n' => 'درجة%s',
  '\\nWhat you should do\\n' => 'ما يجب عليك فعله',
  '\\nA hosting server usually sends mail without a trusted signature, which is what pushes your form emails into the spam folder or stops them arriving at all. The standard fix is to send through an SMTP service.\\n' => 'يرسل خادم الاستضافة عادةً بريدًا بدون توقيع موثوق به، وهو ما يدفع رسائل البريد الإلكتروني النموذجية الخاصة بك إلى مجلد البريد العشوائي أو يمنعها من الوصول على الإطلاق. الإصلاح القياسي هو الإرسال عبر خدمة SMTP.',
  '\\nInstall an SMTP plugin and enter the details of your email service.\\n' => 'قم بتثبيت مكون SMTP الإضافي وأدخل تفاصيل خدمة البريد الإلكتروني لديك.',
  '\\nAdd the SPF and DKIM records to your domain settings.\\n' => 'أضف سجلات SPF وDKIM إلى إعدادات المجال لديك.',
  '\\nRun the email check again until the score is above%s.\\n' => 'قم بتشغيل فحص البريد الإلكتروني مرة أخرى حتى تصبح النتيجة أعلى من%s.',
  '\\nYou have%1$sforms:%2$sactive and%3$sinactive.\\n' => 'لديك نماذج%1$s: %2$sنشط و%3$sغير نشط.',
  '\\nRenew Flux Forms Pro\\n' => 'تجديد Flux Forms Pro',
  '\\nGet more from Flux Forms Pro\\n' => 'احصل على المزيد من Flux Forms Pro',
  '\\nRenew your subscription to restore all Pro features and add-ons.\\n' => 'قم بتجديد اشتراكك لاستعادة كافة ميزات Pro والوظائف الإضافية.',
  '\\nUnlock premium add-ons, unlimited features and priority support for your forms.\\n' => 'احصل على الوظائف الإضافية المميزة والميزات غير المحدودة والدعم ذي الأولوية للنماذج الخاصة بك.',
  '\\nRenew Pro\\n' => 'تجديد النسخة الاحترافية',
  '\\nEmail delivery is working\\n' => 'تسليم البريد الإلكتروني يعمل',
  '\\nThe automated Flux Forms email delivery test completed successfully.\\n' => 'اكتمل اختبار تسليم البريد الإلكتروني التلقائي لـ Flux Forms بنجاح.',
  '[[\'You can attach up to%1$dfile here. Please wait about%2$dminutes before trying again.\', \'en\']]' . chr(0) . '[[\'You can attach up to%1$dfiles here. Please wait about%2$dminutes before trying again.\', \'en\']]' => 'يمكنك إرفاق ما يصل إلى ملفات%1$dهنا. يرجى الانتظار حوالي%2$dدقيقة قبل المحاولة مرة أخرى.' . chr(0) . 'يمكنك إرفاق ما يصل إلى ملف%1$dهنا. يرجى الانتظار حوالي%2$dدقيقة قبل المحاولة مرة أخرى.' . chr(0) . 'يمكنك إرفاق ما يصل إلى ملفات%1$dهنا. يرجى الانتظار حوالي%2$dدقيقة قبل المحاولة مرة أخرى.' . chr(0) . 'يمكنك إرفاق ما يصل إلى ملفات%1$dهنا. يرجى الانتظار حوالي%2$dدقيقة قبل المحاولة مرة أخرى.' . chr(0) . 'يمكنك إرفاق ما يصل إلى ملفات%1$dهنا. يرجى الانتظار حوالي%2$dدقيقة قبل المحاولة مرة أخرى.' . chr(0) . 'يمكنك إرفاق ما يصل إلى ملفات%1$dهنا. يرجى الانتظار حوالي%2$dدقيقة قبل المحاولة مرة أخرى.',
  '\\nThis file is too large. The maximum size for this field is%s.\\n' => 'هذا الملف كبير جدًا. الحد الأقصى لحجم هذا الحقل هو%s.',
  '\\nThis file type is not accepted here. Please attach one of the file types listed on the field.\\n' => 'نوع الملف هذا غير مقبول هنا. الرجاء إرفاق أحد أنواع الملفات المدرجة في الحقل.',
  '\\nThis file appears to be empty. Please choose a different file.\\n' => 'يبدو أن هذا الملف فارغ. الرجاء اختيار ملف مختلف.',
  '\\nThe uploaded file could not be verified. Please attach it again.\\n' => 'تعذر التحقق من الملف الذي تم تحميله. الرجاء إرفاقه مرة أخرى.',
  '\\nX-WP-Nonce header is missing\\n' => 'رأس X-WP-Nonce مفقود',
  '\\nYour form session has expired. Please reload the page.\\n' => 'لقد انتهت صلاحية جلسة النموذج الخاصة بك. الرجاء إعادة تحميل الصفحة.',
  '\\nForm ID:\\n' => 'معرّف النموذج:',
  '\\nThe form will be displayed on the frontend.\\n' => 'سيتم عرض النموذج على الواجهة الأمامية.',
  '\\nThis link uses an older format. For improved security, new email notifications include updated links.\\n' => 'يستخدم هذا الارتباط تنسيقًا قديمًا. لتحسين الأمان، تتضمن إعلامات البريد الإلكتروني الجديدة ارتباطات محدثة.',
  '\\nIt seems that you are the admin of this form. Please log in and try again.\\n' => 'يبدو أنك المسؤول عن هذا النموذج. الرجاء تسجيل الدخول والمحاولة مرة أخرى.',
  '\\nFlux Forms couldn\\\'t locate the form settings. Please check your settings or contact support for assistance.\\n' => 'تعذر على Flux Forms تحديد إعدادات النموذج. الرجاء التحقق من إعداداتك أو الاتصال بالدعم للحصول على المساعدة.',
  '\\nY/m/d \\\\a\\\\t g:ia\\n' => 'Y/m/d \\a\\t g:ia',
  '\\nToo many attempts. Please wait a few minutes and try again.\\n' => 'محاولات كثيرة جدًا. الرجاء الانتظار بضع دقائق ثم حاول مرة أخرى.',
  '[[\'The recording upload could not be verified. Please record it again and retry.\\n' => 'تعذر التحقق من تحميل التسجيل. الرجاء تسجيله مرة أخرى ثم إعادة المحاولة.',
  '\\nThis recording format is not supported. Please record it again.\\n' => 'تنسيق التسجيل هذا غير معتمد. الرجاء تسجيله مرة أخرى.',
  '\\nThe server could not verify the recording format. Please contact the site administrator.\\n' => 'تعذر على الملقم التحقق من تنسيق التسجيل. الرجاء الاتصال بمسؤول الموقع.',
  '\\nThe recording format could not be verified. Please record it again.\\n' => 'تعذر التحقق من تنسيق التسجيل. الرجاء تسجيله مرة أخرى.',
  '\\nThe server could not verify the recording duration. Please record it again and try uploading.\\n' => 'تعذر على الملقم التحقق من مدة التسجيل. الرجاء تسجيله مرة أخرى ومحاولة التحميل.',
  '\\nThe server could not store the recording. Please try again or contact the site administrator.\\n' => 'تعذر على الملقم تخزين التسجيل. الرجاء المحاولة مرة أخرى أو الاتصال بمسؤول الموقع.',
  '\\nThe recording request could not be verified. Please retry.\', \'en\']]' => 'تعذر التحقق من طلب التسجيل. يرجى إعادة المحاولة.',
  '\\nThe upload request could not be verified. Please try again.\\n' => 'تعذر التحقق من طلب التحميل. الرجاء المحاولة مرة أخرى.',
  '\\nThe upload field could not be verified. Please refresh the form and try again.\\n' => 'تعذر التحقق من حقل التحميل. الرجاء تحديث النموذج والمحاولة مرة أخرى.',
  '\\nThe response box could not be verified. Reopen the conversation and try again.\\n' => 'تعذر التحقق من مربع الاستجابة. أعد فتح المحادثة وحاول مرة أخرى.',
  '\\nThe response attachment could not be secured. Please try again.\\n' => 'تعذر تأمين مرفق الاستجابة. الرجاء المحاولة مرة أخرى.',
  '\\nNot allowed to respond to this message.\\n' => 'غير مسموح له بالرد على هذه الرسالة.',
  'error' => 'خطأ',
  '[[\'Payment Intent ID is missing\\n' => 'معرف وجهة الدفع مفقود',
  '\\npersiaPayment\\n' => 'الدفع الفارسي',
  '\\nThe Email Address Is Not Valid\\n' => 'عنوان البريد الإلكتروني غير صالح',
  '\\nThe Username Must Contain Only Letters, Numbers And Lowercase letters\', \'en\']]' => 'يجب أن يحتوي اسم المستخدم على أحرف وأرقام وأحرف صغيرة فقط',
  '\\nThe Username Must Contain At Least 3 Characters.\\n' => 'يجب أن يحتوي اسم المستخدم على 3 أحرف على الأقل.',
  '\\nThe Password Must Contain At Least 8 Characters!\\n' => 'يجب أن تحتوي كلمة المرور على 8 أحرف على الأقل!',
  '\\nThe Password Must Contain At Least 1 Number!\\n' => 'يجب أن تحتوي كلمة المرور على رقم واحد على الأقل!',
  '\\nThe Password Must Contain At Least 1 Capital Letter!\\n' => 'يجب أن تحتوي كلمة المرور على حرف واحد كبير على الأقل!',
  '\\nThe Password Must Contain At Least 1 Lowercase Letter!\\n' => 'يجب أن تحتوي كلمة المرور على حرف واحد صغير على الأقل!',
  '\\nAudio recording\\n' => 'تسجيل صوتي',
  '\\nVideo recording\\n' => 'تسجيل فيديو',
  '\\nScreen recording\\n' => 'تسجيل الشاشة',
  'You are not allowed to do this.' => 'لا يسمح لك أن تفعل هذا.',
  '\\nForm Preview\\n' => 'معاينة النموذج',
  '\\nCreate New Password\\n' => 'إنشاء كلمة مرور جديدة',
  '\\nCreate a secure password for your account\\n' => 'قم بإنشاء كلمة مرور آمنة لحسابك',
  '\\nNew Password\\n' => 'كلمة المرور الجديدة',
  '\\nEnter your new password\\n' => 'أدخل كلمة المرور الجديدة',
  '\\nSet Password\\n' => 'تعيين كلمة المرور',
  '\\nError! Please try again later.\\n' => 'خطأ! الرجاء المحاولة مرة أخرى لاحقاً.',
  '\\nPassword has been changed successfully!\\n' => 'تم تغيير كلمة المرور بنجاح!',
  '\\nInvalid payment selection. Please review your choices and try again. If the problem persists, contact the site administrator.\\n' => 'اختيار الدفع غير صالح. يرجى مراجعة اختياراتك والمحاولة مرة أخرى. إذا استمرت المشكلة، اتصل بمسؤول الموقع.',
  '\\nIf your emails are not being delivered, try using an SMTP plugin. For more information,%1$sclick here%2$sor contact our%3$ssupport team%4$s.\\n' => 'إذا لم يتم تسليم رسائل البريد الإلكتروني الخاصة بك، فحاول استخدام مكون SMTP الإضافي. لمزيد من المعلومات، %1$sانقر هنا%2$sأو اتصل بفريق دعم%3$s%4$s.',
  '\\nView Messages\\n' => 'عرض الرسائل',
  '\\nHello!\\n' => 'مرحبا!',
  '\\nNew Message\\n' => 'رسالة جديدة',
  '\\nNew message received\\n' => 'تم استلام رسالة جديدة',
  '\\nWe received your message\\n' => 'لقد تلقينا رسالتك',
  '\\nThis email was sent automatically. Please do not reply.\\n' => 'تم إرسال هذه الرسالة الإلكترونية تلقائيًا. الرجاء عدم الرد.',
  '\\nBuilt with%1$sYT Form%2$sby%3$sWhiteStudio.team%4$s\\n' => 'تم إنشاؤه باستخدام نموذج%1$sYT%2$sبواسطة%3$sWhiteStudio.team%4$s',
  '\\nWeekly Flux Forms report\\n' => 'تقرير نماذج التدفق الأسبوعي',
  '\\nPro features are paused\\n' => 'الميزات الاحترافية متوقفة مؤقتًا',
  '\\nCongratulations! Email System Working\\n' => 'تهانينا! نظام البريد الإلكتروني يعمل',
  '\\nYour server has successfully sent this test email. The email delivery system is properly configured and functioning.\\n' => 'لقد نجح الخادم الخاص بك في إرسال رسالة البريد الإلكتروني التجريبية هذه. تم تكوين نظام تسليم البريد الإلكتروني ويعمل بشكل صحيح.',
  '\\nEmail Delivery Tips\\n' => 'نصائح حول تسليم البريد الإلكتروني',
  '\\nForm submitted successfully without tracking.\\n' => 'تم إرسال النموذج بنجاح دون تعقب.',
  '\\nYour message has been received and recorded successfully.\\n' => 'تم استلام رسالتك وتسجيلها بنجاح.',
  '\\nReset Password\\n' => 'إعادة تعيين كلمة المرور',
  '\\nOr copy and paste this link:\\n' => 'أو انسخ هذا الارتباط والصقه:',
  '\\nIf you did not request this, you can safely ignore it.\\n' => 'إذا لم تطلب ذلك، فيمكنك تجاهله بأمان.',
  '\\nHi\\n' => 'مرحبا',
  '\\nYou have requested to reset your password.\\n' => 'لقد طلبت إعادة تعيين كلمة المرور الخاصة بك.',
  '\\nClick the button below to set a new password. This link will be valid for 24 hours.\\n' => 'انقر فوق الزر أدناه لتعيين كلمة مرور جديدة. سيكون هذا الارتباط صالحًا لمدة 24 ساعة.',
  '\\nVerify Email\\n' => 'التحقق من البريد الإلكتروني',
  '\\nYour account has been successfully created!\\n' => 'تم إنشاء حسابك بنجاح!',
  '\\nPlease verify your email address by clicking the button below. This activation link will be valid for 24 hours.\\n' => 'الرجاء التحقق من عنوان بريدك الإلكتروني بالنقر فوق الزر أدناه. سيكون ارتباط التنشيط هذا صالحًا لمدة 24 ساعة.',
  '\\nA new user has registered on your website.\\n' => 'تم تسجيل مستخدم جديد في موقعك على الويب.',
  '\\nThe user has been sent a verification email to confirm their account.\\n' => 'تم إرسال رسالة تحقق إلى المستخدم لتأكيد حسابه.',
  '\\nThis is an alert message regarding a SID validation error. This issue may have occurred due to a plugin conflict or an unauthorized attempt to access the website.\\n' => 'هذه رسالة تنبيه بخصوص خطأ في التحقق من صحة SID. ربما حدثت هذه المشكلة بسبب تعارض في البرنامج الإضافي أو محاولة غير مصرح بها للوصول إلى موقع الويب.',
  '\\nIf you receive this email multiple times, it could indicate a recurring issue.\\n' => 'إذا تلقيت هذا البريد الإلكتروني عدة مرات، فقد يشير ذلك إلى مشكلة متكررة.',
  '\\nPlease contact our support team for assistance.\\n' => 'الرجاء الاتصال بفريق الدعم للحصول على المساعدة.',
  '\\nOne or more of the plugins listed below—typically related to caching or security—might be triggering this issue. For troubleshooting, temporarily deactivate them and test your site.\\n' => 'ربما يكون واحد أو أكثر من المكونات الإضافية المدرجة أدناه — المرتبطة عادةً بالتخزين المؤقت أو الأمان — هو الذي يسبب هذه المشكلة. لاستكشاف الأخطاء وإصلاحها، قم بإلغاء تنشيطها مؤقتًا واختبر موقعك.',
  '\\nSID Validation Error\\n' => 'خطأ في التحقق من صحة SID',
  '\\nPlease select a form to display.\\n' => 'الرجاء تحديد نموذج لعرضه.',
  '[[\'Drag-and-drop form builder: multi-step forms, Stripe payments, conditional logic, dashboard, automations and Flux Certificates integration. Fork based on Easy Form Builder (WhiteStudio, GPL).\', \'tr\']]' => 'أداة إنشاء نماذج السحب والإفلات: نماذج متعددة الخطوات، والمدفوعات الشريطية، والمنطق الشرطي، ولوحة المعلومات، والأتمتة، وتكامل شهادات التدفق. الشوكة مبنية على Easy Form Builder (WhiteStudio, GPL).',
  'Loading forms…' => 'جارٍ تحميل النماذج...',
  'Choose a form to display on your page.' => 'اختر نموذجًا لعرضه على صفحتك.',
  'Quick Actions' => 'إجراءات سريعة',
  'Change Form' => 'تغيير النموذج',
  'Select a form to display on your page' => 'حدد نموذجًا لعرضه على صفحتك',
  'Search forms…' => 'نماذج البحث...',
  'No forms found matching your search.' => 'لم يتم العثور على نماذج مطابقة لبحثك.',
  'No forms available. Create a form first.' => 'لا توجد نماذج متاحة. قم بإنشاء نموذج أولاً.',
  'Change' => 'التغيير',
  '\\nKeys are set;%dform uses reCAPTCHA.%dforms use reCAPTCHA.\\n' . chr(0) . '\\nKeys are set;%dform uses reCAPTCHA.%dforms use reCAPTCHA.\\n' => 'تم ضبط المفاتيح; يستخدم نموذج %dreCAPTCHA. تستخدم نماذج %dreCAPTCHA.' . chr(0) . 'تم ضبط المفاتيح; يستخدم نموذج %dreCAPTCHA. تستخدم نماذج %dreCAPTCHA.' . chr(0) . 'تم ضبط المفاتيح; يستخدم نموذج %dreCAPTCHA. تستخدم نماذج %dreCAPTCHA.' . chr(0) . 'تم ضبط المفاتيح; يستخدم نموذج %dreCAPTCHA. تستخدم نماذج %dreCAPTCHA.' . chr(0) . 'تم ضبط المفاتيح; يستخدم نموذج %dreCAPTCHA. تستخدم نماذج %dreCAPTCHA.' . chr(0) . 'تم ضبط المفاتيح; يستخدم نموذج %dreCAPTCHA. تستخدم نماذج %dreCAPTCHA.',
  'Show or hide fields and steps based on the answers to other fields. Rules run from the lowest priority number to the highest; when two rules change the same field, the later one wins. A field targeted by a "Show field" action stays hidden until its rule matches. Hidden fields are skipped by validation and their values are discarded on the server.' => 'إظهار الحقول والخطوات أو إخفاؤها بناءً على إجابات الحقول الأخرى. يتم تشغيل القواعد من رقم الأولوية الأدنى إلى الأعلى؛ عندما تغير قاعدتان نفس الحقل، تفوز القاعدة الأحدث. يظل الحقل المستهدف بإجراء "إظهار الحقل" مخفيًا حتى تتطابق قاعدته. يتم تخطي الحقول المخفية عن طريق التحقق من الصحة ويتم تجاهل قيمها على الخادم.',
  'No rules yet. Click "Add rule" to create your first IF / THEN rule.' => 'لا توجد قواعد حتى الآن. انقر فوق "إضافة قاعدة" لإنشاء قاعدة IF / THEN الأولى.',
  'Add some fields to the form first; rules read and change form fields.' => 'أضف بعض الحقول إلى النموذج أولاً؛ قواعد القراءة وتغيير حقول النموذج.',
  'Add rule' => 'أضف القاعدة',
  'Rule' => 'القاعدة',
  'Rule name' => 'اسم القاعدة',
  'Priority' => 'الأولوية',
  'All of these are true (AND)' => 'كل هذا صحيح (و)',
  'Any of these is true (OR)' => 'أي من هذه صحيح (أو)',
  'Add group' => 'أضف مجموعة',
  'Add action' => 'أضف الإجراء',
  'Select a field' => 'حدد حقلاً',
