  'Make field optional' => 'اجعل الحقل اختياريًا',
  'Enable field' => 'تمكين الحقل',
  'Disable field' => 'تعطيل الحقل',
  'Block submission' => 'منع التقديم',
  'Conditional logic rules updated. Save the form to keep them.' => 'تم تحديث قواعد المنطق الشرطي. احفظ النموذج للاحتفاظ بها.',
  'Incomplete conditions or actions were removed.' => 'تمت إزالة الشروط أو الإجراءات غير المكتملة.',
  'A rule hides or shows a field it also reads. That field can never become visible again once hidden.' => 'تقوم القاعدة بإخفاء الحقل الذي تقرأه أيضًا أو إظهاره. لا يمكن أبدًا أن يصبح هذا الحقل مرئيًا مرة أخرى بمجرد إخفائه.',
  '(deleted field)' => '(حقل محذوف)',
  'This form does not accept Stripe payments.' => 'هذا النموذج لا يقبل مدفوعات Stripe.',
  'This form does not accept online payments.' => 'هذا النموذج لا يقبل الدفع عبر الإنترنت.',
  '[[\'The currency of this form is not supported.\\n' => 'عملة هذا النموذج غير مدعومة.',
  'The payment amount is too large.' => 'مبلغ الدفع كبير جدًا.',
  'Your payment has not been confirmed by Stripe yet. Please wait a moment and try again. If the problem persists, contact the site administrator.' => 'لم يتم تأكيد دفعتك بواسطة Stripe بعد. الرجاء الانتظار لحظة وحاول مرة أخرى. إذا استمرت المشكلة، اتصل بمسؤول الموقع.',
  'Stripe Payments' => 'المدفوعات الشريطية',
  'The publishable and secret API keys are set on the plugin Settings page, Payment tab.' => 'يتم تعيين مفاتيح واجهة برمجة التطبيقات (API) القابلة للنشر والسرية في صفحة إعدادات البرنامج المساعد، وعلامة التبويب "الدفع".',
  'Date (UTC)' => 'التاريخ (التوقيت العالمي الموحد)',
  'Stripe ID' => 'معرف الشريط',
  '\\nThe Stripe secret key is not configured.\\n' => 'لم يتم تكوين المفتاح السري Stripe.',
  '\\nCould not connect to Stripe:%s\', \'en\']]' => 'تعذر الاتصال بـ Stripe: %s',
