  'Flux Forms is an intuitive and user-friendly tool that lets you create custom, multi-step forms in just minutes, without requiring any coding skills.' => 'Flux Forms هي أداة بديهية وسهلة الاستخدام تتيح لك إنشاء نماذج مخصصة متعددة الخطوات في دقائق معدودة فقط، دون الحاجة إلى أي مهارات برمجية.',
  'You do not have to be a coding expert to use Flux Forms. Simply drag and drop the fields to create customized multistep forms easily. Plus, you can connect each submission to a unique request using the Confirmation Code feature.' => 'ليس من الضروري أن تكون خبيرًا في البرمجة لاستخدام Flux Forms. ما عليك سوى سحب الحقول وإفلاتها لإنشاء نماذج مخصصة متعددة الخطوات بسهولة. بالإضافة إلى ذلك، يمكنك ربط كل إرسال بطلب فريد باستخدام ميزة رمز التأكيد.',
