  'Build professional WordPress forms in minutes. Choose how you\'d like to get started.' => 'قم بإنشاء نماذج WordPress احترافية في دقائق. اختر الطريقة التي تريدها للبدء.',
  'Switch to Free Plus?' => 'هل تريد التبديل إلى Free Plus؟',
  'Your Pro activation code will be removed from this site. Pro add-ons will be unavailable until you upgrade again. Your forms, entries and settings will not be deleted.' => 'ستتم إزالة رمز التفعيل الاحترافي الخاص بك من هذا الموقع. لن تكون الوظائف الإضافية الاحترافية متاحة حتى تقوم بالترقية مرة أخرى. لن يتم حذف النماذج والإدخالات والإعدادات الخاصة بك.',
  'Switch to Free?' => 'هل تريد التبديل إلى الإصدار المجاني؟',
  'Advanced features and advanced fields used in your forms will be disabled. Your forms, entries and settings will not be deleted, and will be available again if you upgrade.' => 'سيتم تعطيل الميزات المتقدمة والحقول المتقدمة المستخدمة في النماذج الخاصة بك. لن يتم حذف النماذج والإدخالات والإعدادات الخاصة بك، وستكون متاحة مرة أخرى إذا قمت بالترقية.',
  'Your Pro activation code will be removed from this site. Advanced features, Pro fields and add-ons will be unavailable until you upgrade again. Your forms, entries and settings will not be deleted.' => 'ستتم إزالة رمز التفعيل الاحترافي الخاص بك من هذا الموقع. لن تكون الميزات المتقدمة والحقول الاحترافية والوظائف الإضافية متاحة حتى تقوم بالترقية مرة أخرى. لن يتم حذف النماذج والإدخالات والإعدادات الخاصة بك.',
