  'Set up form notifications' => 'إعداد إعلامات النموذج',
  'Check whether your server can send emails, so you know you will receive form notifications.' => 'تحقق مما إذا كان بإمكان الخادم الخاص بك إرسال رسائل بريد إلكتروني، حتى تعرف أنك ستتلقى إشعارات النماذج.',
  'Form notification email' => 'البريد الإلكتروني لإشعار النموذج',
  'This is saved in General Settings and can be changed later.' => 'يتم حفظ هذا في "الإعدادات العامة" ويمكن تغييره لاحقًا.',
  'Your default settings' => 'إعداداتك الافتراضية',
  'Notifications stay off until delivery is verified' => 'تظل الإشعارات متوقفة حتى يتم التحقق من التسليم',
  'Your forms and submissions are ready to use' => 'النماذج والإرسالات الخاصة بك جاهزة للاستخدام',
  'Save and test email delivery' => 'حفظ واختبار تسليم البريد الإلكتروني"، \'ar\']]',
  'Checking email delivery…' => 'جارٍ التحقق من تسليم البريد الإلكتروني...',
  'A test email was sent. Waiting for delivery confirmation…' => 'تم إرسال بريد إلكتروني تجريبي. في انتظار تأكيد التسليم...',
  'Email delivery is ready. Form notifications can be sent.' => 'تسليم البريد الإلكتروني جاهز. يمكن إرسال إعلامات النموذج.',
  'Your test email was sent, but delivery is not confirmed yet. Check the inbox or spam folder for the address below; you can finish setup and try again later from General Settings.' => 'تم إرسال بريدك الإلكتروني التجريبي، ولكن لم يتم تأكيد التسليم بعد. تحقق من البريد الوارد أو مجلد البريد العشوائي بحثًا عن العنوان أدناه؛ يمكنك إنهاء الإعداد والمحاولة مرة أخرى لاحقاً من "الإعدادات العامة".',
  'We could not verify delivery. Your email address was saved; please check your mail configuration in General Settings.' => 'لم نتمكن من التحقق من التسليم. تم حفظ عنوان بريدك الإلكتروني؛ الرجاء التحقق من تكوين البريد الخاص بك في "الإعدادات العامة".',
  'Your test email was delivered, but its deliverability score is only %1$s out of 100 (below %2$s). The emails your forms send will most likely be filtered as spam. Set up SMTP and run the check again.' => 'تم تسليم البريد الإلكتروني الاختباري الخاص بك، ولكن درجة التسليم الخاصة به هي %1$s فقط من 100 (أقل من %2$s). من المرجح أن تتم تصفية رسائل البريد الإلكتروني التي ترسلها النماذج الخاصة بك كرسائل غير مرغوب فيها. قم بإعداد SMTP ثم قم بتشغيل التحقق مرة أخرى.',
