  'Create a payment form to collect online payments.' => 'قم بإنشاء نموذج دفع لجمع الدفعات عبر الإنترنت.',
  'Submit' => 'إرسال',
  'Purchase Order' => 'أمر الشراء',
  'It is not possible to include reCAPTCHA on payment forms.' => 'لا يمكن تضمين reCAPTCHA في نماذج الدفع.',
  'This site can send emails' => 'يمكن لهذا الموقع إرسال رسائل بريد إلكتروني',
  'Weekly email health and form activity report' => 'تقرير أسبوعي عن سلامة البريد الإلكتروني ونشاط النموذج',
  'Adds your form activity totals &ndash; forms, views and submissions &ndash; to the weekly email your site sends the main administrator. These totals are read on your own site and are never sent to WhiteStudio.' => 'يضيف إجمالي نشاط النموذج - النماذج وطرق العرض والإرسالات - إلى البريد الإلكتروني الأسبوعي الذي يرسله موقعك إلى المسؤول الرئيسي. تتم قراءة هذه الإجماليات على موقعك الخاص ولا يتم إرسالها مطلقًا إلى WhiteStudio.',
  'No automated email check has run yet.' => 'لم يتم تشغيل أي فحص تلقائي للبريد الإلكتروني حتى الآن.',
  'Collect email delivery statistics' => 'تجميع إحصائيات تسليم البريد الإلكتروني',
  'Counts how many emails were sent or failed, shows them in the dashboard widget, and adds the email delivery status section to the weekly email. Once a week your site runs a delivery test and reports the result. Only Pro users can turn this off.' => 'يحسب عدد رسائل البريد الإلكتروني التي تم إرسالها أو الفاشلة، ويعرضها في أداة لوحة المعلومات، ويضيف قسم حالة تسليم البريد الإلكتروني إلى البريد الإلكتروني الأسبوعي. يجري موقعك اختبار التسليم مرة واحدة في الأسبوع ويبلغ عن النتيجة. يمكن لمستخدمي Pro فقط إيقاف تشغيل هذا.',
  'Interval' => 'الفاصل الزمني',
  'Next Billing Date' => 'تاريخ الفاتورة التالي',
  'Yearly' => 'سنوياً',
  'How to activate the Pro version of Flux Forms' => 'كيفية تنشيط الإصدار الاحترافي من Flux Forms',
  'Uploaded File' => 'الملف الذي تم تحميله',
  'Your internet connection has been lost, but do not worry, we have saved the information you entered on this form. Once you are reconnected to the internet, you can easily send your information by clicking the submit button.' => 'لقد انقطع اتصالك بالإنترنت، لكن لا تقلق، فقد قمنا بحفظ المعلومات التي أدخلتها في هذا النموذج. بمجرد إعادة اتصالك بالإنترنت، يمكنك إرسال معلوماتك بسهولة عن طريق النقر فوق الزر "إرسال".',
  'Please ensure that you have a stable internet connection and try again.' => 'يُرجى التأكد من توفر اتصال ثابت بالإنترنت والمحاولة مرة أخرى.',
  'There was a problem uploading the file and the form was not submitted. Please check that your internet connection is stable and try again.' => 'حدثت مشكلة أثناء تحميل الملف ولم يتم إرسال النموذج. الرجاء التأكد من أن اتصالك بالإنترنت مستقر ثم حاول مرة أخرى.',
  'You are experiencing issues with jQuery. Please contact the administrator for assistance. (Error code: JQ-500)' => 'أنت تواجه مشكلات مع jQuery. الرجاء الاتصال بالمسؤول للحصول على المساعدة. (رمز الخطأ: JQ-500)',
  'Your session has expired. Please refresh the page and try again.' => 'لقد انتهت صلاحية جلسة العمل الخاصة بك. الرجاء تحديث الصفحة والمحاولة مرة أخرى.',
  'Basic' => 'أساسي',
  'Sign-In|Up' => 'تسجيل الدخول|التسجيل',
  'Advance' => 'تقدم',
  'Thank you Page' => 'صفحة شكرا',
  'Redirect page' => 'إعادة توجيه الصفحة',
  'Please wait, you will be redirected shortly.' => 'الرجاء الانتظار، سيتم إعادة توجيهك قريباً.',
  'Persia payment' => 'الدفع في بلاد فارس',
  'Unlock Pro Features Today' => 'افتح الميزات الاحترافية اليوم',
  'Upgrade to Pro for just %1$s%2$s%3$s/year and get access to powerful features, including advanced form fields, payment integrations, conditional logic, multi-step forms, file uploads, Security & Spam Protection, and priority support.%4$sView Pro Features%5$s' => 'قم بالترقية إلى Pro مقابل %1$s%2$s %3$s/سنة فقط واحصل على إمكانية الوصول إلى الميزات القوية، بما في ذلك حقول النماذج المتقدمة وعمليات تكامل الدفع والمنطق الشرطي والنماذج متعددة الخطوات وتحميل الملفات والأمان والحماية من البريد العشوائي والدعم ذي الأولوية. ميزات عرض %4$sPro%5$s',
  'Add-on' => 'إضافة',
  'Add-ons' => 'الإضافات',
  'Stripe Payment Add-on' => 'وظيفة إضافية للدفع الشريطي',
  'The Stripe add-on for Flux Forms enables you to integrate your WordPress site with Stripe for payment processing, donations, and online orders.' => 'تمكنك الوظيفة الإضافية Stripe لـ Flux Forms من دمج موقع WordPress الخاص بك مع Stripe لمعالجة الدفع والتبرعات والطلبات عبر الإنترنت.',
  'Offline Forms Add-on' => 'الوظيفة الإضافية للنماذج دون اتصال',
  'The Offline Forms add-on for Flux Forms allows users to save their progress when filling out forms in offline situations.' => 'تسمح الوظيفة الإضافية "النماذج دون اتصال" لـ Flux Forms للمستخدمين بحفظ تقدمهم عند ملء النماذج في المواقف دون اتصال.',
  'Please update Flux Forms before trying again.' => 'الرجاء تحديث Flux Forms قبل المحاولة مرة أخرى.',
  'Activation of offline form mode.' => 'تنشيط وضع النموذج دون اتصال.',
  'Before activating this option, install' => 'قبل تنشيط هذا الخيار، قم بتثبيت',
  'To create a payment form to collect online payments, you must first install a payment add-on such as the Stripe Add-on.' => 'لإنشاء نموذج دفع لجمع الدفعات عبر الإنترنت، يجب عليك أولاً تثبيت وظيفة إضافية للدفع مثل الوظيفة الإضافية Stripe.',
  'All formats' => 'كافة التنسيقات',
  'EFB SMS Add-on' => 'وظيفة EFB الإضافية للرسائل النصية القصيرة',
  'Enable SMS functionality in your forms with the EFB SMS add-on, allowing you to validate mobile numbers and send confirmation codes via SMS, as well as receive notifications through SMS service.' => 'قم بتمكين وظيفة الرسائل القصيرة SMS في النماذج الخاصة بك باستخدام الوظيفة الإضافية لـ EFB SMS، مما يسمح لك بالتحقق من صحة أرقام الهاتف المحمول وإرسال رموز التأكيد عبر الرسائل القصيرة، بالإضافة إلى تلقي الإشعارات من خلال خدمة الرسائل القصيرة.',
  'Advanced confirmation code Add-on' => 'الوظيفة الإضافية لرمز التأكيد المتقدم',
  'Send a confirmation code via email or SMS to users and/or admins, allowing them to quickly access new responses.' => 'أرسل رمز التأكيد عبر البريد الإلكتروني أو الرسائل النصية القصيرة إلى المستخدمين و/أو المسؤولين، مما يسمح لهم بالوصول بسرعة إلى الردود الجديدة.',
  'Box Checklist' => 'قائمة اختيار المربع',
  'Radio Checklist' => 'قائمة اختيار الراديو',
  'This is a warning for WPBakery users. For more information, please click here.' => 'هذا تحذير لمستخدمي WPBakery. لمزيد من المعلومات، الرجاء النقر هنا.',
  'Are you sure you want to close replies to this message?' => 'هل تريد بالتأكيد إغلاق الردود على هذه الرسالة؟',
  'Are you sure you want to open the responses to this message?' => 'هل أنت متأكد أنك تريد فتح الردود على هذه الرسالة؟',
  'The response has been closed by Admin.' => 'تم إغلاق الاستجابة من قبل المسؤول.',
  'The response has been opened by Admin.' => 'تم فتح الرد بواسطة المسؤول.',
