  'Hijri Date' => 'التاريخ الهجري',
  'Install the add-on' => 'قم بتثبيت الوظيفة الإضافية',
  'Please go to the Add-ons Page of Flux Forms plugin and install the Jalili date addons' => 'الرجاء الانتقال إلى صفحة الوظائف الإضافية للمكون الإضافي Flux Forms وتثبيت إضافات تاريخ Jalili',
  'Please go to the Add-ons Page of Flux Forms plugin and install the Hijri date addons' => 'الرجاء الانتقال إلى صفحة الإضافات الخاصة بالمكون الإضافي Flux Forms وتثبيت الإضافات الخاصة بالتاريخ الهجري',
  'date & time' => 'التاريخ والوقت',
  'Enable file upload in the response box' => 'تمكين تحميل الملف في مربع الاستجابة',
  'Enable Google reCAPTCHA in the response box' => 'قم بتمكين Google reCAPTCHA في مربع الاستجابة',
  'Enable download button in the response box' => 'تمكين زر التنزيل في مربع الاستجابة',
  'Display the IP addresses of users in the response box.' => 'عرض عناوين IP الخاصة بالمستخدمين في مربع الاستجابة.',
  'Persia Payment Add-on' => 'الوظيفة الإضافية للدفع في بلاد فارس',
  'The Persia payment add-on for Flux Forms enables you to connect your website with Persia payment to process payments, donations, and online orders.' => 'تمكنك الوظيفة الإضافية للدفع في بلاد فارس لـ Flux Forms من ربط موقع الويب الخاص بك مع خدمة الدفع في بلاد فارس لمعالجة الدفعات والتبرعات والطلبات عبر الإنترنت.',
  'Jalali Date Add-on' => 'إضافة تاريخ جلالي',
  'The Jalali Date add-on allows you to add a Jalali date field to your forms and create any type of form that includes this Shamsi date field.' => 'تسمح لك الوظيفة الإضافية لتاريخ جلالي بإضافة حقل تاريخ جلالي إلى النماذج الخاصة بك وإنشاء أي نوع من النماذج يتضمن حقل تاريخ شمسي هذا.',
  'Hijri Date Add-on' => 'إضافة التاريخ الهجري',
  'The Hijri Date add-on allows you to add a Hijri date field to your forms and create any type of form that includes this field.' => 'تسمح لك الوظيفة الإضافية للتاريخ الهجري بإضافة حقل التاريخ الهجري إلى النماذج الخاصة بك وإنشاء أي نوع من النماذج يتضمن هذا الحقل.',
  'SMS service Add-on' => 'الوظيفة الإضافية لخدمة الرسائل القصيرة',
  'The SMS service add-on enables you to receive notification SMS messages when you or your customers receive new messages or responses.' => 'تمكنك الوظيفة الإضافية لخدمة SMS من تلقي إشعارات عبر رسائل SMS عندما تتلقى أنت أو عملاؤك رسائل أو استجابات جديدة.',
  'Please install either the Hijri or Jalali date add-on. You cannot install both add-ons simultaneously.' => 'يرجى تثبيت إضافة التاريخ الهجري أو الجلالي. لا يمكنك تثبيت كلتا الوظيفتين الإضافيتين في وقت واحد.',
  'Response box' => 'مربع الاستجابة',
  'Regions Drop-Down' => 'القائمة المنسدلة للمناطق',
  'You are seeing this message because your required add-ons are being installed. Please wait a few minutes and then visit this page again. If it has been more than five minutes and nothing has happened, please contact the support team of Flux Forms at Whitestudio.team.' => 'تظهر لك هذه الرسالة لأنه يتم الآن تثبيت الوظائف الإضافية المطلوبة. يرجى الانتظار بضع دقائق ثم قم بزيارة هذه الصفحة مرة أخرى. إذا مر أكثر من خمس دقائق ولم يحدث شيء، فيرجى الاتصال بفريق دعم Flux Forms على Whitestudio.team.',
  'The cell phone number is incorrect' => 'رقم الهاتف الخليوي غير صحيح',
  'Invalid country code' => 'رمز البلد غير صالح',
  'The cell phone number is too short' => 'رقم الهاتف الخلوي قصير جدًا',
  'The cell phone number is too long' => 'رقم الهاتف الخلوي طويل جدًا',
  'Please select the number of countries to display within an acceptable range.' => 'الرجاء تحديد عدد البلدان التي سيتم عرضها ضمن نطاق مقبول.',
  'Disabled Field' => 'حقل معطل',
  'Hidden Field' => 'حقل مخفي',
  'Select a country to display a list of states/provinces.' => 'حدد بلدًا لعرض قائمة الولايات/المقاطعات.',
  'Select a state/province to display a list of cities.' => 'حدد ولاية/مقاطعة لعرض قائمة المدن.',
  'SMS Service Add-on' => 'الوظيفة الإضافية لخدمة الرسائل القصيرة',
  'This field is currently unavailable. Please contact the site administrator.' => 'هذا الحقل غير متوفر حاليًا. الرجاء الاتصال بمسؤول الموقع.',
  'Would you like to customize the form using the colors of the active template?' => 'هل ترغب في تخصيص النموذج باستخدام ألوان القالب النشط؟',
  'Flux Forms has utilized the colors of the active template. Please choose a color for each option below to customize the form you are creating based on the colors of your template. By selecting a color for each option below, the color of all form fields associated with that feature will change accordingly.' => 'لقد استخدمت Flux Forms ألوان القالب النشط. يرجى اختيار لون لكل خيار أدناه لتخصيص النموذج الذي تقوم بإنشائه بناءً على ألوان القالب الخاص بك. من خلال تحديد لون لكل خيار أدناه، سيتم تغيير لون جميع حقول النموذج المرتبطة بهذه الميزة وفقًا لذلك.',
  'Buttons text colors' => 'ألوان نص الأزرار',
