  'Default selected' => 'تم التحديد الافتراضي',
  'Show attributes' => 'إظهار السمات',
  'Hide attributes' => 'إخفاء السمات',
  'The ID length should be at least 3 characters long.' => 'يجب أن يكون طول المعرف 3 أحرف على الأقل.',
  'The ID value must be unique, as it is already being used in this field. Please try a new, unique value.' => 'يجب أن تكون قيمة المعرف فريدة، حيث إنها مستخدمة بالفعل في هذا الحقل. الرجاء تجربة قيمة جديدة وفريدة.',
  'Image picker' => 'منتقي الصور',
