  'New Booking Form' => 'نموذج حجز جديد',
  'Conditional Logic Add-on' => 'وظيفة المنطق الشرطي الإضافية',
  'Conditional logic Add-on' => 'وظيفة المنطق الشرطي الإضافية',
  'The Conditional Logic Add-on enables dynamic and interactive forms based on specific user inputs or conditional rules. It allows for highly personalized forms tailored to meet users’ unique needs.' => 'تعمل الوظيفة الإضافية للمنطق الشرطي على تمكين النماذج الديناميكية والتفاعلية المستندة إلى مدخلات مستخدم محددة أو قواعد شرطية. فهو يسمح بنماذج مخصصة للغاية ومصممة لتلبية الاحتياجات الفريدة للمستخدمين.',
  'The Conditional Logic module failed to load. Please refresh the page; if the problem continues, deactivate and reactivate the Conditional Logic add-on.' => 'فشل تحميل وحدة المنطق الشرطي. يرجى تحديث الصفحة؛ إذا استمرت المشكلة، قم بإلغاء تنشيط الوظيفة الإضافية للمنطق الشرطي وإعادة تنشيطها.',
