  'The entered data does not match the form type. If you are an admin, please review the form type.' => 'البيانات المدخلة غير متطابقة مع نوع النموذج. إذا كنت مسؤولاً، يرجى مراجعة نوع النموذج.',
  'Error: Please ensure there is only one form per page.' => 'خطأ: الرجاء التأكد من وجود نموذج واحد فقط في كل صفحة.',
  'Your activation code has been verified. Enjoy all Pro features of Flux Forms.' => 'تم التحقق من رمز التفعيل الخاص بك. استمتع بجميع الميزات الاحترافية لـ Flux Forms.',
  'The confirmation code for this message is %s. By clicking the button below, you will be able to track messages and view received responses. If needed, you can also send a new reply.' => 'رمز التأكيد لهذه الرسالة هو %s. بالنقر على الزر أدناه، ستتمكن من تتبع الرسائل وعرض الردود المستلمة. إذا لزم الأمر، يمكنك أيضًا إرسال رد جديد.',
  'To explore the full functionality and settings of Flux Forms, including email configurations, form creation options, and other features, simply delve into our %1$s documentation %2$s .' => 'لاستكشاف الوظائف والإعدادات الكاملة لـ Flux Forms، بما في ذلك تكوينات البريد الإلكتروني وخيارات إنشاء النماذج والميزات الأخرى، ما عليك سوى التعمق في وثائق %1$s الخاصة بنا %2$s.',
  'Responses & Confirmation' => 'الردود والتأكيد',
  'Test emails may land in your spam folder. If emails are not delivered, this is usually related to your hosting or email server configuration.server settings %1$sLearn how to fix email delivery issues%2$s or %3$scontact Flux Forms support%4$s.' => 'قد تصل رسائل البريد الإلكتروني الاختبارية إلى مجلد الرسائل غير المرغوب فيها. إذا لم يتم تسليم رسائل البريد الإلكتروني، فهذا عادةً ما يرتبط بتكوين خادم الاستضافة أو البريد الإلكتروني. إعدادات الخادم %1$sتعرف على كيفية إصلاح مشكلات تسليم البريد الإلكتروني%2$s أو %3$sاتصل بدعم Flux Forms%4$s.',
  'From Address' => 'من العنوان',
  'Make sure this email address matches the one configured in your SMTP settings to prevent email delivery issues.' => 'تأكد من تطابق عنوان البريد الإلكتروني هذا مع العنوان الذي تم تكوينه في إعدادات SMTP لديك لمنع حدوث مشكلات في تسليم البريد الإلكتروني.',
  'To preview the form, you need to save the built form and try again.' => 'لمعاينة النموذج، تحتاج إلى حفظ النموذج الذي تم إنشاؤه والمحاولة مرة أخرى.',
  'No selected rows found.' => 'لم يتم العثور على صفوف محددة.',
  'Mark as Read' => 'وضع علامة "مقروءة"',
