  'After changing the Development Mode (Sandbox) option, save the settings, then deactivate and reactivate Flux Forms plugin from the Plugins page for the changes to take effect.' => 'بعد تغيير خيار وضع التطوير (Sandbox)، احفظ الإعدادات، ثم قم بإلغاء تنشيط المكون الإضافي Flux Forms وإعادة تنشيطه من صفحة المكونات الإضافية حتى تدخل التغييرات حيز التنفيذ.',
