  'Telegram Notification Add-on' => 'الوظيفة الإضافية لإشعارات Telegram',
  'The Telegram notification add-on lets you get notifications on your Telegram app whenever you receive new messages or responses' => 'تتيح لك الوظيفة الإضافية لإشعارات Telegram الحصول على إشعارات على تطبيق Telegram الخاص بك عندما تتلقى رسائل أو ردودًا جديدة',
  'Enter a location name' => 'أدخل اسم الموقع',
