  'The connection was interrupted, but don\'t worry—your edits are safely stored in your browser. Refresh the page to continue working.' => 'لقد انقطع الاتصال، لكن لا تقلق، فقد تم تخزين تعديلاتك بأمان في متصفحك. قم بتحديث الصفحة لمتابعة العمل.',
  'There is an auto-saved version of the form available. Do you want to restore it?' => 'توجد نسخة محفوظة تلقائيًا من النموذج متوفرة. هل تريد استعادتها؟',
  'SMS notification could not be sent. Check if the SMS plugin is installed and configured properly.' => 'تعذر إرسال إشعار SMS. تحقق من تثبيت المكون الإضافي لـ SMS وتكوينه بشكل صحيح.',
  'Your request was completed successfully. %1$s %2$s' => 'تم إكمال طلبك بنجاح.%1$s %2$s',
  'PayPal' => 'باي بال',
  'To use %1$s features in your forms, you need to get your %2$s keys.' => 'لاستخدام ميزات %1$s في النماذج الخاصة بك، يجب الحصول على مفاتيح %2$s الخاصة بك.',
  'Go to the add-ons page in the Flux Forms plugin, install the %s add-on, and try again.' => 'انتقل إلى صفحة الوظائف الإضافية في المكون الإضافي Flux Forms، ثم قم بتثبيت الوظيفة الإضافية %s، ثم حاول مرة أخرى.',
  'To create a payment form to collect online payments, install a payment add-on such as the %s Add-on first.' => 'لإنشاء نموذج دفع لجمع الدفعات عبر الإنترنت، قم بتثبيت وظيفة الدفع الإضافية مثل الوظيفة الإضافية %s أولاً.',
  'Thank' => 'شكرًا',
  'The %s plugin may interfere with Flux Forms form functionality. If you encounter any issues with the forms, disable caching for the Flux Forms plugin in the %s settings.' => 'قد يتداخل المكون الإضافي %s مع وظيفة نموذج Flux Forms. إذا واجهت أي مشاكل مع النماذج، قم بتعطيل التخزين المؤقت للمكون الإضافي Flux Forms في إعدادات %s.',
  'Remind me later' => 'ذكّرني لاحقًا',
  'Got it, don\'t show again' => 'فهمت، لا تعرضه مرة أخرى',
  'The value of the %1$s field does not match the pattern and must be at least %2$s characters.' => 'قيمة الحقل %1$s لا تتطابق مع النمط ويجب أن تتكون من أحرف %2$s على الأقل.',
  'The value of the %1$s field does not match the pattern and must be at most %2$s characters.' => 'قيمة الحقل %1$s لا تتطابق مع النمط ويجب أن تتكون من أحرف %2$s على الأكثر.',
  'Please enter valid value for the %s field.' => 'الرجاء إدخال قيمة صالحة للحقل %s.',
  '%s list' => ' قائمة %s',
  'The uploaded file exceeds the allowable limit of %s MB.' => 'الملف الذي تم تحميله يتجاوز الحد المسموح به وهو %s ميغابايت.',
  'The uploaded file is below the required minimum size of %s MB.' => 'الملف الذي تم تحميله أقل من الحد الأدنى المطلوب للحجم وهو %s ميغابايت.',
  'Review the entered values in the %s tab. This message appeared because an error was detected.' => 'راجع القيم المدخلة في علامة التبويب %s. ظهرت هذه الرسالة بسبب اكتشاف خطأ.',
  'Are you sure you want to duplicate the "%s" ?' => 'هل أنت متأكد أنك تريد تكرار "%s" ؟',
  'We are sorry, the booking time for the %s option has expired. Please choose from the other available options.' => 'عذرًا، لقد انتهت مدة حجز خيار %s. الرجاء الاختيار من بين الخيارات الأخرى المتوفرة.',
  'We are sorry, the %s option is currently at full capacity. Please choose from the other available options.' => 'عذرًا، خيار %s يعمل حاليًا بكامل طاقته. الرجاء الاختيار من بين الخيارات الأخرى المتوفرة.',
