  'Security Plugin Detected' => 'تم اكتشاف مكون إضافي للأمان',
  'The following security plugin may block form submissions with 403 errors. It may block the REST API, remove the X-WP-Nonce header, or apply firewall rules to form requests.' => 'قد يقوم مكون الأمان الإضافي التالي بحظر عمليات إرسال النماذج التي تحتوي على أخطاء 403. قد يقوم بحظر REST API، أو إزالة رأس X-WP-Nonce، أو تطبيق قواعد جدار الحماية على طلبات النماذج.',
  'Read more about security plugin compatibility' => 'اقرأ المزيد حول توافق المكونات الإضافية للأمان',
  'Auto-Populate Add-on' => 'ملء الوظيفة الإضافية تلقائيًا',
  'The Auto-Populate add-on enables you to automatically populate form fields from datasets, previously submitted forms, or external APIs.' => 'تمكّنك وظيفة الملء التلقائي الإضافية من تعبئة حقول النماذج تلقائيًا من مجموعات البيانات، أو النماذج التي تم إرسالها مسبقًا، أو واجهات برمجة التطبيقات الخارجية.',
  'Form Security & Spam Protection' => 'أمان النماذج والحماية من البريد العشوائي',
  'Behavior-based anti-spam and API abuse protection with rate limits and a stop-loss for paid notifications such as SMS, Telegram, email and webhooks.' => 'حماية من إساءة استخدام واجهة برمجة التطبيقات (API) ومكافحة البريد العشوائي المستندة إلى السلوك مع حدود للمعدلات وإيقاف الخسارة للإشعارات المدفوعة مثل الرسائل النصية القصيرة (SMS) وTelegram والبريد الإلكتروني وخطافات الويب.',
  'Google Sheet Add-on' => 'الوظيفة الإضافية لجداول بيانات Google',
  'Automatically send form submissions to your Google Sheets in real time. Connect a service account, map fields to columns, and keep a live, styled spreadsheet of every response — no webhook or browser login required.' => 'أرسل عمليات إرسال النماذج تلقائيًا إلى جداول بيانات Google في الوقت الفعلي. قم بتوصيل حساب خدمة، وقم بتعيين الحقول إلى الأعمدة، واحتفظ بجدول بيانات مباشر ومُصمم لكل استجابة - لا يلزم وجود خطاف ويب أو تسجيل دخول للمتصفح.',
