  'Email Server Status' => 'حالة خادم البريد الإلكتروني',
  'The test email never arrived' => 'لم يصل البريد الإلكتروني التجريبي مطلقًا',
  'Your WordPress site cannot send emails reliably. This is a very common hosting issue — the default PHP mail function is often blocked or ends up in spam. Installing an SMTP plugin routes your emails through a verified mail service and fixes this in minutes.' => 'لا يمكن لموقع WordPress الخاص بك إرسال رسائل البريد الإلكتروني بشكل موثوق. هذه مشكلة استضافة شائعة جدًا - غالبًا ما يتم حظر وظيفة بريد PHP الافتراضية أو ينتهي بها الأمر في البريد العشوائي. يؤدي تثبيت مكون SMTP الإضافي إلى توجيه رسائل البريد الإلكتروني الخاصة بك عبر خدمة بريد تم التحقق منها وإصلاح هذه المشكلة خلال دقائق.',
  'WordPress sent the email - it just never arrived' => 'أرسل WordPress البريد الإلكتروني - لكنه لم يصل مطلقًا',
  'Your site handed the message to your mail server successfully, so WordPress and this plugin did their part. It was lost, delayed or rejected afterwards - most often the receiving mailbox filed it as spam, or your host never delivered it from the outbound queue. Sending through an SMTP service, with SPF and DKIM records for your domain, is what fixes this.' => 'لقد قام موقعك بتسليم الرسالة إلى خادم البريد الخاص بك بنجاح، لذلك قام WordPress وهذا المكون الإضافي بدورهما. تم فقدها أو تأخيرها أو رفضها بعد ذلك - غالبًا ما يرسلها صندوق البريد المتلقي كرسالة غير مرغوب فيها، أو لم يسلمها مضيفك مطلقًا من قائمة انتظار البريد الصادر. إن الإرسال عبر خدمة SMTP، مع سجلات SPF وDKIM للمجال الخاص بك، هو ما يحل هذه المشكلة.',
  'WordPress could not send the email' => 'تعذر على WordPress إرسال البريد الإلكتروني',
  'The message never left your website: WordPress returned an error while sending it. Install and configure an SMTP plugin, or ask your host whether PHP mail is disabled.' => 'لم تغادر الرسالة موقعك على الويب مطلقًا: عرض WordPress خطأً أثناء إرسالها. قم بتثبيت مكون SMTP الإضافي وتكوينه، أو اسأل مضيفك عما إذا كان بريد PHP معطلاً.',
  'Your emails arrive, but will most likely land in spam' => 'تصل رسائل البريد الإلكتروني الخاصة بك، ولكن من المرجح أن تصل إلى رسائل غير مرغوب فيها',
  'Delivery itself works - the test message reached us. What is missing is trust: sending through an SMTP service and adding SPF and DKIM records for your domain is what moves your emails from the spam folder to the inbox.' => 'التسليم نفسه يعمل - وصلت رسالة الاختبار إلينا. ما ينقصنا هو الثقة: الإرسال عبر خدمة SMTP وإضافة سجلات SPF وDKIM للمجال الخاص بك هو ما ينقل رسائل البريد الإلكتروني الخاصة بك من مجلد البريد العشوائي إلى البريد الوارد.',
  'The test email was delivered with a deliverability score of %1$s out of 100. Under %2$s, most mailboxes file messages in the spam folder, so the people filling in your forms may never see them.' => 'تم تسليم البريد الإلكتروني التجريبي بدرجة تسليم تبلغ %1$s من أصل 100. ضمن %2$s، تقوم معظم صناديق البريد بحفظ الرسائل في مجلد البريد العشوائي، لذلك قد لا يتمكن الأشخاص الذين يملؤون النماذج الخاصة بك من رؤيتها أبدًا.',
  'Step-by-step SMTP setup guide' => 'دليل إعداد SMTP خطوة بخطوة',
  'Your email server is working. A detailed HTML report has been sent to %s.' => 'خادم البريد الإلكتروني الخاص بك يعمل. تم إرسال تقرير HTML مفصل إلى %s.',
  'your admin email address' => 'عنوان البريد الإلكتروني للمشرف',
  'Spam Score Report on the Way!' => 'تقرير نتيجة البريد العشوائي في الطريق!',
  'A complete email health report — including your spam score, deliverability details, and recommendations — will be sent to %s within the next few minutes.' => 'سيتم إرسال تقرير كامل عن سلامة البريد الإلكتروني - بما في ذلك نقاط البريد العشوائي وتفاصيل إمكانية التسليم والتوصيات - إلى %s خلال الدقائق القليلة القادمة.',
  'Email notifications may not be delivered' => 'قد لا يتم تسليم إعلامات البريد الإلكتروني',
  'This form\'s email notification feature is enabled, but email delivery has not been verified and the latest spam score is %s/100. The form was saved, but admin notification emails may not reach you until SMTP/email delivery is fixed.' => 'تم تمكين ميزة الإعلام عبر البريد الإلكتروني لهذا النموذج، ولكن لم يتم التحقق من تسليم البريد الإلكتروني وآخر نتيجة للبريد العشوائي هي %s/100. تم حفظ النموذج، ولكن قد لا تصلك رسائل البريد الإلكتروني الخاصة بإشعارات المشرف حتى يتم إصلاح تسليم SMTP/البريد الإلكتروني.',
  'Notification emails are turned off' => 'تم إيقاف رسائل الإعلام الإلكترونية',
  'Flux Forms will not send any email — neither to you nor to the person who submits this form — until "This site can send emails" is enabled in Email Settings.' => 'لن تقوم Flux Forms بإرسال أي بريد إلكتروني - لا إليك ولا إلى الشخص الذي يرسل هذا النموذج - حتى يتم تمكين "يمكن لهذا الموقع إرسال رسائل بريد إلكتروني" في إعدادات البريد الإلكتروني.',
  'Enable email sending' => 'تمكين إرسال البريد الإلكتروني',
  'Click "Check Email Server" to test delivery, turn this switch on, then press Save.' => 'انقر فوق "التحقق من خادم البريد الإلكتروني" لاختبار التسليم، ثم قم بتشغيل هذا المفتاح، ثم اضغط "حفظ".',
  'Delivery is taking longer than expected' => 'يستغرق التسليم وقتًا أطول من المتوقع',
  'WordPress sent the test email, but our server has not received it yet. This may be a temporary delay. Check the diagnostics below to troubleshoot.' => 'أرسل WordPress رسالة البريد الإلكتروني التجريبية، لكن خادمنا لم يستلمها بعد. قد يكون هذا تأخيرًا مؤقتًا. تحقق من التشخيص أدناه لاستكشاف الأخطاء وإصلاحها.',
  'Prepare Test' => 'تحضير الاختبار',
  'Connecting to WhiteStudio to generate a unique test email address.' => 'الاتصال بـ WhiteStudio لإنشاء عنوان بريد إلكتروني فريد للاختبار.',
  'WordPress Sends the Email' => 'يرسل WordPress البريد الإلكتروني',
  'WordPress hands a real message to your mail server. A tick here means WordPress sent it, not yet that it arrived.' => 'يسلم WordPress رسالة حقيقية إلى خادم البريد الخاص بك. علامة الاختيار هنا تعني أن WordPress قد أرسلها، ولم تصل بعد.',
  'Waiting for Delivery' => 'في انتظار التسليم',
  'Checking whether the test email arrived at our server (usually takes a few seconds).' => 'التحقق من وصول البريد الإلكتروني التجريبي إلى الخادم الخاص بنا (يستغرق عادةً بضع ثوانٍ).',
  'Quick Result' => 'نتيجة سريعة',
  'Showing the first delivery result — you will see right away if email is working.' => 'عرض نتيجة التسليم الأولى — ستعرف على الفور ما إذا كان البريد الإلكتروني يعمل أم لا.',
  'Full Report' => 'التقرير الكامل',
  'A detailed HTML report with full diagnostics is being prepared and emailed to you.' => 'جاري إعداد تقرير HTML مفصل يتضمن تشخيصات كاملة وإرساله إليك عبر البريد الإلكتروني.',
  'Needs attention' => 'يحتاج إلى الاهتمام',
  '%s of 5 steps done' => ' تم تنفيذ %s من 5 خطوات',
  'Step %s of 5' => 'الخطوة %s من 5',
  '/ 100' => '/ 100',
  'Test started' => 'بدأ الاختبار',
  'A unique address is being generated for this test.' => 'جاري الآن إنشاء عنوان فريد لهذا الاختبار.',
  'Waiting for the email to arrive' => 'في انتظار وصول البريد الإلكتروني',
  'We check our server every few seconds. Please keep this page open.' => 'نحن نتحقق من الخادم الخاص بنا كل بضع ثوانٍ. الرجاء إبقاء هذه الصفحة مفتوحة.',
  'Your email server is healthy' => 'خادم البريد الإلكتروني الخاص بك سليم',
  'The test email arrived, and the subject and unique-code checks both passed.' => 'وصلت رسالة البريد الإلكتروني الاختبارية، وتم اجتياز عملية التحقق من الموضوع والرمز الفريد.',
  'Delivered, but likely to be filtered as spam' => 'تم التسليم، ولكن من المحتمل أن تتم تصفيته كرسائل غير مرغوب فيها',
  'Delivered, but deliverability is weak' => 'تم التسليم، ولكن إمكانية التسليم ضعيفة',
  'No email arrived' => 'لم يصل أي بريد إلكتروني',
  'Nothing was received during the test window, so your server most likely cannot send email.' => 'لم يتم تلقي أي شيء أثناء نافذة الاختبار، لذلك على الأرجح لا يستطيع الخادم الخاص بك إرسال بريد إلكتروني.',
  'The test timed out' => 'انتهت مهلة الاختبار',
  'The test reached its time limit. Your server may be slow, or may block outbound email.' => 'وصل الاختبار إلى الحد الزمني المحدد له. قد يكون الخادم الخاص بك بطيئًا، أو قد يحظر البريد الإلكتروني الصادر.',
  'The test email could not be sent' => 'تعذر إرسال البريد الإلكتروني التجريبي',
  'WordPress returned an error while sending. See the message below.' => 'أرجع WordPress خطأً أثناء الإرسال. راجع الرسالة أدناه.',
  'The connection was lost' => 'تم فقدان الاتصال',
  'No answer came back from the server. Refresh the page and try again.' => 'لم يتم الحصول على أي إجابة من الخادم. قم بتحديث الصفحة وحاول مرة أخرى.',
  'This test needs a higher plan' => 'يحتاج هذا الاختبار إلى خطة أعلى',
  'Upgrade your plan to run the full delivery test.' => 'قم بترقية خطتك لإجراء اختبار التسليم الكامل.',
  'Your email server is working. A detailed HTML report has been sent to' => 'خادم البريد الإلكتروني الخاص بك يعمل. تم إرسال تقرير HTML مفصل إلى',
  'A complete email health report — including your spam score, deliverability details, and recommendations — will be sent within the next few minutes to' => 'سيتم إرسال تقرير كامل عن سلامة البريد الإلكتروني - بما في ذلك نقاط الرسائل غير المرغوب فيها وتفاصيل إمكانية التسليم والتوصيات - خلال الدقائق القليلة القادمة إلى',
