  'The test timed out. Please try again — your server may be slow or blocking outgoing mail.' => 'انتهت مهلة الاختبار. الرجاء المحاولة مرة أخرى — قد يكون الخادم الخاص بك بطيئًا أو يحظر البريد الصادر.',
  'Waiting for the test email to arrive…' => 'في انتظار وصول البريد الإلكتروني التجريبي...',
