  'Your subscription needs renewing before the missing add-ons can be restored.' => 'يحتاج اشتراكك إلى التجديد قبل أن تتمكن من استعادة الوظائف الإضافية المفقودة.',
  'The missing add-on files could not be restored. Check the server connection and file permissions, then try again.' => 'تعذرت استعادة ملفات الوظائف الإضافية المفقودة. تحقق من اتصال الخادم وأذونات الملفات، ثم حاول مرة أخرى.',
