  'Some add-on files are missing' => 'بعض ملفات الوظائف الإضافية مفقودة',
  'The plugin was updated, so its add-ons must be reinstalled before this page can load. Click the button below to install them.' => 'تم تحديث المكون الإضافي، لذا يجب إعادة تثبيت الوظائف الإضافية الخاصة به قبل أن تتمكن من تحميل هذه الصفحة. انقر فوق الزر أدناه لتثبيتها.',
