  'Automatic recovery was attempted but did not finish. Review the reason below, fix it if necessary, then try again.' => 'جرت محاولة الاسترداد التلقائي ولكنها لم تنته. راجع السبب أدناه، وقم بإصلاحه إذا لزم الأمر، ثم حاول مرة أخرى.',
