  'Reload now' => 'أعد التحميل الآن',
  'This form is temporarily unavailable.' => 'هذا النموذج غير متوفر مؤقتاً.',
  'We could not restore a required form component automatically. Please try again shortly; the site administrator can view the exact recovery error in Flux Forms.' => 'لم نتمكن من استعادة مكون النموذج المطلوب تلقائياً. يرجى المحاولة مرة أخرى قريبا؛ يمكن لمسؤول الموقع عرض خطأ الاسترداد الدقيق في Flux Forms.',
  'The add-on is already installed.' => 'الوظيفة الإضافية مثبتة مسبقاً.',
  'File access status not checked yet. Please wait.' => 'لم يتم التحقق من حالة الوصول إلى الملف بعد. الرجاء الانتظار.',
  'Error: server (%s) responded with an invalid request. responded code: %s' => 'خطأ: استجاب الخادم (%s) بطلب غير صالح. رمز الاستجابة: %s',
  'Cannot install add-ons of Flux Forms because the plugin is not able to connect to the %s server' => 'لا يمكن تثبيت الوظائف الإضافية لـ Flux Forms لأن المكون الإضافي غير قادر على الاتصال بملقم %s',
  'Your Easy Form Builder Pro subscription has expired, so the Pro add-ons could not be downloaded. The plugin keeps working without them. Renew your subscription to restore all Pro features:' => 'لقد انتهت صلاحية اشتراكك في Easy Form Builder Pro، لذا تعذر تنزيل الوظائف الإضافية Pro. يستمر البرنامج المساعد في العمل بدونها. قم بتجديد اشتراكك لاستعادة كافة ميزات Pro:',
  'The version of the add-on is not compatible with the version of the Flux Forms plugin.' => 'إصدار الوظيفة الإضافية غير متوافق مع إصدار البرنامج الإضافي Flux Forms.',
  'Cannot install add-ons of Flux Forms because the plugin is not able to download files' => 'لا يمكن تثبيت الوظائف الإضافية لـ Flux Forms لأن المكون الإضافي غير قادر على تنزيل الملفات',
  'Cannot install add-ons because this server has disabled the PHP filesystem functions needed to prepare the download. Please ask your hosting provider to enable mkdir and rename, or configure the WordPress filesystem.' => 'لا يمكن تثبيت الوظائف الإضافية لأن هذا الملقم قام بتعطيل وظائف نظام ملفات PHP اللازمة للتحضير للتنزيل. الرجاء مطالبة موفر الاستضافة بتمكين mkdir وإعادة تسمية نظام ملفات WordPress أو تكوينه.',
  'Cannot install add-ons of Flux Forms because the plugin is not able to move the downloaded file' => 'لا يمكن تثبيت الوظائف الإضافية لـ Flux Forms لأن المكون الإضافي غير قادر على نقل الملف الذي تم تنزيله',
  'Cannot install add-ons of Flux Forms because the plugin is not able to unzip files' => 'لا يمكن تثبيت الوظائف الإضافية لـ Flux Forms لأن المكون الإضافي غير قادر على فك ضغط الملفات',
  'To fix this, sign in to your %s, download the Add-ons Handler plugin from the Downloads section, then install and activate it. After that, activate the add-ons you need from the Add-ons Handler plugin.' => 'لإصلاح هذه المشكلة، قم بتسجيل الدخول إلى %s الخاص بك، وقم بتنزيل المكون الإضافي Add-ons Handler من قسم التنزيلات، ثم قم بتثبيته وتنشيطه. بعد ذلك، قم بتنشيط الوظائف الإضافية التي تحتاجها من المكون الإضافي Add-ons Handler.',
  'WhiteStudio dashboard' => 'لوحة تحكم WhiteStudio',
  'This bundled add-on is missing from the plugin files.' => 'هذه الوظيفة الإضافية المجمعة مفقودة من ملفات البرنامج الإضافي.',
  'The add-on server returned an unexpected response.' => 'أرجع خادم الوظيفة الإضافية استجابة غير متوقعة.',
  'The add-on could not be installed.' => 'تعذر تثبيت الوظيفة الإضافية.',
  'The add-on server did not provide a download URL.' => 'لم يوفر خادم الوظيفة الإضافية عنوان URL للتنزيل.',
  'The add-on download URL is not an approved Flux Forms source.' => 'عنوان URL لتنزيل الوظيفة الإضافية ليس مصدرًا معتمدًا لـ Flux Forms.',
  'Your server could not reach %1$s, so the add-on could not be downloaded. This is almost always a firewall on your hosting blocking the outgoing request, not a problem with your licence. To install add-ons without any download at all, sign in at %2$s and download the Flux Forms Add-ons Handler plugin, then install it like any other plugin. It contains every add-on your licence covers.' => 'تعذر على الخادم الخاص بك الوصول إلى %1$s، لذا تعذر تنزيل الوظيفة الإضافية. يكون هذا دائمًا بمثابة جدار حماية على الاستضافة الخاصة بك يمنع الطلب الصادر، ولا يمثل مشكلة في الترخيص الخاص بك. لتثبيت الإضافات دون أي تنزيل على الإطلاق، قم بتسجيل الدخول على %2$s وقم بتنزيل المكون الإضافي Flux Forms Add-ons Handler، ثم قم بتثبيته مثل أي مكون إضافي آخر. فهو يحتوي على كل الوظائف الإضافية التي تغطي تراخيصك.',
  'If you would rather fix the connection, ask your hosting provider why outgoing requests from %s are being blocked.' => 'إذا كنت تفضل إصلاح الاتصال، اسأل موفر الاستضافة عن سبب حظر الطلبات الصادرة من %s.',
  'Flux Forms: add-on downloads are being blocked' => 'نماذج التدفق: تم حظر تنزيلات الوظائف الإضافية',
  'Add-on affected: %s' => 'الوظيفة الإضافية المتأثرة: %s',
  'No response was recorded for this add-on.' => 'لم يتم تسجيل أي استجابة لهذه الوظيفة الإضافية.',
  'Writable' => 'قابل للكتابة',
  'Not writable — the add-on folder cannot be created or extracted into.' => 'غير قابل للكتابة — لا يمكن إنشاء مجلد الوظيفة الإضافية أو استخراجه إليه.',
  'Blocked by WP_HTTP_BLOCK_EXTERNAL — outgoing requests are disabled on this site.' => 'تم حظرها بواسطة WP_HTTP_BLOCK_EXTERNAL — تم تعطيل الطلبات الصادرة على هذا الموقع.',
  'DISABLE_WP_CRON is on — background retries only run if a server cron task calls wp-cron.php.' => 'DISABLE_WP_CRON قيد التشغيل - يتم تشغيل عمليات إعادة المحاولة في الخلفية فقط إذا كانت مهمة cron الخاصة بالخادم تستدعي wp-cron.php.',
  'Page that needed it' => 'الصفحة التي تحتاج إليها',
  'Plugin version' => 'إصدار البرنامج المساعد',
  'Add-on folder' => 'مجلد الوظائف الإضافية',
  'Outgoing requests' => 'الطلبات الصادرة',
  'WP-Cron' => 'WP-Cron',
  'Attempts made' => 'تم إجراء المحاولات',
  'Flux Forms could not reinstall its add-on files automatically. Forms that rely on those add-ons are showing a temporary message to visitors until this is resolved.' => 'تعذر على Flux Forms إعادة تثبيت ملفات الوظائف الإضافية الخاصة به تلقائياً. تعرض النماذج التي تعتمد على تلك الوظائف الإضافية رسالة مؤقتة للزائرين حتى يتم حل هذه المشكلة.',
  'What is missing' => 'ما هو المفقود',
  'Diagnostics' => 'التشخيص',
  'What to do next' => 'ما يجب فعله بعد ذلك',
  'Open Flux Forms in your dashboard and use the Recover add-ons button.' => 'افتح Flux Forms في لوحة المعلومات واستخدم زر "استرداد الوظائف الإضافية".',
  'If the add-on folder is not writable, ask your host to allow writing to the plugin folder.' => 'إذا كان مجلد الوظيفة الإضافية غير قابل للكتابة، فاطلب من مضيفك السماح بالكتابة إلى مجلد الوظيفة الإضافية.',
  'If outgoing requests are blocked, ask your host to allow connections to the Flux Forms update server.' => 'إذا تم حظر الطلبات الصادرة، فاطلب من مضيفك السماح بالاتصالات بملقم تحديث Flux Forms.',
  'If your Pro subscription has expired, renew it to restore the Pro add-ons.' => 'إذا انتهت صلاحية اشتراكك في Pro، قم بتجديده لاستعادة الوظائف الإضافية لـ Pro.',
  'We have made some updates. Please wait a few minutes before trying again.' => 'لقد أجرينا بعض التحديثات. الرجاء الانتظار بضع دقائق قبل المحاولة مرة أخرى.',
  'Cannot install add-ons of Flux Forms because the plugin is not able to connect to the whitestudio.team server' => 'لا يمكن تثبيت الوظائف الإضافية لـ Flux Forms لأن المكون الإضافي غير قادر على الاتصال بخادم Whitestudio.team',
  'One of the free features' => 'إحدى الميزات المجانية',
  'Important: Caching Plugin May Affect Flux Forms' => 'هام: قد يؤثر البرنامج الإضافي للتخزين المؤقت على نماذج التمويه',
  'The following caching plugins are active on your site:' => 'المكونات الإضافية التالية للتخزين المؤقت نشطة على موقعك:',
  'Plugin Name' => 'اسم البرنامج المساعد',
  'Slug' => 'سبيكة',
  'Please note that these plugins may affect the functionality of Flux Forms.' => 'الرجاء ملاحظة أن هذه المكونات الإضافية قد تؤثر على وظيفة Flux Forms.',
  'If you experience any issues, please exclude the page where your form is published from caching or disable these plugins. For detailed guidance on how to set up this exclusion, please refer to the documentation of the respective caching plugin.' => 'إذا واجهت أية مشكلات، فيرجى استبعاد الصفحة التي تم نشر النموذج الخاص بك فيها من التخزين المؤقت أو تعطيل هذه المكونات الإضافية. للحصول على إرشادات مفصلة حول كيفية إعداد هذا الاستثناء، يرجى الرجوع إلى وثائق البرنامج الإضافي للتخزين المؤقت المعني.',
  'Sent by' => 'تم الإرسال بواسطة',
  'Action needed: Flux Forms Pro is paused on %s' => 'الإجراء المطلوب: تم إيقاف Flux Forms Pro مؤقتًا على %s',
  'Flux Forms could not confirm your Pro licence for %1$s days in a row, so the Pro features on %2$s are paused for now.' => 'تعذر على Flux Forms تأكيد ترخيص Pro الخاص بك لمدة %1$s من الأيام المتتالية، لذا تم إيقاف ميزات Pro في %2$s مؤقتًا في الوقت الحالي.',
  'Your forms, entries and settings are untouched, every free feature keeps working, and your activation code is still stored &mdash; nothing was deleted.' => 'لم يتم تغيير النماذج والإدخالات والإعدادات الخاصة بك، وستستمر كل الميزات المجانية في العمل، ولا يزال رمز التنشيط الخاص بك مخزّنًا - ولم يتم حذف أي شيء.',
  'Open %1$sYT Form &rarr; Settings%2$s and press %1$sSave%2$s. That checks the licence again straight away; if the connection is back, Pro switches on within a minute.' => 'افتح نموذج %1$sYT → الإعدادات%2$s واضغط على %1$sحفظ%2$s. يقوم ذلك بالتحقق من الترخيص مرة أخرى على الفور؛ إذا عاد الاتصال، فسيتم تشغيل Pro خلال دقيقة.',
  'Still paused? Ask your hosting provider to allow outgoing HTTPS connections to %s &mdash; a firewall, proxy or regional block is the usual cause &mdash; then repeat step 1.' => 'هل ما زالت متوقفة مؤقتًا؟ اطلب من موفر الاستضافة السماح باتصالات HTTPS الصادرة بـ%s— جدار الحماية أو الوكيل أو الحظر الإقليمي هو السبب المعتاد — ثم كرر الخطوة 1.',
  'If your subscription has expired, or you moved this website to a new domain, %1$srenew or re-activate your licence%2$s and paste the new code into Settings.' => 'إذا انتهت صلاحية اشتراكك، أو قمت بنقل موقع الويب هذا إلى مجال جديد، %1$sقم بتجديد ترخيصك%2$s أو إعادة تنشيطه ولصق الرمز الجديد في الإعدادات.',
  'First failed check' => 'فشل الفحص الأول',
  'Grace period' => 'فترة السماح',
  'Activation code' => 'رمز التفعيل',
  'Error code' => 'رمز الخطأ',
  'How to bring Pro back' => 'كيفية إعادة النسخة الاحترافية',
  'Check my licence now' => 'التحقق من الترخيص الخاص بي الآن',
  'Still stuck? Send the details above to %1$sour support team%2$s and we will take it from there.' => 'هل ما زلت عالقًا؟ أرسل التفاصيل أعلاه إلى %1$sفريق الدعم لدينا%2$s وسنتولى الأمر من هناك.',
  'The licence server answered with an error and could not confirm your licence.' => 'أجاب خادم الترخيص بخطأ ولم يتمكن من تأكيد الترخيص الخاص بك.',
  'Your website could not reach the licence server &mdash; almost always a network, firewall or DNS restriction on the hosting side.' => 'تعذر على موقع الويب الخاص بك الوصول إلى خادم الترخيص — غالبًا ما يكون هناك قيود على الشبكة أو جدار الحماية أو DNS من جانب الاستضافة.',
  'The licence server&rsquo;s answer arrived damaged, usually because a security plugin, proxy or CDN changed it on the way.' => 'وصلت إجابة خادم الترخيص تالفة، وذلك عادةً بسبب قيام مكون إضافي للأمان أو وكيل أو CDN بتغييرها في الطريق.',
  'The licence check could not be completed.' => 'تعذر إكمال فحص الترخيص.',
  'Your activation code has expired!' => 'لقد انتهت صلاحية رمز التفعيل الخاص بك!',
  'Your Easy Form Builder Pro subscription has expired. To continue using the %s add-on and all Pro features, please renew your subscription.' => 'لقد انتهت صلاحية اشتراكك في Easy Form Builder Pro. لمواصلة استخدام الوظيفة الإضافية %s وجميع ميزات Pro، يرجى تجديد اشتراكك.',
  'Renew Subscription' => 'تجديد الاشتراك',
  'Pro Version Required' => 'الإصدار الاحترافي مطلوب',
  'The %s add-on is a Pro feature. Please upgrade to Flux Forms Pro to access this functionality.' => 'الوظيفة الإضافية %s هي ميزة احترافية. الرجاء الترقية إلى Flux Forms Pro للوصول إلى هذه الوظيفة.',
  'Your Easy Form Builder Pro subscription has expired. To continue enjoying all Pro features and keep your forms running, %1$sRenew your subscription now.%2$s' => 'لقد انتهت صلاحية اشتراكك في Easy Form Builder Pro. لمواصلة الاستمتاع بجميع ميزات Pro والحفاظ على تشغيل النماذج الخاصة بك، %1$sقم بتجديد اشتراكك الآن.%2$s',
  'The payment could not be verified yet.' => 'تعذر التحقق من الدفع بعد.',
  'This payment provider does not support refunds from the site.' => 'لا يدعم موفر الدفع هذا عمليات استرداد الأموال من الموقع.',
  'Trial' => 'محاكمة',
  'Canceled' => 'تم الإلغاء',
  'Amount mismatch' => 'المبلغ غير متطابق',
  'Unpaid' => 'غير مدفوعة',
  'Incomplete' => 'غير مكتمل',
  'Expired' => 'انتهت الصلاحية',
  'Sorry, you are not allowed to access this page.' => 'عذرًا، غير مسموح لك بالوصول إلى هذه الصفحة.',
  'Payments taken through your forms, from every payment provider. API keys and the active provider are set on the plugin Settings page, Payment tab.' => 'يتم سداد الدفعات من خلال النماذج الخاصة بك، من كل مزود خدمة دفع. يتم تعيين مفاتيح API والموفر النشط في صفحة إعدادات المكون الإضافي، علامة التبويب "الدفع".',
  'A Stripe webhook signing secret starts with "whsec_".' => 'يبدأ سر توقيع خطاف الويب الشريطي بـ "whsec_".',
  'Providers and webhooks' => 'الموفرون وخطافات الويب',
  'Configured' => 'تم تكوينه',
  'Not configured' => 'لم يتم تكوينه',
  'Webhook URL for this provider (if it sends payment notifications):' => 'عنوان URL للخطاف على الويب لهذا الموفر (إذا كان يرسل إعلامات الدفع):',
  'Recent payments' => 'الدفعات الأخيرة',
  'No payments yet.' => 'لا توجد دفعات حتى الآن.',
  'Confirmation code' => 'رمز التأكيد',
  'Transaction ID' => 'معرّف المعاملة',
  'Subscription' => 'الاشتراك',
  'One-time' => 'مرة واحدة',
  'The latest %d payments are shown.' => 'يتم عرض آخر دفعات %d.',
  'Test provider (development only)' => 'موفر الاختبار (التطوير فقط)',
  'Test outcome' => 'نتيجة الاختبار',
  'Approve every payment' => 'الموافقة على كل دفعة',
  'Decline every payment' => 'رفض كل دفعة',
  'No money is taken. Development only.' => 'لم يتم أخذ أي أموال. التطوير فقط.',
  'TEST MODE: no card is charged.' => 'وضع الاختبار: لم يتم شحن البطاقة.',
  'Test provider: the payment was declined.' => 'موفر الاختبار: تم رفض الدفع.',
  'Publishable key' => 'مفتاح قابل للنشر',
  'Stripe is not configured on this site. Please contact the site administrator.' => 'لم يتم تكوين الشريط على هذا الموقع. الرجاء الاتصال بمسؤول الموقع.',
  'The payment method of this form is not supported.' => 'طريقة الدفع لهذا النموذج غير معتمدة.',
  'The payment could not be started. Please try again.' => 'تعذر بدء الدفع. الرجاء المحاولة مرة أخرى.',
  'Optional but recommended: in the Stripe Dashboard add a webhook endpoint with this URL and the events payment_intent.succeeded, payment_intent.payment_failed, payment_intent.canceled, charge.refunded, customer.subscription.updated and customer.subscription.deleted, then paste its signing secret below.' => 'اختياري لكن موصى به: في لوحة معلومات Stripe، قم بإضافة نقطة نهاية خطاف الويب باستخدام URL هذا والأحداث Payment_intent.succeeded وPayment_intent.Payment_failed وPayment_intent.canceled وcharge.refunded وcustomer.subscription.updated وcustomer.subscription.deleted، ثم الصق سر التوقيع الخاص به أدناه.',
  'Webhook signing secret' => 'سر التوقيع على الويب',
  'Saved - leave empty to keep it' => 'تم الحفظ - اتركه فارغًا للاحتفاظ به',
  'Remove the saved secret' => 'قم بإزالة السر المحفوظ',
  'Invalid or expired nonce' => 'رقم غير صالح أو منتهية الصلاحية',
  'No payment provider is available on this site. Please contact the site administrator.' => 'لا يتوفر أي مزود دفع على هذا الموقع. الرجاء الاتصال بمسؤول الموقع.',
  'Too many payment attempts. Please wait a few minutes and try again.' => 'محاولات الدفع كثيرة جدًا. الرجاء الانتظار بضع دقائق ثم حاول مرة أخرى.',
  'Invalid payment data. Please refresh the page and try again.' => 'بيانات الدفع غير صالحة. الرجاء تحديث الصفحة والمحاولة مرة أخرى.',
  'The payment provider is not configured on this site. Please contact the site administrator.' => 'لم يتم تكوين موفر الدفع على هذا الموقع. الرجاء الاتصال بمسؤول الموقع.',
  'No payment amount detected. Please review your selected items and try again. If the problem persists, contact support.' => 'لم يتم اكتشاف مبلغ الدفع. يرجى مراجعة العناصر المحددة والمحاولة مرة أخرى. إذا استمرت المشكلة، فاتصل بالدعم.',
  'Too many requests. Please wait a moment and try again.' => 'الطلبات كثيرة جدًا. الرجاء الانتظار قليلاً ثم حاول مرة أخرى.',
  'Payment not found.' => 'لم يتم العثور على الدفعة.',
  'Your payment has not been confirmed yet. Please wait a moment and try again. If the problem persists, contact the site administrator.' => 'لم يتم تأكيد دفعتك بعد. الرجاء الانتظار لحظة وحاول مرة أخرى. إذا استمرت المشكلة، اتصل بمسؤول الموقع.',
  'Online payment is not available at the moment. Please try again later or contact us.' => 'الدفع عبر الإنترنت غير متاح في الوقت الحالي. يرجى المحاولة مرة أخرى لاحقاً أو الاتصال بنا.',
  'Active payment provider' => 'موفر الدفع النشط',
  'Payment forms take card payments through this provider. Only installed providers are listed.' => 'تستقبل نماذج الدفع دفعات البطاقة من خلال هذا الموفر. تم سرد الموفرين المثبتين فقط.',
  'Saved — leave empty to keep' => 'تم الحفظ — اتركه فارغًا للاحتفاظ به',
  '%s settings' => ' إعدادات %s',
  'Flux Forms replaces %s, which has been deactivated. Your forms, entries and settings stay in place. You can delete the old plugin.' => 'تحل Flux Forms محل %s، الذي تم إلغاء تنشيطه. تظل النماذج والإدخالات والإعدادات الخاصة بك في مكانها. يمكنك حذف المكوّن الإضافي القديم.',
  'Updating amount…' => 'جاري تحديث المبلغ...',
  'The amount could not be verified. Please check your selections and try again.' => 'تعذر التحقق من المبلغ. الرجاء التحقق من اختياراتك والمحاولة مرة أخرى.',
  'Subject made by Flux Forms (with the tracking code)' => 'تم إنشاء الموضوع بواسطة Flux Forms (باستخدام رمز التتبع)',
