  'Flux Donate is active but did not take over payments (filter flxb_own_payments is off?). Flux Forms uses its own Stripe settings.' => 'Flux Donate نشط ولكنه لم يتولى الدفعات (تم إيقاف تشغيل عامل التصفية flxb_own_ Payments؟). يستخدم Flux Forms إعدادات Stripe الخاصة به.',
  'Flux Donate is not active; Flux Forms takes payments itself with %s.' => 'Flux Donate غير نشط؛ تتلقى Flux Forms الدفعات بنفسها باستخدام %s.',
  'Flux Donate is not active and the Stripe keys are missing: %d payment form shows "Online payment is unavailable".' . chr(0) . 'Flux Donate is not active and the Stripe keys are missing: %d payment forms show "Online payment is unavailable".' => 'Flux Donate غير نشط والمفاتيح الشريطية مفقودة: تظهر نماذج الدفع %d"الدفع عبر الإنترنت غير متاح".' . chr(0) . 'Flux Donate غير نشط والمفاتيح الشريطية مفقودة: يُظهر نموذج الدفع %d"الدفع عبر الإنترنت غير متاح".' . chr(0) . 'Flux Donate غير نشط والمفاتيح الشريطية مفقودة: تظهر نماذج الدفع %d"الدفع عبر الإنترنت غير متاح".' . chr(0) . 'Flux Donate غير نشط والمفاتيح الشريطية مفقودة: تظهر نماذج الدفع %d"الدفع عبر الإنترنت غير متاح".' . chr(0) . 'Flux Donate غير نشط والمفاتيح الشريطية مفقودة: تظهر نماذج الدفع %d"الدفع عبر الإنترنت غير متاح".' . chr(0) . 'Flux Donate غير نشط والمفاتيح الشريطية مفقودة: تظهر نماذج الدفع %d"الدفع عبر الإنترنت غير متاح".',
  'Flux Donate is not active and no Stripe keys are set. No payment form exists, so nothing is affected.' => 'Flux Donate غير نشط ولم يتم تعيين أي مفاتيح شريطية. لا يوجد نموذج دفع، لذلك لن يتأثر أي شيء.',
  'Panel › Settings › Payment' => 'اللوحة › الإعدادات › الدفع',
  'Not active. Forms work; donations are not tracked and recurring iyzico payments are not available.' => 'غير نشط. عمل النماذج؛ لا يتم تعقب التبرعات ولا تتوفر دفعات iyzico المتكررة.',
  'Flux Certificates (automations)' => 'شهادات التدفق (الأتمتة)',
  'Version %s is active; certificate automations can run.' => 'الإصدار %s نشط؛ يمكن تشغيل عمليات أتمتة الشهادات.',
