  'Not active, but %d active automation creates or sends certificates; it will fail.' . chr(0) . 'Not active, but %d active automations create or send certificates; they will fail.' => 'غير نشطة، ولكن عمليات التشغيل الآلي النشطة لـ%d تقوم بإنشاء الشهادات أو إرسالها؛ سوف يفشلون.' . chr(0) . 'غير نشط، ولكن التشغيل الآلي النشط لـ%d يقوم بإنشاء الشهادات أو إرسالها؛ سوف تفشل.' . chr(0) . 'غير نشطة، ولكن عمليات التشغيل الآلي النشطة لـ%d تقوم بإنشاء الشهادات أو إرسالها؛ سوف يفشلون.' . chr(0) . 'غير نشطة، ولكن عمليات التشغيل الآلي النشطة لـ%d تقوم بإنشاء الشهادات أو إرسالها؛ سوف يفشلون.' . chr(0) . 'غير نشطة، ولكن عمليات التشغيل الآلي النشطة لـ%d تقوم بإنشاء الشهادات أو إرسالها؛ سوف يفشلون.' . chr(0) . 'غير نشطة، ولكن عمليات التشغيل الآلي النشطة لـ%d تقوم بإنشاء الشهادات أو إرسالها؛ سوف يفشلون.',
  'Not active. Needed only for certificate automations.' => 'غير نشط. مطلوب فقط لأتمتة الشهادات.',
  'Automations' => 'الأتمتة',
  'No automation is on. After a form or payment nothing runs automatically (certificate, e-mail, webhook).' => 'لا يوجد تشغيل تلقائي. بعد النموذج أو الدفع، لا يتم تشغيل أي شيء تلقائيًا (الشهادة، البريد الإلكتروني، خطاف الويب).',
  '%d automation is on.' . chr(0) . '%d automations are on.' => 'تم تشغيل عمليات التشغيل الآلي لـ%d.' . chr(0) . 'أتمتة %d قيد التشغيل.' . chr(0) . 'تم تشغيل عمليات التشغيل الآلي لـ%d.' . chr(0) . 'تم تشغيل عمليات التشغيل الآلي لـ%d.' . chr(0) . 'تم تشغيل عمليات التشغيل الآلي لـ%d.' . chr(0) . 'تم تشغيل عمليات التشغيل الآلي لـ%d.',
