  'Keys are set; %d form uses reCAPTCHA.' . chr(0) . 'Keys are set; %d forms use reCAPTCHA.' => 'تم ضبط المفاتيح؛  تستخدم نماذج %d reCAPTCHA.' . chr(0) . 'تم ضبط المفاتيح؛  يستخدم نموذج %d reCAPTCHA.' . chr(0) . 'تم ضبط المفاتيح؛  تستخدم نماذج %d reCAPTCHA.' . chr(0) . 'تم ضبط المفاتيح؛  تستخدم نماذج %d reCAPTCHA.' . chr(0) . 'تم ضبط المفاتيح؛  تستخدم نماذج %d reCAPTCHA.' . chr(0) . 'تم ضبط المفاتيح؛  تستخدم نماذج %d reCAPTCHA.',
  '%d form has reCAPTCHA on but the site key or secret key is missing; the form is not shown.' . chr(0) . '%d forms have reCAPTCHA on but the site key or secret key is missing; they are not shown.' => 'تحتوي نماذج %d على ميزة reCAPTCHA قيد التشغيل ولكن مفتاح الموقع أو المفتاح السري مفقود؛ لم يتم عرضها.' . chr(0) . 'يحتوي نموذج %d على ميزة reCAPTCHA قيد التشغيل ولكن مفتاح الموقع أو المفتاح السري مفقود؛ لا يظهر النموذج.' . chr(0) . 'تحتوي نماذج %d على ميزة reCAPTCHA قيد التشغيل ولكن مفتاح الموقع أو المفتاح السري مفقود؛ لم يتم عرضها.' . chr(0) . 'تحتوي نماذج %d على ميزة reCAPTCHA قيد التشغيل ولكن مفتاح الموقع أو المفتاح السري مفقود؛ لم يتم عرضها.' . chr(0) . 'تحتوي نماذج %d على ميزة reCAPTCHA قيد التشغيل ولكن مفتاح الموقع أو المفتاح السري مفقود؛ لم يتم عرضها.' . chr(0) . 'تحتوي نماذج %d على ميزة reCAPTCHA قيد التشغيل ولكن مفتاح الموقع أو المفتاح السري مفقود؛ لم يتم عرضها.',
