  'Replies per tracking code/hour' => 'الردود لكل رمز تتبع/ساعة',
  'Caps replies to one tracked conversation (across IPs). 0 disables.' => 'يقوم Caps بالرد على محادثة واحدة متعقبة (عبر عناوين IP). 0 معطل.',
  'Uploads per IP/min' => 'التحميلات لكل IP/الدقيقة',
  'Protects upload endpoint.' => 'يحمي نقطة نهاية التحميل.',
  'Payment starts per IP/min' => 'يبدأ الدفع لكل IP/دقيقة',
  'Protects payment REST routes.' => 'يحمي مسارات الدفع REST.',
  'File upload budget' => 'ميزانية تحميل الملف',
  'Flux Forms already limits uploads on its own: each visitor may upload three files per file field on the form, and the response box allows three. Leave a box at 0 to keep that automatic behaviour, or enter a number to set it yourself.' => 'تقيد Flux Forms عمليات التحميل من تلقاء نفسها: يمكن لكل زائر تحميل ثلاثة ملفات لكل حقل ملف في النموذج، ويسمح مربع الاستجابة بثلاثة. اترك المربع عند 0 للاحتفاظ بهذا السلوك التلقائي، أو أدخل رقمًا لتعيينه بنفسك.',
  'Uploads allowed per file field' => 'التحميلات مسموحة لكل حقل ملف',
  'Default 3, so a two-field form allows six uploads. 0 keeps the default.' => 'الافتراضي 3، لذا فإن النموذج المكون من حقلين يسمح بستة عمليات تحميل. 0 يحتفظ بالقيمة الافتراضية.',
  'Total uploads per visitor' => 'إجمالي التحميلات لكل زائر',
  'A fixed total that ignores how many fields the form has. 0 keeps the automatic per-field calculation.' => 'إجمالي ثابت يتجاهل عدد الحقول التي يحتوي عليها النموذج. 0 يحتفظ بالحساب التلقائي لكل حقل.',
  'Budget resets after (seconds)' => 'يتم إعادة تعيين الميزانية بعد (ثواني)',
  'Default 3600 (one hour). 0 keeps the default.' => 'الافتراضي 3600 (ساعة واحدة). 0 يحتفظ بالقيمة الافتراضية.',
  'Maximum file size (MB)' => 'الحد الأقصى لحجم الملف (ميجابايت)',
  'A site-wide ceiling. It can only tighten a per-field limit, never widen it. 0 keeps the field setting.' => 'سقف على مستوى الموقع. يمكنها فقط تشديد الحد لكل حقل، ولا توسعه أبدًا. 0 يحتفظ بإعدادات الحقل.',
  'Protect response lookup' => 'حماية البحث عن الاستجابة',
  'Rate-limit tracking-code searches by request count (no human-token check).' => 'البحث عن كود التتبع بحدود المعدل حسب عدد الطلبات (بدون فحص الرمز المميز البشري).',
  'Manual access lists' => 'قوائم الوصول اليدوي',
  'One entry per line: an exact IP or a wildcard prefix such as 203.0.113.* — allowlist bypasses all checks, blocklist blocks in every mode.' => 'إدخال واحد في كل سطر: عنوان IP محدد أو بادئة بدل مثل 203.0.113.* — تتجاوز القائمة المسموح بها جميع عمليات التحقق، وتحظر قوائم الحظر في كل وضع.',
  'IP allowlist' => 'القائمة المسموح بها لعنوان IP',
  'Trusted IPs that skip the shield completely (your office, monitoring bots).' => 'عناوين IP الموثوقة التي تتخطى الحماية تمامًا (مكتبك، برامج المراقبة).',
  'IP blocklist' => 'قائمة حظر IP',
  'IPs that are always blocked on protected form routes.' => 'عناوين IP المحظورة دائمًا على توجيهات النماذج المحمية.',
  'Minimum paid notification score' => 'الحد الأدنى لنتيجة الإشعارات المدفوعة',
  'Suppress costly notifications below this score.' => 'منع الإعلامات المكلفة التي تقل عن هذه النتيجة.',
  'SMS daily stop-loss' => 'إيقاف الخسارة اليومي عبر الرسائل النصية القصيرة',
  'Global SMS budget per day, across all recipients.' => 'ميزانية الرسائل النصية القصيرة (SMS) العالمية يوميًا، عبر كافة المستلمين.',
  'Telegram daily stop-loss' => 'إيقاف الخسارة اليومي في تيليجرام',
  'Global Telegram budget per day, across all recipients.' => 'ميزانية Telegram العالمية يوميًا، عبر جميع المستلمين.',
  'Webhook/Email daily stop-loss' => 'الخطاف عبر الويب/البريد الإلكتروني لإيقاف الخسارة اليومي',
  'Global webhook/email/sheet budget per day.' => 'خطاف ويب عالمي/بريد إلكتروني/ميزانية ورقة يوميًا.',
  'Per-recipient daily cap' => 'الحد الأقصى اليومي لكل مستلم',
  'Maximum notifications per single recipient per day (0 disables).' => 'الحد الأقصى من الإشعارات لكل مستلم واحد في اليوم (0 تعطيل).',
  'These limits become active for paid services after the core integration filter is added.' => 'تصبح هذه الحدود نشطة للخدمات المدفوعة بعد إضافة عامل تصفية التكامل الأساسي.',
  'Decisions — last 24 hours' => 'القرارات — آخر 24 ساعة',
  'Stacked per hour: allowed, blocked, quarantined and monitored requests.' => 'مجمعة لكل ساعة: الطلبات المسموح بها، والمحظورة، والمعزولة، والمراقبة.',
  'No decisions recorded in the last 24 hours.' => 'لم يتم تسجيل أي قرارات خلال 24 ساعة الماضية.',
  'Security logs' => 'سجلات الأمان',
  'Recent decisions without storing raw IP addresses.' => 'القرارات الأخيرة دون تخزين عناوين IP الأولية.',
  'Clear Human Shield logs?' => 'هل تريد مسح سجلات Human Shield؟',
  'Logs cleared.' => 'تم مسح السجلات.',
  'Latest security decisions.' => 'أحدث قرارات الأمان.',
  'No logs yet.' => 'لا توجد سجلات حتى الآن.',
  'Route' => 'المسار',
  'Score' => 'النتيجة',
  'Reasons' => 'الأسباب',
  'System readiness' => 'جاهزية النظام',
  'Human Shield checks these functions before enforcing security rules.' => 'يقوم Human Shield بالتحقق من هذه الوظائف قبل فرض قواعد الأمان.',
  'PHP requirements are ready.' => 'متطلبات PHP جاهزة.',
  'Some required PHP functions are unavailable.' => 'بعض وظائف PHP المطلوبة غير متوفرة.',
  'REST API:' => 'واجهة برمجة تطبيقات REST:',
