  'Tables:' => 'الجداول:',
  'ready' => 'جاهز',
  'not ready yet' => 'ليست جاهزة بعد',
  'Recommended only after you verify PHP functions and tables are ready.' => 'يوصى به فقط بعد التحقق من أن وظائف وجداول PHP جاهزة.',
  'Trust proxy IP headers' => 'الوثوق برؤوس IP للوكيل',
  'Use forwarding headers only when the immediate peer matches the trusted proxy list below.' => 'استخدم إعادة توجيه الرؤوس فقط عندما يتطابق النظير المباشر مع قائمة الوكيل الموثوق به أدناه.',
  'Trusted proxy IPs' => 'عناوين IP الوكيلة الموثوقة',
  'One exact IP or wildcard prefix per line. Add only your load balancer/CDN egress addresses; keep this empty when the origin is directly reachable.' => 'عنوان IP أو بادئة بدل واحدة محددة لكل سطر. أضف فقط موازن التحميل/عناوين خروج CDN الخاصة بك؛ أبقِ هذا فارغًا عندما يكون من الممكن الوصول إلى الأصل مباشرةً.',
  'Store raw behavior metrics' => 'تخزين مقاييس السلوك الأولية',
  'Keep off for privacy unless debugging a rollout.' => 'توقف عن العمل للحفاظ على الخصوصية ما لم يتم تصحيح أخطاء الطرح.',
  'Log retention days' => 'تسجيل أيام الاحتفاظ',
  'How long events should be retained.' => 'مدة الاحتفاظ بالأحداث.',
  'Client attestation timeout' => 'انتهت مهلة تصديق العميل',
  'Milliseconds before the browser falls back to the normal request.' => 'ملي ثانية قبل عودة المستعرض إلى الطلب العادي.',
  'If a required PHP function is disabled, enable it in php.ini disable_functions or ask the host to allow it. Cache and security plugins must not cache or rewrite POST responses from /wp-json/EmsfbShield/v1/*.' => 'إذا تم تعطيل إحدى وظائف PHP المطلوبة، قم بتمكينها في php.ini Disable_functions أو اطلب من المضيف السماح بذلك. يجب ألا تقوم ذاكرة التخزين المؤقت والمكونات الإضافية للأمان بالتخزين المؤقت أو إعادة كتابة استجابات POST من /wp-json/EmsfbShield/v1/*.',
  'Security & Spam Protection tabs' => 'علامات التبويب "الأمان والحماية من البريد العشوائي"',
  'Security log export is unavailable because this server has disabled a required PHP function: %s. Ask your hosting provider to enable it.' => 'تصدير سجل الأمان غير متاح لأن هذا الملقم قام بتعطيل وظيفة PHP مطلوبة: %s. اطلب من موفر الاستضافة تمكينه.',
  'Security log export is unavailable because this server has disabled required PHP functions: %s. Ask your hosting provider to enable them.' => 'تصدير سجل الأمان غير متاح لأن هذا الملقم قام بتعطيل وظائف PHP المطلوبة: %s. اطلب من موفر الاستضافة تمكينها.',
