  'Datasets' => 'مجموعات البيانات',
  'Datasets available for auto-populate' => 'مجموعات البيانات المتوفرة للملء التلقائي',
  'No datasets yet. Upload a CSV file to get started.' => 'لا توجد مجموعات بيانات حتى الآن. قم بتحميل ملف CSV للبدء.',
