  'Prepare CSV' => 'تحضير ملف CSV',
  'Upload the CSV file using the upload button.' => 'قم بتحميل ملف CSV باستخدام زر التحميل.',
  'Upload Dataset' => 'تحميل مجموعة البيانات',
  'In Form Builder, open Form Settings and enable "Auto-Populate". Choose your dataset, then map elements to dataset fields as search conditions.' => 'في "منشئ النماذج"، افتح "إعدادات النموذج" وقم بتمكين "الملء التلقائي". اختر مجموعة البيانات الخاصة بك، ثم قم بتعيين العناصر إلى حقول مجموعة البيانات كشروط بحث.',
  'Enable Auto-Populate' => 'تمكين الملء التلقائي',
  'For each target field, enable "Auto-Populate to automatically populate this field" and select the dataset column to auto-populate.' => 'بالنسبة لكل حقل مستهدف، قم بتمكين "الملء التلقائي لملء هذا الحقل تلقائيًا" وحدد عمود مجموعة البيانات لملءه تلقائيًا.',
  'Map Fields' => 'حقول الخريطة',
  'You can edit dataset values inline by clicking on them.' => 'يمكنك تحرير قيم مجموعة البيانات بشكل مضمّن عن طريق النقر عليها.',
  'Follow these steps to set up auto-populate for your forms' => 'اتبع هذه الخطوات لإعداد التعبئة التلقائية للنماذج الخاصة بك',
  'Quick Start Guide' => 'دليل البدء السريع',
  'Tips & Notes' => 'نصائح وملاحظات',
  'Editing Data' => 'تحرير البيانات',
  'Supported format: CSV with UTF-8 encoding.' => 'التنسيق المعتمد: ملف CSV بتشفير UTF-8.',
  'Form Builder Tips' => 'نصائح منشئ النماذج',
  'Use conditions to filter dataset rows based on user input.' => 'استخدم الشروط لتصفية صفوف مجموعة البيانات بناءً على إدخال المستخدم.',
  'Multiple fields can auto-populate from the same dataset.' => 'يمكن تعبئة الحقول المتعددة تلقائيًا من نفس مجموعة البيانات.',
  'Changes to the dataset take effect immediately for new form submissions.' => 'تسري التغييرات على مجموعة البيانات فورًا لعمليات إرسال النماذج الجديدة.',
  'Connect & Manage API Integrations' => 'الاتصال وإدارة عمليات تكامل واجهة برمجة التطبيقات',
  'Real-time Data' => 'بيانات الوقت الحقيقي',
  'Field Mapping' => 'تعيين الحقل',
  'Smart Cache' => 'ذاكرة التخزين المؤقت الذكية',
  'Total Connections' => 'إجمالي الاتصالات',
  'API connections configured' => 'تم تكوين اتصالات API',
  'How to use API Integrations' => 'كيفية استخدام عمليات تكامل واجهة برمجة التطبيقات',
  'Follow these steps to connect your external API' => 'اتبع هذه الخطوات لتوصيل واجهة برمجة التطبيقات الخارجية لديك',
  'Click "Add API Connection" to create a new connection and enter your API endpoint URL.' => 'انقر فوق "إضافة اتصال API" لإنشاء اتصال جديد وإدخال عنوان URL لنقطة نهاية API الخاصة بك.',
  'Add Connection' => 'إضافة اتصال',
  'Configure authentication (API Key, Bearer Token, or Basic Auth) if your API requires it.' => 'قم بتكوين المصادقة (مفتاح API، أو Bearer Token، أو المصادقة الأساسية) إذا كانت API لديك تتطلب ذلك.',
  'Select a form and map API response fields to your form fields for auto-populate.' => 'حدد نموذجًا وقم بتعيين حقول استجابة واجهة برمجة التطبيقات (API) إلى حقول النموذج الخاص بك لملءها تلقائيًا.',
  'Use the Test button to verify the API returns expected data, then save your connection.' => 'استخدم الزر "اختبار" للتحقق من قيام API بإرجاع البيانات المتوقعة، ثم احفظ اتصالك.',
  'Test & Save' => 'اختبار وحفظ',
  'Use cache settings to reduce API calls and improve performance.' => 'استخدم إعدادات ذاكرة التخزين المؤقت لتقليل استدعاءات API وتحسين الأداء.',
  'Set a reasonable timeout to prevent slow form loading.' => 'قم بتعيين مهلة معقولة لمنع التحميل البطيء للنموذج.',
  'Always use HTTPS endpoints for secure data transfer.' => 'استخدم دائمًا نقاط نهاية HTTPS لنقل البيانات بشكل آمن.',
  'Keep API keys confidential — they are stored securely in WordPress.' => 'حافظ على سرية مفاتيح API — حيث يتم تخزينها بشكل آمن في WordPress.',
  'API responses are fetched in real-time when the form loads. Enable caching for frequently accessed data.' => 'يتم جلب استجابات واجهة برمجة التطبيقات (API) في الوقت الفعلي عند تحميل النموذج. تمكين التخزين المؤقت للبيانات التي يتم الوصول إليها بشكل متكرر.',
