  'Sync Form Responses to Google Sheets' => 'مزامنة استجابات النماذج مع جداول بيانات Google',
  'Automatically send form submissions to your Google Sheets. Connect one or more service accounts, link a sheet to each form, and let data flow in real time — no webhook or browser login required.' => 'أرسل عمليات إرسال النماذج تلقائيًا إلى جداول بيانات Google. قم بتوصيل حساب خدمة واحد أو أكثر، وربط ورقة بكل نموذج، والسماح بتدفق البيانات في الوقت الحقيقي - لا يلزم وجود خطاف ويب أو تسجيل دخول للمتصفح.',
