  '%d service account connected' . chr(0) . '%d service accounts connected' => 'حسابات خدمة %d متصلة' . chr(0) . 'حساب خدمة %d متصل' . chr(0) . 'حسابات خدمة %d متصلة' . chr(0) . 'حسابات خدمة %d متصلة' . chr(0) . 'حسابات خدمة %d متصلة' . chr(0) . 'حسابات خدمة %d متصلة',
