  'Help & Guide' => 'تعليمات وتوجيهات',
  'Saved successfully.' => 'تم الحفظ بنجاح.',
  'Open in Google Sheets' => 'فتح في جداول بيانات Google',
  'Service Accounts' => 'حسابات الخدمة',
  'Connect one or more Google service accounts — no browser login required' => 'قم بتوصيل حساب واحد أو أكثر من حسابات خدمة Google — لا يلزم تسجيل الدخول إلى المتصفح',
  'Your server is missing the PHP OpenSSL extension.' => 'يفتقد الملقم الخاص بك ملحق PHP OpenSSL.',
  'Google Sheet sync cannot work until it is enabled. Please ask your host to enable the %s PHP extension, then reload this page.' => 'لا يمكن أن تعمل مزامنة جداول بيانات Google حتى يتم تمكينها. الرجاء مطالبة مضيفك بتمكين ملحق %s PHP، ثم إعادة تحميل هذه الصفحة.',
  'Copy this email' => 'انسخ هذا البريد الإلكتروني',
  'Copy email' => 'نسخ البريد الإلكتروني',
  'To sync an <strong>existing</strong> sheet: open it in Google Sheets &rarr; <strong>Share</strong> &rarr; paste the email above &rarr; set role to <strong>Editor</strong>. To create a <strong>new</strong> sheet, just use Form Bindings — no sharing needed.' => 'لمزامنة ورقة<strong>موجودة في</strong>: افتحها في جداول بيانات Google ←<strong>شارك</strong>← الصق البريد الإلكتروني أعلاه ← اضبط الدور على<strong>Editor</strong>. لإنشاء ورقة<strong>جديدة</strong>، ما عليك سوى استخدام روابط النماذج — لا حاجة للمشاركة.',
  'Set Default' => 'تعيين كافتراضي',
  'Retest' => 'إعادة الاختبار',
  'Let’s connect Google Sheets — about 3 minutes, one time' => 'دعونا نربط جداول بيانات Google — حوالي 3 دقائق، مرة واحدة',
  'Follow the numbered steps on the right to download a free service account key from Google, then drop the file below. You only do this once. After that, creating a sheet for any form is a couple of clicks.' => 'اتبع الخطوات المرقمة على اليمين لتنزيل مفتاح حساب خدمة مجاني من Google، ثم قم بإسقاط الملف أدناه. أنت تفعل هذا مرة واحدة فقط. بعد ذلك، يتم إنشاء ورقة لأي نموذج ببضع نقرات.',
  'Your Google email' => 'بريدك الإلكتروني على Google',
  '(recommended)' => '(مستحسن)',
  'Any sheet the plugin <strong>creates</strong> is automatically shared to this address, so it appears in your own Google Drive under “Shared with me.” Without it, new sheets stay hidden inside the service account.' => 'أي ورقة ينشئها المكون الإضافي<strong></strong>تتم مشاركتها تلقائيًا على هذا العنوان، لذلك تظهر في Google Drive الخاص بك ضمن "تمت مشاركتها معي". وبدون ذلك، تظل الأوراق الجديدة مخفية داخل حساب الخدمة.',
  'Enable Google Sheet Integration' => 'تمكين تكامل جداول بيانات Google',
  'Sync form submissions to your spreadsheets automatically' => 'مزامنة عمليات إرسال النماذج إلى جداول البيانات تلقائيًا',
  'Drag & drop service account JSON file(s) here' => 'قم بسحب وإفلات ملف (ملفات) حساب الخدمة JSON هنا',
  'or click to browse — you can add multiple service accounts at once' => 'أو انقر للتصفح — يمكنك إضافة حسابات خدمة متعددة في وقت واحد',
  'Connected service accounts' => 'حسابات الخدمة المتصلة',
  'One-time setup (≈3 min)' => 'الإعداد لمرة واحدة (≈3 دقائق)',
  'Go to <a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a> &rarr; Project dropdown (top-left) &rarr; New Project &rarr; name it &rarr; Create' => 'انتقل إلى<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a>→ القائمة المنسدلة للمشروع (أعلى اليسار) → مشروع جديد → قم بتسميته → إنشاء',
  'APIs &amp; Services &rarr; Library &rarr; enable <strong>Google Sheets API</strong> <em>and</em> <strong>Google Drive API</strong>' => 'واجهات برمجة التطبيقات والخدمات → المكتبة → تمكين<strong>Google Sheets API</strong><em>و</em><strong>Google Drive API</strong>',
  'APIs &amp; Services &rarr; Credentials &rarr; Create Credentials &rarr; Service Account &rarr; name it &rarr; Done' => 'واجهات برمجة التطبيقات والخدمات → بيانات الاعتماد → إنشاء بيانات الاعتماد → حساب الخدمة → قم بتسميته → تم',
  'Open the service account &rarr; Keys tab &rarr; Add Key &rarr; Create New Key &rarr; JSON (downloads automatically)' => 'افتح حساب الخدمة ← علامة تبويب المفاتيح ← إضافة مفتاح ← إنشاء مفتاح جديد ← JSON (يتم التنزيل تلقائيًا)',
  'Drag that downloaded file into the box on the left — it is tested automatically' => 'اسحب الملف الذي تم تنزيله إلى المربع الموجود على اليسار — سيتم اختباره تلقائيًا',
  'Add <strong>Your Google email</strong> above so created sheets land in your Drive' => 'أضف<strong>بريدك الإلكتروني في Google</strong>أعلاه بحيث تصل الأوراق التي تم إنشاؤها إلى Drive',
  'Please choose a valid .json key file.' => 'الرجاء اختيار ملف مفتاح .json صالح.',
  'Could not read file: %s' => 'تعذرت قراءة الملف: %s',
  'Connecting service account…' => 'جارٍ توصيل حساب الخدمة...',
  'Service account added.' => 'تمت إضافة حساب الخدمة.',
  'Saved. New sheets created by the plugin will be shared to %s automatically.' => 'تم الحفظ. ستتم مشاركة الأوراق الجديدة التي أنشأها البرنامج الإضافي مع %s تلقائيًا.',
  'Email cleared. New sheets will stay inside the service account until you share them.' => 'تم مسح البريد الإلكتروني. ستبقى الأوراق الجديدة داخل حساب الخدمة حتى تقوم بمشاركتها.',
