  'Service Account' => 'حساب الخدمة',
  'Loading your spreadsheets…' => 'جارٍ تحميل جداول البيانات...',
  'Click <strong>“Browse My Sheets”</strong> to list spreadsheets this service account can already access, or <strong>“Create New Sheet”</strong> to make a fresh one.' => 'انقر فوق<strong>"استعراض أوراقي"</strong>لسرد جداول البيانات التي يمكن لحساب الخدمة هذا الوصول إليها بالفعل، أو<strong>"إنشاء ورقة جديدة"</strong>لإنشاء ورقة جديدة.',
  '<strong>No spreadsheets are accessible to this service account yet.</strong> You have two options:' => '<strong>لا يمكن الوصول إلى جداول البيانات لحساب الخدمة هذا حتى الآن.</strong>لديك خياران:',
  '<strong>Easiest:</strong> click <em>“Create New Sheet”</em> above — it is made for you and shared to your email automatically.' => '<strong>الأسهل:</strong>انقر فوق<em>"إنشاء ورقة جديدة"</em>أعلاه — فهي مصممة خصيصًا لك ويتم مشاركتها مع بريدك الإلكتروني تلقائيًا.',
  '<strong>Use an existing sheet:</strong> open it in Google Sheets &rarr; Share &rarr; paste' => '<strong>استخدم ورقة موجودة:</strong>افتحها في جداول بيانات Google → مشاركة → لصق',
  '&rarr; Editor, then click <em>Browse My Sheets</em> again.' => '→ المحرر، ثم انقر فوق<em>"استعراض الأوراق الخاصة بي"</em>مرة أخرى.',
  'the service account email' => 'البريد الإلكتروني لحساب الخدمة',
  'Create a new spreadsheet' => 'إنشاء جدول بيانات جديد',
  'New spreadsheet title (e.g. Contact form responses)' => 'عنوان جدول بيانات جديد (على سبيل المثال، ردود نماذج الاتصال)',
  'Your Google email — the sheet is shared here so you can open it' => 'بريدك الإلكتروني على Google — تتم مشاركة الورقة هنا حتى تتمكن من فتحها',
  'Pre-filled from your saved email.' => 'تم ملؤها مسبقًا من بريدك الإلكتروني المحفوظ.',
  'Leave empty only if you don’t need to open the sheet yourself.' => 'اتركه فارغًا فقط إذا لم تكن بحاجة إلى فتح الورقة بنفسك.',
  'Create Sheet' => 'إنشاء ورقة',
  'Creating…' => 'جارٍ الإنشاء...',
  'Creating spreadsheet…' => 'جاري إنشاء جدول بيانات...',
  'Sheet created and shared with your email. It’s selected below — click Next to finish.' => 'تم إنشاء الورقة ومشاركتها مع بريدك الإلكتروني. تم تحديده أدناه — انقر فوق "التالي" للإنهاء.',
  'Sheet created. Tip: add “Your Google email” on the Connections tab so new sheets are shared to you automatically.' => 'تم إنشاء الورقة. نصيحة: أضف "بريدك الإلكتروني على Google" في علامة التبويب "الاتصالات" حتى تتم مشاركة الأوراق الجديدة معك تلقائيًا.',
  'Open the new sheet' => 'افتح الورقة الجديدة',
  'Selected:' => 'محدد:',
