  'Or type a new tab name (created automatically)' => 'أو اكتب اسم علامة تبويب جديدة (يتم إنشاؤها تلقائيًا)',
  'Browse My Sheets' => 'تصفح أوراقي',
  'Create New Sheet' => 'إنشاء ورقة جديدة',
  'Choose or create a spreadsheet first' => 'اختر جدول بيانات أو أنشئه أولاً',
  'Please select a service account.' => 'الرجاء تحديد حساب خدمة.',
  'Please choose or create a spreadsheet first.' => 'الرجاء اختيار أو إنشاء جدول بيانات أولاً.',
  'Enable Sync for this Form' => 'تمكين المزامنة لهذا النموذج',
  'Disable to pause without deleting the binding' => 'تعطيل الإيقاف المؤقت دون حذف الارتباط',
  'Reading this form’s fields…' => 'قراءة حقول هذا النموذج...',
  'We couldn’t read this form’s fields automatically, so column mapping isn’t available. Don’t worry — <strong>every submitted field will still be synced automatically</strong>, each in its own column, in submission order. The header row is created and kept up to date for you.' => 'لم نتمكن من قراءة حقول هذا النموذج تلقائيًا، لذا فإن تعيين الأعمدة غير متاح. لا تقلق —<strong>ستتم مزامنة كل حقل مُرسل تلقائيًا</strong>، كل في العمود الخاص به، بترتيب الإرسال. يتم إنشاء صف الرأس وتحديثه لك.',
  'Drag rows (or use ▲▼) to set the <strong>column order</strong>. Rename any <strong>header</strong>. Turn a field off to skip its column. The letter (A, B, C…) shows where each field lands.' => 'اسحب الصفوف (أو استخدم ▲▼) لتعيين ترتيب الأعمدة<strong></strong>. إعادة تسمية أي رأس<strong></strong>. قم بإيقاف تشغيل الحقل لتخطي العمود الخاص به. يُظهر الحرف (A، B، C...) مكان وصول كل حقل.',
  'Col' => 'العقيد',
  'Spreadsheet header' => 'رأس جدول البيانات',
  'Order / On' => 'الطلب / تشغيل',
  'Refresh fields from form' => 'تحديث الحقول من النموذج',
  'Columns & Field Mapping' => 'تعيين الأعمدة والحقول',
  'Submitted time' => 'وقت الإرسال',
  'Submitted At' => 'تم الإرسال في',
  'Column header' => 'رأس العمود',
  'Include this field' => 'قم بتضمين هذا الحقل',
  '%d column will be written to the sheet.' . chr(0) . '%d columns will be written to the sheet.' => 'ستتم كتابة أعمدة %d على الورقة.' . chr(0) . 'سيتم كتابة عمود %d على الورقة.' . chr(0) . 'ستتم كتابة أعمدة %d على الورقة.' . chr(0) . 'ستتم كتابة أعمدة %d على الورقة.' . chr(0) . 'ستتم كتابة أعمدة %d على الورقة.' . chr(0) . 'ستتم كتابة أعمدة %d على الورقة.',
  'Sheet Style' => 'نمط الورقة',
  '(Google theme)' => '(موضوع Google)',
  'Pick a look for the sheet — colored header, frozen top row and alternating row colors (Google Sheets’ own styling). It’s applied automatically on the first sync, or apply it now.' => 'اختر مظهرًا للورقة - الرأس الملون والصف العلوي المجمد وألوان الصفوف البديلة (التصميم الخاص بجداول بيانات Google)." يتم تطبيقه تلقائيًا عند المزامنة الأولى، أو قم بتطبيقه الآن.',
  'Apply style now' => 'تطبيق النمط الآن',
  'Applying…' => 'جارٍ التقديم...',
  'Optional — it also applies on the first submission.' => 'اختياري — ينطبق أيضًا على الإرسال الأول.',
  'Spreadsheet:' => 'جدول البيانات:',
  'Tab:' => 'علامة التبويب:',
  'Columns:' => 'الأعمدة:',
  '%d mapped' => ' تم تعيين %d',
  'all submitted fields (auto)' => 'كافة الحقول المرسلة (تلقائي)',
  'Style:' => 'النمط:',
  'After saving, submit the form once to create the header row and confirm the first sync.' => 'بعد الحفظ، قم بإرسال النموذج مرة واحدة لإنشاء صف الرأس وتأكيد المزامنة الأولى.',
  'Save Binding' => 'حفظ الربط',
  'Please choose a spreadsheet first.' => 'الرجاء اختيار جدول بيانات أولاً.',
  'Pick a style first — “None” leaves the sheet unstyled.' => 'اختر نمطًا أولاً — يؤدي اختيار "بلا" إلى ترك الورقة بدون نمط.',
  'Style applied.' => 'تم تطبيق النمط.',
  'Please select a form.' => 'الرجاء تحديد نموذج.',
  'Please choose a spreadsheet.' => 'الرجاء اختيار جدول بيانات.',
  'Binding saved.' => 'تم حفظ التضمين.',
  'Remove this binding? Syncing stops for this form. Your Google Sheet and its data are not deleted.' => 'هل تريد إزالة هذا الارتباط؟ تتوقف المزامنة لهذا النموذج. لن يتم حذف جدول بيانات Google الخاص بك وبياناته.',
  'Sync removed — your Google Sheet and its data are untouched.' => 'تمت إزالة المزامنة - لم يتم تغيير جدول بيانات Google الخاص بك وبياناته.',
  'Remove ALL %d binding? Syncing stops for every form. Your Google Sheets are not deleted.' . chr(0) . 'Remove ALL %d bindings? Syncing stops for every form. Your Google Sheets are not deleted.' => 'هل تريد إزالة جميع روابط %d؟ تتوقف المزامنة لكل نموذج. لا يتم حذف جداول بيانات Google الخاصة بك.' . chr(0) . 'هل تريد إزالة جميع روابط %d؟ تتوقف المزامنة لكل نموذج. لا يتم حذف جداول بيانات Google الخاصة بك.' . chr(0) . 'هل تريد إزالة جميع روابط %d؟ تتوقف المزامنة لكل نموذج. لا يتم حذف جداول بيانات Google الخاصة بك.' . chr(0) . 'هل تريد إزالة جميع روابط %d؟ تتوقف المزامنة لكل نموذج. لا يتم حذف جداول بيانات Google الخاصة بك.' . chr(0) . 'هل تريد إزالة جميع روابط %d؟ تتوقف المزامنة لكل نموذج. لا يتم حذف جداول بيانات Google الخاصة بك.' . chr(0) . 'هل تريد إزالة جميع روابط %d؟ تتوقف المزامنة لكل نموذج. لا يتم حذف جداول بيانات Google الخاصة بك.',
  'All bindings removed. Your Google Sheets are untouched.' => 'تمت إزالة كافة الارتباطات. لم يتم تغيير جداول بيانات Google الخاصة بك.',
  'Help & Setup Guide' => 'دليل التعليمات والإعداد',
  'Everything you need to connect forms to Google Sheets' => 'كل ما تحتاجه لربط النماذج بجداول بيانات Google',
  'Step-by-Step Setup' => 'الإعداد خطوة بخطوة',
  'Create or Select a Project' => 'إنشاء مشروع أو تحديده',
  'Open console.cloud.google.com and log in &rarr; click the Project dropdown (top-left) &rarr; New Project (or pick an existing one) &rarr; enter a name &rarr; Create' => 'افتح console.cloud.google.com وقم بتسجيل الدخول ← انقر على القائمة المنسدلة "المشروع" (أعلى اليسار) ← مشروع جديد (أو اختر مشروعًا موجودًا) ← أدخل اسمًا ← إنشاء',
  'Enable both Google APIs' => 'تمكين كلا واجهتي Google APIs',
  'APIs &amp; Services &rarr; Library &rarr; enable <strong>Google Sheets API</strong> and <strong>Google Drive API</strong> (both are required — Drive lists and creates the files)' => 'واجهات برمجة التطبيقات والخدمات → المكتبة → تمكين<strong>Google Sheets API</strong>و<strong>Google Drive API</strong>(كلاهما مطلوب — قوائم Drive وإنشاء الملفات)',
  'Create a Service Account' => 'إنشاء حساب خدمة',
  'APIs &amp; Services &rarr; Credentials &rarr; Create Credentials &rarr; Service Account &rarr; enter a name &rarr; Done' => 'واجهات برمجة التطبيقات والخدمات → بيانات الاعتماد → إنشاء بيانات الاعتماد → حساب الخدمة → أدخل اسمًا → تم',
  'Create a JSON Key' => 'إنشاء مفتاح JSON',
  'Open the service account &rarr; Keys tab &rarr; Add Key &rarr; Create New Key &rarr; choose JSON (file downloads automatically)' => 'افتح حساب الخدمة ← علامة تبويب المفاتيح ← إضافة مفتاح ← إنشاء مفتاح جديد ← اختر JSON (يتم تنزيل الملف تلقائيًا)',
  'Drop the Key File' => 'أسقط ملف المفتاح',
  'Drag the downloaded file into the Connections tab — it is verified automatically and you’ll see a green “Connected” badge' => 'اسحب الملف الذي تم تنزيله إلى علامة التبويب "الاتصالات" — يتم التحقق منه تلقائيًا وستظهر لك شارة "متصل" باللون الأخضر',
  'Add Your Google Email' => 'أضف بريدك الإلكتروني على Google',
  'On the Connections tab, fill in “Your Google email” and Save — sheets the plugin creates are then shared to you so they appear in your own Drive' => 'في علامة التبويب "الاتصالات"، املأ "بريدك الإلكتروني في Google" ثم احفظ - تتم بعد ذلك مشاركة الأوراق التي ينشئها المكون الإضافي معك حتى تظهر في Drive الخاص بك',
  'Bind a Form (create a sheet)' => 'ربط نموذج (إنشاء ورقة)',
  'Form Bindings &rarr; pick a form &rarr; <strong>Create New Sheet</strong> &rarr; Save. No manual sharing needed — this is the easiest path' => 'ربط النماذج ← اختر نموذجًا ←<strong>إنشاء ورقة جديدة</strong>← حفظ. ليست هناك حاجة للمشاركة اليدوية — هذا هو المسار الأسهل',
  '…or use an existing sheet' => '...أو استخدم ورقة موجودة',
  'Prefer your own sheet? Open it &rarr; Share &rarr; paste the service account email (copy button on its card) &rarr; Editor &rarr; then Browse My Sheets in the wizard' => 'هل تفضل ورقتك الخاصة؟ افتحه ← مشاركة ← الصق البريد الإلكتروني لحساب الخدمة (زر النسخ على بطاقته) ← المحرر ← ثم تصفح أوراقي في المعالج"، \'en\']]',
  'I created a sheet — where did it go?' => 'لقد قمت بإنشاء ورقة — أين ذهبت؟',
  'Service accounts create files in their own hidden Drive. Add “Your Google email” on the Connections tab and the plugin shares every new sheet to you automatically — it then appears under “Shared with me” in your Google Drive. Each sheet also has an “Open” link right in this dashboard.' => 'تنشئ حسابات الخدمة ملفات في محرك الأقراص المخفي الخاص بها. أضف "بريدك الإلكتروني على Google" في علامة التبويب "الاتصالات" وسيشارك المكون الإضافي كل ورقة جديدة لك تلقائيًا - ثم تظهر ضمن "تمت مشاركتها معي" في Google Drive. تحتوي كل ورقة أيضًا على رابط "فتح" مباشرةً في لوحة المعلومات هذه.',
  'Why don’t I see my existing sheet in the picker?' => 'لماذا لا أرى الورقة الموجودة في المنتقي؟',
  'It must be shared with the service account’s email first: open the sheet &rarr; Share &rarr; paste the email (use the copy button on the connection card) &rarr; set Editor &rarr; Share. Then click “Browse My Sheets” again.' => 'يجب مشاركته مع البريد الإلكتروني لحساب الخدمة أولاً: افتح الورقة ← مشاركة ← الصق البريد الإلكتروني (استخدم زر النسخ الموجود على بطاقة الاتصال) ← ضبط المحرر ← مشاركة. ثم انقر فوق "استعراض الأوراق" مرة أخرى.',
  'Test result: Google API is not enabled.' => 'نتيجة الاختبار: لم يتم تمكين Google API.',
  'Open Google Cloud Console for the same project &rarr; APIs &amp; Services &rarr; Library, and enable BOTH “Google Sheets API” and “Google Drive API”. Wait a minute, then retest.' => 'افتح Google Cloud Console لنفس المشروع → واجهات برمجة التطبيقات والخدمات → المكتبة، وقم بتمكين كل من "Google Sheets API" و"Google Drive API". انتظر دقيقة، ثم أعد الاختبار.',
  'Test result: Access/Permission denied' => 'نتيجة الاختبار: تم رفض الوصول/الإذن',
  'The service account can authenticate but can’t reach that specific spreadsheet. Re-share the sheet with the service account email as Editor, or create a new sheet instead.' => 'يمكن لحساب الخدمة المصادقة ولكن لا يمكنه الوصول إلى جدول البيانات المحدد هذا. أعد مشاركة الورقة مع البريد الإلكتروني لحساب الخدمة كمحرر، أو قم بإنشاء ورقة جديدة بدلاً من ذلك.',
  'OpenSSL is required.' => 'مطلوب OpenSSL.',
  'The server is missing the PHP OpenSSL extension used to sign the secure Google request. Ask your host to enable it — no plugin setting can replace it.' => 'يفتقد الخادم ملحق PHP OpenSSL المستخدم لتوقيع طلب Google الآمن. اطلب من مضيفك تمكينه — لا يمكن لأي إعداد إضافي أن يحل محله.',
  'Can I connect more than one service account?' => 'هل يمكنني توصيل أكثر من حساب خدمة واحد؟',
  'Yes — drop as many JSON keys as you like in the Connections tab and pick which one each form binding should use.' => 'نعم — قم بإسقاط أي عدد تريده من مفاتيح JSON في علامة التبويب "الاتصالات" واختر المفتاح الذي يجب أن يستخدمه كل ربط نموذج.',
  'Does the connection expire?' => 'هل تنتهي صلاحية الاتصال؟',
  'No. The integration runs entirely on the server using your JSON key — there’s no browser session or login to expire.' => 'لا. يتم تشغيل التكامل بالكامل على الخادم باستخدام مفتاح JSON الخاص بك - لا توجد جلسة متصفح أو تسجيل دخول لتنتهي صلاحيته.',
  'Can I choose which field goes to which column?' => 'هل يمكنني اختيار الحقل الذي سيتم الانتقال إليه في أي عمود؟',
  'Yes. In the binding wizard’s <strong>Columns &amp; Fields</strong> step, drag rows (or use ▲▼) to set the order, rename each column header, and toggle any field off to skip it. The A/B/C badge shows exactly where each field lands.' => 'نعم. في خطوة<strong>الأعمدة والحقول</strong>الخاصة بمعالج الربط، اسحب الصفوف (أو استخدم ▲▼) لتعيين الترتيب، وأعد تسمية رأس كل عمود، وقم بتبديل أي حقل لتخطيه. تُظهر شارة A/B/C مكان وصول كل حقل بالضبط.',
  'Can I style the sheet automatically?' => 'هل يمكنني تصميم الورقة تلقائياً؟',
  'Yes. The <strong>Style &amp; Save</strong> step offers Google-Sheets themes (colored header, frozen top row, alternating row colors). Pick one and it’s applied on the first sync, or click “Apply style now”.' => 'نعم. توفر خطوة<strong>Style & Save</strong>سمات جداول بيانات Google (الرأس الملون، والصف العلوي المجمد، وألوان الصفوف البديلة). اختر واحدًا وسيتم تطبيقه على المزامنة الأولى، أو انقر فوق "تطبيق النمط الآن".',
  'What if my form fields change later?' => 'ماذا لو تغيرت حقول النموذج الخاصة بي لاحقاً؟',
  'New fields are added automatically. In mapped mode, open the Columns step and click “Refresh fields from form” to pull them into the mapping; in “All Form Fields” mode they appear as new columns on the next submission.' => 'تتم إضافة الحقول الجديدة تلقائياً. في الوضع المعين، افتح خطوة الأعمدة وانقر على "تحديث الحقول من النموذج" لسحبها إلى التعيين؛ في وضع "كافة حقول النموذج"، تظهر كأعمدة جديدة في الإرسال التالي.',
  'What if the tab doesn’t exist yet?' => 'ماذا لو لم تكن علامة التبويب موجودة بعد؟',
  'It is created automatically the first time a submission is synced.' => 'يتم إنشاؤه تلقائيًا عند مزامنة الإرسال لأول مرة.',
  'Google Sheet Sync Logs' => 'سجلات مزامنة أوراق Google',
  'Latest submissions sent to Google Sheets, success or failure' => 'أحدث الإرسالات التي تم إرسالها إلى جداول بيانات Google، سواء كانت ناجحة أم فاشلة',
  'Log cleared.' => 'تم مسح السجل.',
  'Clear Log' => 'مسح السجل',
  'Clear all logs?' => 'هل تريد مسح كافة السجلات؟',
  'No sync activity yet.' => 'لا يوجد أي نشاط مزامنة حتى الآن.',
  'Spreadsheet' => 'جدول بيانات',
  'Synced' => 'متزامن',
  'None (plain)' => 'لا يوجد (عادي)',
  'Minimal' => 'الحد الأدنى',
  'Slate' => 'قائمة',
  'Sunset' => 'غروب الشمس',
  'Grape' => 'العنب',
  '%s is currently unavailable.' => '%s غير متوفر حالياً.',
  'disabled in php.ini: %s' => 'معطل في php.ini: %s',
  'not provided by PHP or its required extension: %s' => 'غير متوفر بواسطة PHP أو ملحقها المطلوب: %s',
  '%1$s cannot run because required PHP functions are unavailable (%2$s). Ask your hosting provider to enable the required PHP extension or remove the listed functions from disable_functions in php.ini.' => ' لا يمكن تشغيل %1$s لأن وظائف PHP المطلوبة غير متوفرة (%2$s). اطلب من موفر الاستضافة تمكين ملحق PHP المطلوب أو إزالة الوظائف المدرجة من Disable_functions في php.ini.',
  'This add-on is not included in Flux Forms.' => 'لم يتم تضمين هذه الوظيفة الإضافية في Flux Forms.',
  'Error: server (%s) responded with an invalid request. responded code : %s ' => 'خطأ: استجاب الخادم (%s) بطلب غير صالح. رمز الرد : %s',
  'Your Easy Form Builder Pro subscription has expired, so this add-on cannot be downloaded.' => 'لقد انتهت صلاحية اشتراكك في Easy Form Builder Pro، لذا لا يمكن تنزيل هذه الوظيفة الإضافية.',
  'Something went wrong, please refresh the page.' => 'حدث خطأ ما، يرجى تحديث الصفحة.',
  'The response attachment could not be verified. Please attach the file again.' => 'تعذر التحقق من مرفق الاستجابة. الرجاء إرفاق الملف مرة أخرى.',
  'You do not have permission to update these settings.' => 'ليس لديك الإذن بتحديث هذه الإعدادات.',
  'Please enter a valid admin email address.' => 'الرجاء إدخال عنوان بريد إلكتروني صالح للمسؤول.',
  'You do not have permission to complete setup.' => 'ليس لديك الإذن بإكمال الإعداد.',
  'Invalid email address' => 'عنوان البريد الإلكتروني غير صالح',
  'Invalid sender email' => 'البريد الإلكتروني للمرسل غير صالح',
  'The sender email address is not valid.' => 'عنوان البريد الإلكتروني للمرسل غير صالح.',
  'Email tester service error' => 'خطأ في خدمة اختبار البريد الإلكتروني',
  'Could not start email test.' => 'تعذر بدء اختبار البريد الإلكتروني.',
  'Invalid service response' => 'استجابة الخدمة غير صالحة',
  'The email tester service returned an invalid response.' => 'أرجعت خدمة اختبار البريد الإلكتروني استجابة غير صالحة.',
  'The message never left your website: WordPress reported an error while trying to send it. This is the one case where the fix really is on the WordPress or hosting side - usually an SMTP plugin, or PHP mail disabled by the host.' => 'لم تغادر الرسالة موقعك على الويب مطلقًا: أبلغ WordPress عن خطأ أثناء محاولة إرسالها. هذه هي الحالة الوحيدة التي يكون فيها الإصلاح على جانب WordPress أو الاستضافة - عادةً ما يكون مكون SMTP الإضافي أو بريد PHP معطلاً بواسطة المضيف.',
  'WordPress could not send the test email. The message never left your website, so nothing was delivered.' => 'تعذر على WordPress إرسال البريد الإلكتروني التجريبي. لم تغادر الرسالة موقعك على الويب مطلقًا، لذلك لم يتم تسليم أي شيء.',
  'Email test is waiting for delivery confirmation' => 'اختبار البريد الإلكتروني في انتظار تأكيد التسليم',
  'WordPress sent the test email. Flux Forms is waiting for the delivery result before marking email as ready.' => 'أرسل WordPress رسالة البريد الإلكتروني التجريبية. ينتظر Flux Forms نتيجة التسليم قبل وضع علامة على البريد الإلكتروني كجاهز.',
  'WordPress accepted and sent the test email. Waiting for it to arrive.' => 'قبل WordPress وأرسل البريد الإلكتروني التجريبي. في انتظار وصوله.',
  'The email tester service returned an invalid JSON response.' => 'أرجعت خدمة اختبار البريد الإلكتروني استجابة JSON غير صالحة.',
  'The email tester service could not start the test.' => 'تعذر على خدمة اختبار البريد الإلكتروني بدء الاختبار.',
  'Invalid test hash' => 'تجزئة الاختبار غير صالحة',
  'The email test hash is not valid.' => 'تجزئة اختبار البريد الإلكتروني غير صالحة.',
  'Your site could not connect' => 'تعذر على موقعك الاتصال',
  'No connection could be opened from your site to our mail testing service. This is usually outbound traffic blocked by your server or its network - some hosts block connections to other countries - rather than a problem with the service. Your hosting provider can confirm it.' => 'لا يمكن فتح اتصال من موقعك بخدمة اختبار البريد لدينا. عادةً ما تكون هذه حركة مرور صادرة محظورة بواسطة خادمك أو شبكته - حيث يقوم بعض المضيفين بحظر الاتصالات إلى بلدان أخرى - وليست مشكلة في الخدمة. يمكن لموفر الاستضافة الخاص بك تأكيد ذلك.',
  'Service error' => 'خطأ في الخدمة',
  'The email tester service could not return the result.' => 'تعذر على خدمة اختبار البريد الإلكتروني إرجاع النتيجة.',
  'The message never left your website. WordPress reported an error while sending, so nothing could be delivered.' => 'لم تغادر الرسالة موقعك على الويب مطلقًا. أبلغ WordPress عن خطأ أثناء الإرسال، لذلك لا يمكن تسليم أي شيء.',
  'The email was sent, but it never arrived' => 'تم إرسال البريد الإلكتروني، لكنه لم يصل مطلقًا',
  'WordPress sent the message successfully, so your site and this plugin did their part. It was lost, delayed or rejected after leaving WordPress - usually the receiving side treated it as spam, or your host never delivered it from the outbound queue.' => 'أرسل WordPress الرسالة بنجاح، لذلك قام موقعك وهذا المكون الإضافي بدورهما. لقد تم فقدها أو تأخيرها أو رفضها بعد مغادرة WordPress - عادةً ما يعاملها الجانب المتلقي كرسالة غير مرغوب فيها، أو لم يسلمها مضيفك مطلقًا من قائمة انتظار البريد الصادر.',
  'Email test failed' => 'فشل اختبار البريد الإلكتروني',
  'The email server test could not verify email capability.' => 'تعذر على اختبار خادم البريد الإلكتروني التحقق من إمكانية البريد الإلكتروني.',
  'Email capability verified' => 'تم التحقق من إمكانية البريد الإلكتروني',
  'Server confirmed ability to send emails.' => 'أكد الخادم قدرته على إرسال رسائل البريد الإلكتروني.',
  'Your emails are being delivered to spam' => 'يتم تسليم رسائل البريد الإلكتروني الخاصة بك إلى البريد العشوائي',
  'WordPress sent the test email, but delivery has not been confirmed yet.' => 'أرسل WordPress رسالة البريد الإلكتروني التجريبية، ولكن لم يتم تأكيد التسليم بعد.',
  'Email delivery failed: %s' => 'فشل تسليم البريد الإلكتروني: %s',
  'No file was received. Please choose a file and try again.' => 'لم يتم استلام أي ملف. الرجاء اختيار ملف والمحاولة مرة أخرى.',
  'The file could not be read. Please try attaching it again.' => 'تعذرت قراءة الملف. الرجاء محاولة إرفاقه مرة أخرى.',
  'Enable the Email Notification Feature' => 'تمكين ميزة الإعلام عبر البريد الإلكتروني',
  'To receive email notifications from your forms, verify your email server by following these steps:' => 'لتلقي إعلامات البريد الإلكتروني من النماذج الخاصة بك، تحقق من خادم البريد الإلكتروني الخاص بك باتباع الخطوات التالية:',
  'Go to the <a href="%s" style="font-weight:600;">Flux Forms Panel</a>' => 'انتقل إلى لوحة نماذج التدفق<a href="%s" style="font-weight:600;"></a>',
  'Click Settings from the top menu' => 'انقر فوق "إعدادات" من القائمة العلوية',
  'Select the Email Settings tab' => 'حدد علامة التبويب إعدادات البريد الإلكتروني',
  'Click "Check Email Server" and wait for the test to finish' => 'انقر فوق "التحقق من خادم البريد الإلكتروني" وانتظر حتى ينتهي الاختبار',
  'If the score is above 70 — enable the "This site can send emails" switch and save' => 'إذا كانت النتيجة أعلى من 70 — قم بتمكين مفتاح التبديل "يمكن لهذا الموقع إرسال رسائل بريد إلكتروني" ثم احفظ',
  'Otherwise, follow the instructions shown in the test results' => 'وإلا، فاتبع الإرشادات الموضحة في نتائج الاختبار',
  '%s notification' => ' إشعار %s',
  'Disabling this feature may affect the proper functionality of Flux Forms. If you plan to use the %s feature, please ensure it is enabled.' => 'قد يؤثر تعطيل هذه الميزة على الأداء الوظيفي المناسب لـ Flux Forms. إذا كنت تخطط لاستخدام ميزة %s، فيرجى التأكد من تمكينها.',
  'Email system is working properly.' => 'نظام البريد الإلكتروني يعمل بشكل صحيح.',
  'Your server is able to send emails using the default PHP mail system.' => 'خادمك قادر على إرسال رسائل البريد الإلكتروني باستخدام نظام بريد PHP الافتراضي.',
  'Email system is not available.' => 'نظام البريد الإلكتروني غير متوفر.',
  'The PHP mail() function is missing. Your server cannot send emails.' => 'وظيفة PHP mail() مفقودة. لا يمكن لخادمك إرسال رسائل البريد الإلكتروني.',
  'Email sending is blocked by server settings.' => 'تم حظر إرسال البريد الإلكتروني بواسطة إعدادات الخادم.',
  'The mail() function is disabled in your server PHP configuration (php.ini).' => 'وظيفة mail() معطلة في تكوين PHP للملقم الخاص بك (php.ini).',
  'WordPress mail function not found.' => 'لم يتم العثور على وظيفة بريد WordPress.',
  'The wp_mail() function is missing or not available. WordPress email features may be broken.' => 'وظيفة wp_mail() مفقودة أو غير متوفرة. قد تكون ميزات البريد الإلكتروني في WordPress معطلة.',
  'No email handler configured.' => 'لم يتم تكوين معالج البريد الإلكتروني.',
  'Your server has no SMTP host or sendmail path set. Emails may not be delivered.' => 'لا يحتوي الملقم لديك على مضيف SMTP أو مسار إرسال البريد. قد لا يتم تسليم رسائل البريد الإلكتروني.',
  'Test email could not be sent.' => 'تعذر إرسال البريد الإلكتروني التجريبي.',
  'It seems that your WordPress site could not send a test email. To manually test your email system, go to Flux Forms > Settings > Email Settings tab and click the "Check Email Server" button.' => 'يبدو أن موقع WordPress الخاص بك لم يتمكن من إرسال بريد إلكتروني تجريبي. لاختبار نظام البريد الإلكتروني يدويًا، انتقل إلى Flux Forms > الإعدادات > علامة التبويب إعدادات البريد الإلكتروني وانقر فوق الزر "التحقق من خادم البريد الإلكتروني".',
  'Invalid email address.' => 'عنوان البريد الإلكتروني غير صالح.',
  'Please enter a valid admin email address before testing email delivery.' => 'الرجاء إدخال عنوان بريد إلكتروني صالح للمسؤول قبل اختبار تسليم البريد الإلكتروني.',
  'Invalid sender email.' => 'البريد الإلكتروني للمرسل غير صالح.',
  'The sender email address is not valid. Please check your email settings.' => 'عنوان البريد الإلكتروني للمرسل غير صالح. الرجاء التحقق من إعدادات البريد الإلكتروني الخاص بك.',
  'Email tester service error.' => 'خطأ في خدمة اختبار البريد الإلكتروني.',
  'Flux Forms could not start the email delivery test. Please try again later.' => 'تعذر على Flux Forms بدء اختبار تسليم البريد الإلكتروني. الرجاء المحاولة مرة أخرى لاحقاً.',
  'Invalid email tester response.' => 'استجابة اختبار البريد الإلكتروني غير صالحة.',
  'Invalid email test.' => 'اختبار البريد الإلكتروني غير صالح.',
  'The email test identifier is invalid. Please start a new test.' => 'معرّف اختبار البريد الإلكتروني غير صالح. الرجاء بدء اختبار جديد.',
  'Email tester connection error.' => 'خطأ في اتصال مختبر البريد الإلكتروني.',
  'Flux Forms could not connect to the email tester service.' => 'تعذر على Flux Forms الاتصال بخدمة اختبار البريد الإلكتروني.',
  'Email delivery test failed.' => 'فشل اختبار تسليم البريد الإلكتروني.',
  'Your emails are arriving in the spam folder.' => 'تصل رسائل البريد الإلكتروني الخاصة بك إلى مجلد الرسائل غير المرغوب فيها.',
  'The test message was delivered, but its deliverability score is too low to rely on. Sending through SMTP and adding SPF and DKIM records for your domain is what fixes this.' => 'تم تسليم رسالة الاختبار، ولكن درجة تسليمها منخفضة للغاية بحيث لا يمكن الاعتماد عليها. إن الإرسال عبر SMTP وإضافة سجلات SPF وDKIM للمجال الخاص بك هو ما يحل هذه المشكلة.',
  'Email delivery test is pending.' => 'اختبار تسليم البريد الإلكتروني معلق.',
  'Email Issue' => 'مشكلة في البريد الإلكتروني',
  'Flux Forms Email Warning:' => 'تحذير عبر البريد الإلكتروني لنماذج التدفق:',
  'Plan data is missing.' => 'بيانات الخطة مفقودة.',
  'Invalid plan data format.' => 'تنسيق بيانات الخطة غير صالح.',
  'Invalid plan type.' => 'نوع الخطة غير صالح.',
  'Please confirm this plan downgrade before continuing.' => 'الرجاء تأكيد الرجوع إلى إصدار سابق من هذه الخطة قبل المتابعة.',
  'Free plan activated - no additional features.' => 'تم تفعيل الخطة المجانية - لا توجد ميزات إضافية.',
