  'System Ready' => 'النظام جاهز',
  'Checking add-on installation capabilities&hellip;' => 'يتم التحقق من إمكانيات تثبيت الوظائف الإضافية...',
  'This check runs once after plugin activation. Please refresh the page in a few moments.' => 'يتم تنفيذ هذا الفحص مرة واحدة بعد تنشيط المكون الإضافي. الرجاء تحديث الصفحة خلال لحظات قليلة.',
  'Some add-ons need a PHP server change' => 'تحتاج بعض الوظائف الإضافية إلى تغيير خادم PHP',
  'Flux Forms has safely paused each affected active add-on, so the rest of the plugin can continue working.' => 'لقد قام Flux Forms بإيقاف كل وظيفة إضافية نشطة متأثرة مؤقتًا بشكل آمن، بحيث يمكن لبقية المكون الإضافي مواصلة العمل.',
  '(currently enabled and paused)' => '(ممكّن ومتوقف مؤقتًا حاليًا)',
  '(not enabled)' => '(غير ممكّن)',
  'disabled in php.ini:' => 'معطل في php.ini:',
  'not provided by PHP or its required extension:' => 'غير متوفر بواسطة PHP أو ملحقها المطلوب:',
  'This usually means the needed PHP extension is not installed, or the function is listed in disable_functions in php.ini. Please ask your hosting provider to enable it, then refresh this page.' => 'يعني هذا عادة أن ملحق PHP المطلوب غير مثبت، أو أن الوظيفة مدرجة في Disable_functions في php.ini. الرجاء مطالبة موفر الاستضافة بتمكينه، ثم قم بتحديث هذه الصفحة.',
  'If you are seeing this message, it is likely for one of these reasons: If you have a caching plugin installed, its settings may need to be reviewed.' => 'إذا كنت ترى هذه الرسالة، فمن المحتمل أن يكون ذلك لأحد الأسباب التالية: إذا كان لديك مكون إضافي للتخزين المؤقت مثبتاً، فقد تحتاج إعداداته إلى المراجعة.',
  'Please also ensure that you have a stable internet connection and try again.' => 'يُرجى أيضًا التأكد من توفر اتصال ثابت بالإنترنت والمحاولة مرة أخرى.',
  'Built with %sYT Form%s by %sWordPress form plugin by whitestudio.team%s' => 'تم إنشاؤه باستخدام نموذج%sYT%sبواسطة المكون الإضافي لنموذج WordPress%sبواسطة Whitestudio.team%s',
