  'Powered by %1$sYT Form%2$s . %3$sbest Form plugin for Wordpress%4$s.' => 'مدعوم من %1$sYT Form%2$s.%3$sأفضل مكون إضافي للنموذج في Wordpress%4$s.',
  'Flux Forms WordPress Plugin' => 'مكوّن Flux Forms WordPress الإضافي',
  'This form requires a payment method. Please add one or change the form type.' => 'يتطلب هذا النموذج طريقة دفع. الرجاء إضافة واحد أو تغيير نوع النموذج.',
