  'This panel is only visible to site administrators.' => 'هذه اللوحة مرئية فقط لمسؤولي الموقع.',
  'jQuery Dependency Issue' => 'jمشكلة تبعية الاستعلام',
  'jQuery is not properly loaded or available. AJAX and interactive form features may not work correctly.' => 'jلم يتم تحميل الاستعلام أو توفره بشكل صحيح. قد لا تعمل ميزات AJAX والنماذج التفاعلية بشكل صحيح.',
  'WhiteStudio.team' => 'WhiteStudio.team',
  'EFB' => 'EFB',
  'Flux Forms is a free and powerful WordPress form builder plugin for creating contact forms, payment forms, surveys, registration forms, multi-step forms, file upload forms, electronic signature forms, and audio, video, and screen recording forms, with conditional logic, email notifications, integrations, entry management, and advanced spam protection.' => 'Flux Forms عبارة عن مكون إضافي مجاني وقوي لإنشاء نماذج WordPress لإنشاء نماذج الاتصال ونماذج الدفع والاستطلاعات ونماذج التسجيل والنماذج متعددة الخطوات ونماذج تحميل الملفات ونماذج التوقيع الإلكتروني ونماذج تسجيل الصوت والفيديو والشاشة، مع المنطق الشرطي وإشعارات البريد الإلكتروني وعمليات التكامل وإدارة الإدخال والحماية المتقدمة من البريد العشوائي.',
