  'Elementor form plugin' => 'المكون الإضافي لنموذج العنصر',
  'Divi form plugin' => 'المكوّن الإضافي لنموذج Divi',
  'WPBakery form plugin' => 'المكوّن الإضافي لنموذج WPBakery',
  'Some plugin files are missing, so the plugin stopped loading to keep your site running. Please reinstall Flux Forms from the Plugins page — your forms, messages, and settings are kept.' => 'بعض ملفات المكونات الإضافية مفقودة، لذا توقف تحميل المكونات الإضافية للحفاظ على تشغيل موقعك. الرجاء إعادة تثبيت Flux Forms من صفحة المكونات الإضافية - يتم الاحتفاظ بالنماذج والرسائل والإعدادات الخاصة بك.',
  'Missing files:' => 'الملفات المفقودة:',
  'Select a form to display from the dropdown below.' => 'حدد نموذجاً لعرضه من القائمة المنسدلة أدناه.',
  'Selected Form:' => 'النموذج المحدد:',
  'Form will be displayed here on the frontend.' => 'سيتم عرض النموذج هنا على الواجهة الأمامية.',
  'Loading forms&hellip;' => 'جاري تحميل النماذج...',
  '📍 Confirmation Code Finder (Tracking Form)' => '📍 الباحث عن رمز التأكيد (نموذج التتبع)',
  'Choose a form to display. The tracking form allows users to find submissions by confirmation code.' => 'اختر نموذجًا لعرضه. يسمح نموذج التتبع للمستخدمين بالعثور على الإرسالات بواسطة رمز التأكيد.',
  'Show Form Title' => 'إظهار عنوان النموذج',
  'Container' => 'حاوية',
  'Border Radius' => 'نصف القطر الحدودي',
  'Box Shadow' => 'ظل الصندوق',
  'Select a form from the widget settings panel.' => 'حدد نموذجًا من لوحة إعدادات عنصر واجهة المستخدم.',
  '👈 Use the sidebar to choose a form' => '👈 استخدم الشريط الجانبي لاختيار النموذج\'، \'tr\']]',
  'Selected Form ID:' => 'معرّف النموذج المحدد:',
  'The form will appear here on the frontend.' => 'سيظهر النموذج هنا على الواجهة الأمامية.',
  'Display an Flux Forms form' => 'عرض نموذج Flux Forms',
  'Display the form name as a heading above the form.' => 'عرض اسم النموذج كعنوان أعلى النموذج.',
  'Extra Class Name' => 'اسم الفئة الإضافية',
  'Add custom CSS classes for styling.' => 'أضف فئات CSS مخصصة للتصميم.',
  'Design' => 'التصميم',
  'CSS' => 'CSS',
  'Select a form from the element settings.' => 'حدد نموذجاً من إعدادات العنصر.',
  '✏️ Click to edit and choose a form' => '✏️ انقر لتعديل النموذج واختياره',
  'Add forms created with Flux Forms' => 'إضافة نماذج تم إنشاؤها باستخدام Flux Forms',
  'Display Flux Forms forms on your page' => 'عرض نماذج Flux Forms على صفحتك',
  'Choose the form you want to display' => 'اختر النموذج الذي تريد عرضه',
  'Please select a form from element settings' => 'الرجاء تحديد نموذج من إعدادات العناصر',
  'Form: %s (ID: %s)' => 'النموذج: %s(المعرف: %s)',
  '📍 Confirmation Code Finder (Tracking)' => '📍 الباحث عن رمز التأكيد (التتبع)',
  '🎨 Flux Forms' => '🎨 نماذج التدفق',
  'Add Flux Forms forms to your page' => 'أضف نماذج Flux Forms إلى صفحتك',
  'Select Form:' => 'حدد النموذج:',
  'Custom Title (optional):' => 'عنوان مخصص (اختياري):',
  'Shortcode:' => 'الرمز القصير:',
  'Run the email check' => 'قم بتشغيل فحص البريد الإلكتروني',
  'The last delivery check scored %s out of 100. Your messages do leave the site, but most mailboxes will file them as spam, so the people filling in your forms will not see them. Sending through an SMTP service, and adding SPF and DKIM records for your domain, is what fixes this.' => 'سجل فحص التسليم الأخير %s من أصل 100. تغادر رسائلك الموقع، ولكن معظم صناديق البريد ستسجلها كرسائل غير مرغوب فيها، وبالتالي لن يراها الأشخاص الذين يملؤون النماذج الخاصة بك. إن الإرسال عبر خدمة SMTP وإضافة سجلات SPF وDKIM للمجال الخاص بك هو ما يحل هذه المشكلة.',
  'The last delivery check found that your messages do leave the site, but mailboxes file them as spam. Sending through an SMTP service, and adding SPF and DKIM records for your domain, is what fixes this.' => 'أظهر فحص التسليم الأخير أن رسائلك تغادر الموقع، لكن صناديق البريد تسجلها كرسائل غير مرغوب فيها. إن الإرسال عبر خدمة SMTP وإضافة سجلات SPF وDKIM للمجال الخاص بك هو ما يحل هذه المشكلة.',
  'Your form emails are going to the spam folder' => 'ستنتقل رسائل البريد الإلكتروني النموذجية الخاصة بك إلى مجلد الرسائل غير المرغوب فيها',
  'Your form emails are sent, but they are not arriving' => 'تم إرسال رسائل البريد الإلكتروني للنموذج الخاص بك، لكنها لا تصل',
  'WordPress sent the last test message successfully, so your site and this plugin did their part - it was lost, delayed or rejected after leaving WordPress. Usually the receiving mailbox treated it as spam, or your host never delivered it from the outbound queue. Sending through an SMTP service, with SPF and DKIM records for your domain, is what fixes this.' => 'أرسل WordPress آخر رسالة اختبارية بنجاح، لذلك قام موقعك وهذا المكون الإضافي بدورهما - فقد تم فقده أو تأخيره أو رفضه بعد مغادرة WordPress. عادةً ما يعاملها صندوق البريد المتلقي على أنها بريد عشوائي، أو أن المضيف الخاص بك لم يسلمها مطلقًا من قائمة انتظار البريد الصادر. إن الإرسال عبر خدمة SMTP، مع سجلات SPF وDKIM للمجال الخاص بك، هو ما يحل هذه المشكلة.',
  'WordPress cannot send your form emails' => 'لا يمكن لـ WordPress إرسال رسائل البريد الإلكتروني للنموذج الخاص بك',
  'The last check could not even hand a message to your mail server: WordPress reported an error while sending, so nothing left the site. An SMTP plugin, or asking your host whether PHP mail is disabled, is where to start.' => 'لم يتمكن الفحص الأخير حتى من تسليم رسالة إلى خادم البريد الخاص بك: أبلغ WordPress عن خطأ أثناء الإرسال، لذلك لم يبق أي شيء في الموقع. من أين تبدأ، مكون SMTP الإضافي، أو سؤال مضيفك عما إذا كان بريد PHP معطلاً.',
  'Your form emails are not being delivered' => 'لا يتم تسليم رسائل البريد الإلكتروني النموذجية الخاصة بك',
  'The last delivery check could not get a message through, so nothing your forms send is reaching anybody. A hosting server usually sends mail without a trusted signature; sending through an SMTP service is the standard fix.' => 'تعذر على فحص التسليم الأخير استلام الرسالة، لذا لا يصل أي شيء ترسله النماذج إلى أي شخص. عادةً ما يرسل خادم الاستضافة البريد بدون توقيع موثوق به؛ الإرسال عبر خدمة SMTP هو الحل القياسي.',
  'Once Weekly (Flux Forms)' => 'مرة واحدة أسبوعيًا (نماذج التدفق)',
  'The weekly email delivery test completed successfully.' => 'تم إكمال اختبار تسليم البريد الإلكتروني الأسبوعي بنجاح.',
  'The weekly email delivery test found an email delivery problem.' => 'لقد اكتشف اختبار تسليم البريد الإلكتروني الأسبوعي وجود مشكلة في تسليم البريد الإلكتروني.',
  'The main WordPress administrator email address is not valid.' => 'عنوان البريد الإلكتروني الرئيسي لمسؤول WordPress غير صالح.',
  'Could not start the email delivery test.' => 'تعذر بدء اختبار تسليم البريد الإلكتروني.',
  'WordPress sent the automated test email and is waiting for it to arrive.' => 'أرسل WordPress رسالة بريد إلكتروني تجريبية تلقائية وهو في انتظار وصولها.',
  'WordPress could not send the automated test email. The message never left this website.' => 'تعذر على WordPress إرسال البريد الإلكتروني التجريبي الآلي. لم تغادر الرسالة موقع الويب هذا مطلقًا.',
  'The email delivery test timed out before confirmation was received.' => 'انتهت مهلة اختبار تسليم البريد الإلكتروني قبل استلام التأكيد.',
  'Weekly Flux Forms report for %s' => 'تقرير Flux Forms الأسبوعي لـ%s',
  'Here is your weekly snapshot for %s.' => 'هذه هي اللقطة الأسبوعية لـ%s.',
  'Report generated %s' => 'تم إنشاء التقرير %s',
  'Detailed analysis' => 'تحليل تفصيلي',
  'Emails failed' => 'فشلت رسائل البريد الإلكتروني',
  'You can turn these reports off in Flux Forms settings.' => 'يمكنك إيقاف تشغيل هذه التقارير في إعدادات Flux Forms.',
  'The test email was delivered, but its deliverability score is only %1$s out of 100 (below %2$s), so the emails your forms send are very likely to be rejected or filtered as spam.' => 'تم تسليم البريد الإلكتروني التجريبي، ولكن درجة التسليم الخاصة به هي %1$s فقط من أصل 100 (أقل من %2$s)، لذلك من المحتمل جدًا أن يتم رفض رسائل البريد الإلكتروني التي ترسلها النماذج أو تصفيتها كرسائل غير مرغوب فيها.',
  'Run the email check so you can be sure the messages your forms send are actually reaching people. The check sends a real message through the new WhiteStudio delivery service and reports back what arrived.' => 'قم بتشغيل فحص البريد الإلكتروني حتى تتأكد من أن الرسائل التي ترسلها نماذجك تصل بالفعل إلى الأشخاص. يرسل الشيك رسالة حقيقية من خلال خدمة تسليم WhiteStudio الجديدة ويبلغ بما وصل.',
  'Read the guide to sending email through SMTP' => 'اقرأ دليل إرسال البريد الإلكتروني عبر SMTP',
  'Delivery has not been scored yet' => 'لم يتم تسجيل التسليم بعد',
  'WordPress sent your email, but it never arrived' => 'أرسل WordPress بريدك الإلكتروني، لكنه لم يصل مطلقًا',
  'WordPress could not send your email' => 'تعذر على WordPress إرسال بريدك الإلكتروني',
  'We could not confirm your emails are being delivered' => 'لم نتمكن من تأكيد تسليم رسائل البريد الإلكتروني الخاصة بك',
  'out of 100' => 'من 100',
  'Your email delivery is healthy' => 'تسليم بريدك الإلكتروني سليم',
  'Your emails are likely going to spam' => 'من المحتمل أن تصل رسائل البريد الإلكتروني الخاصة بك إلى رسائل غير مرغوب فيها',
  'Your emails are not reaching anybody' => 'رسائل البريد الإلكتروني الخاصة بك لا تصل إلى أي شخص',
  'grade %s' => 'درجة %s',
  'What you should do' => 'ما يجب عليك فعله',
  'A hosting server usually sends mail without a trusted signature, which is what pushes your form emails into the spam folder or stops them arriving at all. The standard fix is to send through an SMTP service.' => 'يرسل خادم الاستضافة عادةً بريدًا بدون توقيع موثوق به، وهو ما يدفع رسائل البريد الإلكتروني النموذجية الخاصة بك إلى مجلد البريد العشوائي أو يمنعها من الوصول على الإطلاق. الإصلاح القياسي هو الإرسال عبر خدمة SMTP.',
  'Install an SMTP plugin and enter the details of your email service.' => 'قم بتثبيت مكون SMTP الإضافي وأدخل تفاصيل خدمة البريد الإلكتروني لديك.',
  'Add the SPF and DKIM records to your domain settings.' => 'أضف سجلات SPF وDKIM إلى إعدادات المجال لديك.',
  'Run the email check again until the score is above %s.' => 'قم بتشغيل فحص البريد الإلكتروني مرة أخرى حتى تصبح النتيجة أعلى من %s.',
  'You have %1$s forms: %2$s active and %3$s inactive.' => 'لديك نماذج %1$s: %2$s نشط و %3$s غير نشط.',
  'Renew Flux Forms Pro' => 'تجديد Flux Forms Pro',
  'Get more from Flux Forms Pro' => 'احصل على المزيد من Flux Forms Pro',
  'Renew your subscription to restore all Pro features and add-ons.' => 'قم بتجديد اشتراكك لاستعادة كافة ميزات Pro والوظائف الإضافية.',
  'Unlock premium add-ons, unlimited features and priority support for your forms.' => 'احصل على الوظائف الإضافية المميزة والميزات غير المحدودة والدعم ذي الأولوية للنماذج الخاصة بك.',
  'Renew Pro' => 'تجديد النسخة الاحترافية',
  'Email delivery is working' => 'تسليم البريد الإلكتروني يعمل',
  'The automated Flux Forms email delivery test completed successfully.' => 'اكتمل اختبار تسليم البريد الإلكتروني التلقائي لـ Flux Forms بنجاح.',
  'You can attach up to %1$d file here. Please wait about %2$d minutes before trying again.' . chr(0) . 'You can attach up to %1$d files here. Please wait about %2$d minutes before trying again.' => 'يمكنك إرفاق ما يصل إلى ملفات %1$d هنا. يرجى الانتظار حوالي %2$d دقيقة قبل المحاولة مرة أخرى.' . chr(0) . 'يمكنك إرفاق ما يصل إلى ملف %1$d هنا. يرجى الانتظار حوالي %2$d دقيقة قبل المحاولة مرة أخرى.' . chr(0) . 'يمكنك إرفاق ما يصل إلى ملفات %1$d هنا. يرجى الانتظار حوالي %2$d دقيقة قبل المحاولة مرة أخرى.' . chr(0) . 'يمكنك إرفاق ما يصل إلى ملفات %1$d هنا. يرجى الانتظار حوالي %2$d دقيقة قبل المحاولة مرة أخرى.' . chr(0) . 'يمكنك إرفاق ما يصل إلى ملفات %1$d هنا. يرجى الانتظار حوالي %2$d دقيقة قبل المحاولة مرة أخرى.' . chr(0) . 'يمكنك إرفاق ما يصل إلى ملفات %1$d هنا. يرجى الانتظار حوالي %2$d دقيقة قبل المحاولة مرة أخرى.',
  'This file is too large. The maximum size for this field is %s.' => 'هذا الملف كبير جدًا. الحد الأقصى لحجم هذا الحقل هو %s.',
  'This file type is not accepted here. Please attach one of the file types listed on the field.' => 'نوع الملف هذا غير مقبول هنا. الرجاء إرفاق أحد أنواع الملفات المدرجة في الحقل.',
  'This file appears to be empty. Please choose a different file.' => 'يبدو أن هذا الملف فارغ. الرجاء اختيار ملف مختلف.',
  'The uploaded file could not be verified. Please attach it again.' => 'تعذر التحقق من الملف الذي تم تحميله. الرجاء إرفاقه مرة أخرى.',
  'X-WP-Nonce header is missing' => 'رأس X-WP-Nonce مفقود',
  'Your form session has expired. Please reload the page.' => 'لقد انتهت صلاحية جلسة النموذج الخاصة بك. الرجاء إعادة تحميل الصفحة.',
  'Form ID:' => 'معرّف النموذج:',
  'The form will be displayed on the frontend.' => 'سيتم عرض النموذج على الواجهة الأمامية.',
  'This link uses an older format. For improved security, new email notifications include updated links.' => 'يستخدم هذا الارتباط تنسيقًا قديمًا. لتحسين الأمان، تتضمن إعلامات البريد الإلكتروني الجديدة ارتباطات محدثة.',
  'It seems that you are the admin of this form. Please log in and try again.' => 'يبدو أنك المسؤول عن هذا النموذج. الرجاء تسجيل الدخول والمحاولة مرة أخرى.',
  'Flux Forms couldn\'t locate the form settings. Please check your settings or contact support for assistance.' => 'تعذر على Flux Forms تحديد إعدادات النموذج. الرجاء التحقق من إعداداتك أو الاتصال بالدعم للحصول على المساعدة.',
  'Y/m/d \\a\\t g:ia' => 'Y/m/d \\a\\t g:ia',
  'Too many attempts. Please wait a few minutes and try again.' => 'محاولات كثيرة جدًا. الرجاء الانتظار بضع دقائق ثم حاول مرة أخرى.',
  'The recording upload could not be verified. Please record it again and retry.' => 'تعذر التحقق من تحميل التسجيل. الرجاء تسجيله مرة أخرى ثم إعادة المحاولة.',
  'This recording format is not supported. Please record it again.' => 'تنسيق التسجيل هذا غير معتمد. الرجاء تسجيله مرة أخرى.',
  'The server could not verify the recording format. Please contact the site administrator.' => 'تعذر على الملقم التحقق من تنسيق التسجيل. الرجاء الاتصال بمسؤول الموقع.',
  'The recording format could not be verified. Please record it again.' => 'تعذر التحقق من تنسيق التسجيل. الرجاء تسجيله مرة أخرى.',
  'The server could not verify the recording duration. Please record it again and try uploading.' => 'تعذر على الملقم التحقق من مدة التسجيل. الرجاء تسجيله مرة أخرى ومحاولة التحميل.',
  'The server could not store the recording. Please try again or contact the site administrator.' => 'تعذر على الملقم تخزين التسجيل. الرجاء المحاولة مرة أخرى أو الاتصال بمسؤول الموقع.',
  'The recording request could not be verified. Please retry.' => 'تعذر التحقق من طلب التسجيل. يرجى إعادة المحاولة.',
  'The upload request could not be verified. Please try again.' => 'تعذر التحقق من طلب التحميل. الرجاء المحاولة مرة أخرى.',
  'The upload field could not be verified. Please refresh the form and try again.' => 'تعذر التحقق من حقل التحميل. الرجاء تحديث النموذج والمحاولة مرة أخرى.',
  'The response box could not be verified. Reopen the conversation and try again.' => 'تعذر التحقق من مربع الاستجابة. أعد فتح المحادثة وحاول مرة أخرى.',
  'The response attachment could not be secured. Please try again.' => 'تعذر تأمين مرفق الاستجابة. الرجاء المحاولة مرة أخرى.',
  'Not allowed to respond to this message.' => 'غير مسموح له بالرد على هذه الرسالة.',
  'Payment Intent ID is missing' => 'معرف وجهة الدفع مفقود',
  'persiaPayment' => 'الدفع الفارسي',
  'The Email Address Is Not Valid' => 'عنوان البريد الإلكتروني غير صالح',
  'The Username Must Contain Only Letters, Numbers And Lowercase letters' => 'يجب أن يحتوي اسم المستخدم على أحرف وأرقام وأحرف صغيرة فقط',
  'The Username Must Contain At Least 3 Characters.' => 'يجب أن يحتوي اسم المستخدم على 3 أحرف على الأقل.',
  'The Password Must Contain At Least 8 Characters!' => 'يجب أن تحتوي كلمة المرور على 8 أحرف على الأقل!',
  'The Password Must Contain At Least 1 Number!' => 'يجب أن تحتوي كلمة المرور على رقم واحد على الأقل!',
  'The Password Must Contain At Least 1 Capital Letter!' => 'يجب أن تحتوي كلمة المرور على حرف واحد كبير على الأقل!',
  'The Password Must Contain At Least 1 Lowercase Letter!' => 'يجب أن تحتوي كلمة المرور على حرف واحد صغير على الأقل!',
  'Audio recording' => 'تسجيل صوتي',
  'Video recording' => 'تسجيل فيديو',
  'Screen recording' => 'تسجيل الشاشة',
  'Form Preview' => 'معاينة النموذج',
  'Create New Password' => 'إنشاء كلمة مرور جديدة',
  'Create a secure password for your account' => 'قم بإنشاء كلمة مرور آمنة لحسابك',
  'New Password' => 'كلمة المرور الجديدة',
  'Enter your new password' => 'أدخل كلمة المرور الجديدة',
  'Set Password' => 'تعيين كلمة المرور',
  'Error! Please try again later.' => 'خطأ! الرجاء المحاولة مرة أخرى لاحقاً.',
  'Password has been changed successfully!' => 'تم تغيير كلمة المرور بنجاح!',
  'Invalid payment selection. Please review your choices and try again. If the problem persists, contact the site administrator.' => 'اختيار الدفع غير صالح. يرجى مراجعة اختياراتك والمحاولة مرة أخرى. إذا استمرت المشكلة، اتصل بمسؤول الموقع.',
  'If your emails are not being delivered, try using an SMTP plugin. For more information, %1$s click here %2$s or contact our %3$s support team %4$s.' => 'إذا لم يتم تسليم رسائل البريد الإلكتروني الخاصة بك، فحاول استخدام مكون SMTP الإضافي. لمزيد من المعلومات، %1$s انقر هنا %2$s أو اتصل بفريق دعم %3$s%4$s.',
  'View Messages' => 'عرض الرسائل',
  'Hello!' => 'مرحبا!',
  'New Message' => 'رسالة جديدة',
  'New message received' => 'تم استلام رسالة جديدة',
  'We received your message' => 'لقد تلقينا رسالتك',
  'This email was sent automatically. Please do not reply.' => 'تم إرسال هذه الرسالة الإلكترونية تلقائيًا. الرجاء عدم الرد.',
  'Built with %1$sYT Form%2$s by %3$sWhiteStudio.team%4$s' => 'تم إنشاؤه باستخدام نموذج %1$sYT%2$s بواسطة %3$sWhiteStudio.team%4$s',
  'Weekly Flux Forms report' => 'تقرير نماذج التدفق الأسبوعي',
  'Pro features are paused' => 'الميزات الاحترافية متوقفة مؤقتًا',
  'Congratulations! Email System Working' => 'تهانينا! نظام البريد الإلكتروني يعمل',
  'Your server has successfully sent this test email. The email delivery system is properly configured and functioning.' => 'لقد نجح الخادم الخاص بك في إرسال رسالة البريد الإلكتروني التجريبية هذه. تم تكوين نظام تسليم البريد الإلكتروني ويعمل بشكل صحيح.',
  'Email Delivery Tips' => 'نصائح حول تسليم البريد الإلكتروني',
  'Form submitted successfully without tracking.' => 'تم إرسال النموذج بنجاح دون تعقب.',
  'Your message has been received and recorded successfully.' => 'تم استلام رسالتك وتسجيلها بنجاح.',
  'Reset Password' => 'إعادة تعيين كلمة المرور',
  'Or copy and paste this link:' => 'أو انسخ هذا الارتباط والصقه:',
  'If you did not request this, you can safely ignore it.' => 'إذا لم تطلب ذلك، فيمكنك تجاهله بأمان.',
  'Hi' => 'مرحبا',
  'You have requested to reset your password.' => 'لقد طلبت إعادة تعيين كلمة المرور الخاصة بك.',
  'Click the button below to set a new password. This link will be valid for 24 hours.' => 'انقر فوق الزر أدناه لتعيين كلمة مرور جديدة. سيكون هذا الارتباط صالحًا لمدة 24 ساعة.',
  'Verify Email' => 'التحقق من البريد الإلكتروني',
  'Your account has been successfully created!' => 'تم إنشاء حسابك بنجاح!',
  'Please verify your email address by clicking the button below. This activation link will be valid for 24 hours.' => 'الرجاء التحقق من عنوان بريدك الإلكتروني بالنقر فوق الزر أدناه. سيكون ارتباط التنشيط هذا صالحًا لمدة 24 ساعة.',
  'A new user has registered on your website.' => 'تم تسجيل مستخدم جديد في موقعك على الويب.',
  'The user has been sent a verification email to confirm their account.' => 'تم إرسال رسالة تحقق إلى المستخدم لتأكيد حسابه.',
  'This is an alert message regarding a SID validation error. This issue may have occurred due to a plugin conflict or an unauthorized attempt to access the website.' => 'هذه رسالة تنبيه بخصوص خطأ في التحقق من صحة SID. ربما حدثت هذه المشكلة بسبب تعارض في البرنامج الإضافي أو محاولة غير مصرح بها للوصول إلى موقع الويب.',
  'If you receive this email multiple times, it could indicate a recurring issue.' => 'إذا تلقيت هذا البريد الإلكتروني عدة مرات، فقد يشير ذلك إلى مشكلة متكررة.',
  'Please contact our support team for assistance.' => 'الرجاء الاتصال بفريق الدعم للحصول على المساعدة.',
  'One or more of the plugins listed below—typically related to caching or security—might be triggering this issue. For troubleshooting, temporarily deactivate them and test your site.' => 'ربما يكون واحد أو أكثر من المكونات الإضافية المدرجة أدناه — المرتبطة عادةً بالتخزين المؤقت أو الأمان — هو الذي يسبب هذه المشكلة. لاستكشاف الأخطاء وإصلاحها، قم بإلغاء تنشيطها مؤقتًا واختبر موقعك.',
  'SID Validation Error' => 'خطأ في التحقق من صحة SID',
  'Please select a form to display.' => 'الرجاء تحديد نموذج لعرضه.',
  'Sürükle-bırak form oluşturucu: çok adımlı formlar, Stripe ödemeleri, koşullu mantık, dashboard, otomasyonlar ve Flux Certificates entegrasyonu. Easy Form Builder (WhiteStudio, GPL) tabanlı fork.' => 'أداة إنشاء نماذج السحب والإفلات: نماذج متعددة الخطوات، والمدفوعات الشريطية، والمنطق الشرطي، ولوحة المعلومات، والأتمتة، وتكامل شهادات التدفق. الشوكة مبنية على Easy Form Builder (WhiteStudio, GPL).',
  'The currency of this form is not supported.' => 'عملة هذا النموذج غير مدعومة.',
  'The Stripe secret key is not configured.' => 'لم يتم تكوين المفتاح السري Stripe.',
  'Could not connect to Stripe: %s' => 'تعذر الاتصال بـ Stripe: %s',
  'Stripe API error (HTTP %d).' => 'خطأ في Stripe API (HTTP %d).',
  'Type your reply...' => 'اكتب ردك...',
  'height' => 'الارتفاع',
  'Checking email delivery...' => 'جارٍ التحقق من تسليم البريد الإلكتروني...',
  'A test email was sent. Waiting for delivery confirmation...' => 'تم إرسال بريد إلكتروني تجريبي. في انتظار تأكيد التسليم...',
  'Adds your form activity totals – forms, views and submissions – to the weekly email your site sends the main administrator. These totals are read on your own site and are never sent to WhiteStudio.' => 'يضيف إجمالي نشاط النموذج - النماذج وطرق العرض والإرسالات - إلى البريد الإلكتروني الأسبوعي الذي يرسله موقعك إلى المسؤول الرئيسي. تتم قراءة هذه الإجماليات على موقعك الخاص ولا يتم إرسالها مطلقًا إلى WhiteStudio.',
  'A value is written to this field while another rule hides or disables it — hidden and disabled fields are not saved with the entry.' => 'تتم كتابة قيمة في هذا الحقل بينما تقوم قاعدة أخرى بإخفائها أو تعطيلها — لا يتم حفظ الحقول المخفية والمعطلة مع الإدخال.',
  'Message...' => 'الرسالة...',
  'hide' => 'إخفاء',
  'Uploading recording...' => 'جاري تحميل التسجيل...',
  'Got it, don\'t show it again' => 'فهمت، لا تعرضه مرة أخرى',
  'Your text here...' => 'النص الخاص بك هنا...',
  'Waiting for the test email to arrive...' => 'في انتظار وصول البريد الإلكتروني التجريبي...',
  'Still checking — please wait a moment...' => 'لا يزال التحقق — الرجاء الانتظار قليلاً...',
  'Starting email delivery test...' => 'بدء اختبار تسليم البريد الإلكتروني...',
  'WordPress accepted and sent the message. Waiting for it to arrive...' => 'قبل ووردبريس الرسالة وأرسلها. في انتظار وصوله...',
  'turkey' => 'تركيا',
  'bug report' => 'تقرير الأخطاء',
  'kosher' => 'كوشير',
  'banner' => 'شعار',
  'Installing add-ons...' => 'تثبيت الوظائف الإضافية...',
  'Your forms, entries and settings are untouched, every free feature keeps working, and your activation code is still stored — nothing was deleted.' => 'لم يتم تغيير النماذج والإدخالات والإعدادات الخاصة بك، وستستمر كل الميزات المجانية في العمل، ولا يزال رمز التنشيط الخاص بك مخزّنًا - ولم يتم حذف أي شيء.',
  'Open %1$sYT Form → Settings%2$s and press %1$sSave%2$s. That checks the licence again straight away; if the connection is back, Pro switches on within a minute.' => 'افتح نموذج %1$sYT → الإعدادات%2$s واضغط على %1$sحفظ%2$s. يقوم ذلك بالتحقق من الترخيص مرة أخرى على الفور؛ إذا عاد الاتصال، فسيتم تشغيل Pro خلال دقيقة.',
  'Still paused? Ask your hosting provider to allow outgoing HTTPS connections to %s — a firewall, proxy or regional block is the usual cause — then repeat step 1.' => 'هل ما زالت متوقفة مؤقتًا؟ اطلب من موفر الاستضافة السماح باتصالات HTTPS الصادرة بـ%s— جدار الحماية أو الوكيل أو الحظر الإقليمي هو السبب المعتاد — ثم كرر الخطوة 1.',
  'grace period' => 'فترة السماح',
  'Your website could not reach the licence server — almost always a network, firewall or DNS restriction on the hosting side.' => 'تعذر على موقع الويب الخاص بك الوصول إلى خادم الترخيص — غالبًا ما يكون هناك قيود على الشبكة أو جدار الحماية أو DNS من جانب الاستضافة.',
  'The licence server’s answer arrived damaged, usually because a security plugin, proxy or CDN changed it on the way.' => 'وصلت إجابة خادم الترخيص تالفة، وذلك عادةً بسبب قيام مكون إضافي للأمان أو وكيل أو CDN بتغييرها في الطريق.',
  'Updating amount...' => 'جاري تحديث المبلغ...',
  'Keys are set;%dform uses reCAPTCHA.%dforms use reCAPTCHA.' => 'تم ضبط المفاتيح; يستخدم نموذج %dreCAPTCHA. تستخدم نماذج %dreCAPTCHA.',
  'Preparing your certificate...' => 'جاري تحضير شهادتك...',
  'Search elements...' => 'عناصر البحث...',
  'Enter your test message here...' => 'أدخل رسالتك الاختبارية هنا...',
  'Type your message here...' => 'اكتب رسالتك هنا...',
  'Testing connection...' => 'جارٍ اختبار الاتصال...',
  'Saving...' => 'جاري الحفظ...',
  'Loading...' => 'جاري التحميل...',
  'To sync an<strong>existing</strong>sheet: open it in Google Sheets →<strong>Share</strong>→ paste the email above → set role to<strong>Editor</strong>. To create a<strong>new</strong>sheet, just use Form Bindings — no sharing needed.' => 'لمزامنة ورقة<strong>موجودة في</strong>: افتحها في جداول بيانات Google ←<strong>شارك</strong>← الصق البريد الإلكتروني أعلاه ← اضبط الدور على<strong>Editor</strong>. لإنشاء ورقة<strong>جديدة</strong>، ما عليك سوى استخدام روابط النماذج — لا حاجة للمشاركة.',
  'Go to<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a>→ Project dropdown (top-left) → New Project → name it → Create' => 'انتقل إلى<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a>→ القائمة المنسدلة للمشروع (أعلى اليسار) → مشروع جديد → قم بتسميته → إنشاء',
  'APIs & Services → Library → enable<strong>Google Sheets API</strong><em>and</em><strong>Google Drive API</strong>' => 'واجهات برمجة التطبيقات والخدمات → المكتبة → تمكين<strong>Google Sheets API</strong><em>و</em><strong>Google Drive API</strong>',
  'APIs & Services → Credentials → Create Credentials → Service Account → name it → Done' => 'واجهات برمجة التطبيقات والخدمات → بيانات الاعتماد → إنشاء بيانات الاعتماد → حساب الخدمة → قم بتسميته → تم',
  'Open the service account → Keys tab → Add Key → Create New Key → JSON (downloads automatically)' => 'افتح حساب الخدمة ← علامة تبويب المفاتيح ← إضافة مفتاح ← إنشاء مفتاح جديد ← JSON (يتم التنزيل تلقائيًا)',
  'Connecting service account...' => 'جارٍ توصيل حساب الخدمة...',
  'tab' => 'علامة التبويب',
  'Loading your spreadsheets...' => 'جارٍ تحميل جداول البيانات...',
  '<strong>Use an existing sheet:</strong>open it in Google Sheets → Share → paste' => '<strong>استخدم ورقة موجودة:</strong>افتحها في جداول بيانات Google → مشاركة → لصق',
  '→ Editor, then click<em>Browse My Sheets</em>again.' => '→ المحرر، ثم انقر فوق<em>"استعراض الأوراق الخاصة بي"</em>مرة أخرى.',
  'Creating...' => 'جارٍ الإنشاء...',
  'Creating spreadsheet...' => 'جاري إنشاء جدول بيانات...',
  'Loading worksheet tabs...' => 'جاري تحميل علامات تبويب أوراق العمل...',
  'Reading this form’s fields...' => 'قراءة حقول هذا النموذج...',
  'Drag rows (or use ▲▼) to set the<strong>column order</strong>. Rename any<strong>header</strong>. Turn a field off to skip its column. The letter (A, B, C...) shows where each field lands.' => 'اسحب الصفوف (أو استخدم ▲▼) لتعيين ترتيب الأعمدة<strong></strong>. إعادة تسمية أي رأس<strong></strong>. قم بإيقاف تشغيل الحقل لتخطي العمود الخاص به. يُظهر الحرف (A، B، C...) مكان وصول كل حقل.',
  'Applying...' => 'جارٍ التقديم...',
  'Open console.cloud.google.com and log in → click the Project dropdown (top-left) → New Project (or pick an existing one) → enter a name → Create' => 'افتح console.cloud.google.com وقم بتسجيل الدخول ← انقر على القائمة المنسدلة "المشروع" (أعلى اليسار) ← مشروع جديد (أو اختر مشروعًا موجودًا) ← أدخل اسمًا ← إنشاء',
  'APIs & Services → Library → enable<strong>Google Sheets API</strong>and<strong>Google Drive API</strong>(both are required — Drive lists and creates the files)' => 'واجهات برمجة التطبيقات والخدمات → المكتبة → تمكين<strong>Google Sheets API</strong>و<strong>Google Drive API</strong>(كلاهما مطلوب — قوائم Drive وإنشاء الملفات)',
  'APIs & Services → Credentials → Create Credentials → Service Account → enter a name → Done' => 'واجهات برمجة التطبيقات والخدمات → بيانات الاعتماد → إنشاء بيانات الاعتماد → حساب الخدمة → أدخل اسمًا → تم',
  'Open the service account → Keys tab → Add Key → Create New Key → choose JSON (file downloads automatically)' => 'افتح حساب الخدمة ← علامة تبويب المفاتيح ← إضافة مفتاح ← إنشاء مفتاح جديد ← اختر JSON (يتم تنزيل الملف تلقائيًا)',
  'Form Bindings → pick a form →<strong>Create New Sheet</strong>→ Save. No manual sharing needed — this is the easiest path' => 'ربط النماذج ← اختر نموذجًا ←<strong>إنشاء ورقة جديدة</strong>← حفظ. ليست هناك حاجة للمشاركة اليدوية — هذا هو المسار الأسهل',
  '...or use an existing sheet' => '...أو استخدم ورقة موجودة',
  'Prefer your own sheet? Open it → Share → paste the service account email (copy button on its card) → Editor → then Browse My Sheets in the wizard' => 'هل تفضل ورقتك الخاصة؟ افتحه ← مشاركة ← الصق البريد الإلكتروني لحساب الخدمة (زر النسخ على بطاقته) ← المحرر ← ثم تصفح أوراقي في المعالج"، \'en\']]',
  'It must be shared with the service account’s email first: open the sheet → Share → paste the email (use the copy button on the connection card) → set Editor → Share. Then click “Browse My Sheets” again.' => 'يجب مشاركته مع البريد الإلكتروني لحساب الخدمة أولاً: افتح الورقة ← مشاركة ← الصق البريد الإلكتروني (استخدم زر النسخ الموجود على بطاقة الاتصال) ← ضبط المحرر ← مشاركة. ثم انقر فوق "استعراض الأوراق" مرة أخرى.',
  'Open Google Cloud Console for the same project → APIs & Services → Library, and enable BOTH “Google Sheets API” and “Google Drive API”. Wait a minute, then retest.' => 'افتح Google Cloud Console لنفس المشروع → واجهات برمجة التطبيقات والخدمات → المكتبة، وقم بتمكين كل من "Google Sheets API" و"Google Drive API". انتظر دقيقة، ثم أعد الاختبار.',
  'Yes. In the binding wizard’s<strong>Columns & Fields</strong>step, drag rows (or use ▲▼) to set the order, rename each column header, and toggle any field off to skip it. The A/B/C badge shows exactly where each field lands.' => 'نعم. في خطوة<strong>الأعمدة والحقول</strong>الخاصة بمعالج الربط، اسحب الصفوف (أو استخدم ▲▼) لتعيين الترتيب، وأعد تسمية رأس كل عمود، وقم بتبديل أي حقل لتخطيه. تُظهر شارة A/B/C مكان وصول كل حقل بالضبط.',
  'Yes. The<strong>Style & Save</strong>step offers Google-Sheets themes (colored header, frozen top row, alternating row colors). Pick one and it’s applied on the first sync, or click “Apply style now”.' => 'نعم. توفر خطوة<strong>Style & Save</strong>سمات جداول بيانات Google (الرأس الملون، والصف العلوي المجمد، وألوان الصفوف البديلة). اختر واحدًا وسيتم تطبيقه على المزامنة الأولى، أو انقر فوق "تطبيق النمط الآن".',
  'synchronized' => 'متزامن',
  '%1$s cannot run because required PHP functions are unavailable (%2$s). Ask your hosting provider to enable the required PHP extension or remove the listed functions from disabled_functions in php.ini.' => ' لا يمكن تشغيل %1$s لأن وظائف PHP المطلوبة غير متوفرة (%2$s). اطلب من موفر الاستضافة تمكين ملحق PHP المطلوب أو إزالة الوظائف المدرجة من Disable_functions في php.ini.',
  'Checking add-on installation capabilities...' => 'يتم التحقق من إمكانيات تثبيت الوظائف الإضافية...',
